import{n as e,t}from"./helpers-0sYvox5E.js";var n=[t({id:`blueprint-hall-001`,building:`blueprint-hall`,bullets:[`2.1-K4`],d:1,stem:`A company runs a web application on Amazon EC2 instances in an Auto Scaling group. The architects want servers to be replaced at will without causing an availability impact. Which design principle BEST meets this requirement?`,correct:[`Make the application stateless by offloading state, so requests need no data stored on an instance`,`A stateless design leaves no dependence on locally stored data on disk or in memory, so any server can be replaced at will.`],wrong:[[`Keep each visitor's session data in the memory of the instance that first served the visitor`,`State held in instance memory is lost when that instance is replaced, which creates the availability impact.`],[`Store the working data of each user on the local disk of the instance that handles the requests of that user`,`Data on a local disk is tied to one server, so replacing the server removes the data.`],[`Schedule instance replacements only during the lowest-traffic hours of the week`,`Servers still could not be replaced at will, and the state held on them would still be lost.`]],slot:0,evidence:[`waf-stateless|Systems should either not require state, or should offload state such that between different client requests, there is no dependence on locally stored data on disk and in memory.`,`waf-stateless|This allows servers to be replaced at will without causing an availability impact.`]}),t({id:`blueprint-hall-002`,building:`blueprint-hall`,bullets:[`2.1-K4`],d:2,stem:`A retail web application runs on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer. Shopping cart contents are held in the memory of each instance, so customers lose their carts when the group scales in. Any instance must be able to serve any customer, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Offload the cart data to an Amazon ElastiCache cache that all instances read from and write to`,`Session data is offloaded to an in-memory cache, so no instance holds state and any instance can serve any customer.`],wrong:[[`Enable sticky sessions on the target group so that each customer keeps returning to the same instance`,`Sticky sessions bind a session to one target, so the cart still lives on that instance and is lost when the instance is removed.`],[`Raise the minimum size of the Auto Scaling group so that scale-in events rarely occur`,`Instances can still fail or be replaced, and the application would still depend on state held on one server.`],[`Copy the cart data to the Amazon EBS root volume of each instance after every request`,`The data stays local to each instance, so another instance cannot serve the customer and the state is lost on replacement.`]],slot:1,evidence:[`waf-stateless|Offload session data to a database, cache, or external files.`,`msa-data-store|Popular stores for session data are in-memory caches such as Memcached or Redis.`,`alb-target-attrs|you can use the sticky session feature (also known as session affinity) to enable the load balancer to bind a user's session to a specific target.`]}),e({id:`blueprint-hall-003`,building:`blueprint-hall`,bullets:[`2.1-K4`],d:2,stem:`A company hosts a photo-sharing web application on Amazon EC2 instances behind an Application Load Balancer. Each instance keeps uploaded photos and user sessions on its own disk, which prevents horizontal scaling. Any instance must be able to serve any request. Which TWO actions BEST meet these requirements? (Choose two.)`,correct:[[`Store the uploaded photos in Amazon S3 and have the application retrieve them when needed`,`Large unstructured data such as images is kept in Amazon S3 instead of on the instance, so no photo depends on one server.`],[`Move the user session data to an Amazon ElastiCache cache that every instance uses`,`Offloading session data to a cache removes the session state from the instances, so any instance can service any request.`]],wrong:[[`Increase the instance size of every web server in the Auto Scaling group`,`A larger instance still holds its own state locally, so the application still cannot scale horizontally.`],[`Enable sticky sessions on the load balancer so each user always reaches the same instance`,`Sticky sessions bind a user to one target, so requests still depend on which instance they reach.`],[`Attach an additional Amazon EBS volume to each instance for photo storage`,`A volume attached to one instance is still local data, so only that instance can serve the photos.`]],slots:[1,3],evidence:[`waf-stateless|Consider using Amazon S3 to store large, unstructured data, such as images and documents.`,`waf-stateless|Offload session data to a database, cache, or external files.`,`waf-stateless|they can scale horizontally because any of the available compute resources (such as EC2 instances and AWS Lambda functions) can service any request.`]}),t({id:`blueprint-hall-004`,building:`blueprint-hall`,bullets:[`2.1-K4`],d:2,stem:`A company is splitting a monolithic order system into microservices owned by separate teams. All services still read and write one shared Amazon RDS database, and every schema change must be coordinated across the teams. The company wants each service to be developed and deployed independently. Which approach is MOST aligned with microservices design principles?`,correct:[`Give each microservice its own data store and let the services exchange data through their APIs`,`Each component of a microservices application maintains its own data, which promotes independence and decentralization.`],wrong:[[`Keep the shared database and add one read replica endpoint for each team to use`,`All services would still depend on the same data and schema, so the teams remain coupled.`],[`Keep the shared database and put a dedicated in-memory cache in front of it for each of the services`,`A cache reduces read load but leaves the shared schema, so teams still cannot change their data independently.`],[`Move the shared database to a larger instance class so that every service has more capacity`,`More capacity does not remove the shared schema, so schema changes still need coordination across teams.`]],slot:2,evidence:[`msa-distributed-data|In traditional applications, all components often share a single database.`,`msa-distributed-data|In contrast, each component of a microservices-based application maintains its own data, promoting independence and decentralization.`,`waf-loose-coupling|Loosely coupled systems should avoid sharing data through shared databases or other forms of tightly coupled data storage, which can reintroduce tight coupling and hinder scalability.`]}),t({id:`blueprint-hall-005`,building:`blueprint-hall`,bullets:[`2.1-K4`,`2.1-S1`],d:3,stem:`An order microservice, a payment microservice and an inventory microservice each keep their own database. One business operation spans all three, and if the payment step fails the stock that the inventory service already reserved must be released. The company wants the services to keep their data separate. Which design BEST handles this failure?`,correct:[`Use the Saga pattern, with a coordinator that runs compensating actions to undo the completed steps`,`The Saga pattern coordinates a series of compensating actions, so completed work is undone while each service keeps its own data.`],wrong:[[`Merge the tables of all three services into one database so that a single transaction can roll back`,`A shared database removes the independence of the services, which the company wants to keep.`],[`Let the inventory service read the payment database directly to detect failed payments`,`Reading another service's data store couples the services and does not coordinate undoing the completed steps.`],[`Retry the failed payment step without limit so that no earlier step ever has to be undone`,`Retries cannot guarantee success, so a permanently failed step still leaves completed work that must be undone.`]],slot:3,evidence:[`msa-distributed-data|Sometimes, business operations require multiple microservices to work together.`,`msa-distributed-data|If one part fails, you might have to undo some completed tasks.`,`msa-distributed-data|The Saga pattern helps manage this by coordinating a series of compensating actions.`]}),t({id:`blueprint-hall-006`,building:`blueprint-hall`,bullets:[`2.1-K4`],d:3,stem:`A company is building a microservice that stores and retrieves device profiles by a single key. The service does one thing, needs no table joins, and receives large activity spikes of short duration that make capacity planning difficult. The company wants the data store that needs the LEAST capacity planning. Which solution meets these requirements?`,correct:[`An Amazon DynamoDB table that uses on-demand capacity`,`A simplified data model suits NoSQL, and on-demand capacity serves requests instantly without capacity planning.`],wrong:[[`An Amazon DynamoDB table with provisioned throughput set to the typical daily load`,`Provisioned throughput must be planned in advance, which is hard when spikes are large and short.`],[`An Amazon RDS for MySQL DB instance sized for the peak load, with one read replica`,`A relational instance sized for peak still needs capacity planning, and the service has no need for joins.`],[`An Amazon RDS for PostgreSQL Multi-AZ DB instance that is resized after each spike`,`Resizing after each spike is manual capacity planning and reacts too late for short spikes.`]],slot:0,evidence:[`msa-data-store|Because individual microservices are designed to do one thing well, they typically have a simplified data model that might be well suited to NoSQL persistence.`,`msa-data-store|However, there are cases where capacity planning is difficult or not possible because of large activity spikes of short duration in your application.`,`msa-data-store|DynamoDB on-demand is capable of serving thousands of requests per second instantly without capacity planning.`]}),t({id:`blueprint-hall-007`,building:`blueprint-hall`,bullets:[`2.1-K10`],d:1,stem:`A company is designing a three-tier web application. The presentation tier is a set of static files and a JavaScript single-page application that calls backend APIs. The company wants to serve the presentation tier with no web servers to manage and with no code that runs for each file request. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Store the files in Amazon S3 and serve them through Amazon CloudFront`,`Static web content can be served from Amazon S3 and Amazon CloudFront, so no web servers are needed.`],wrong:[[`Run a web server on Amazon EC2 instances in an Auto Scaling group that serves the files`,`The company would have to patch and manage the instances, which it wants to avoid.`],[`Run a web server in AWS Fargate containers that serves the files from the image`,`Containers still need a web server to build, deploy and maintain, which the company wants to avoid.`],[`Return each file from an AWS Lambda function behind an Amazon API Gateway API`,`This runs function code for every file request, which the company wants to avoid, and adds a function and an API to maintain.`]],slot:1,evidence:[`msa-ui|Modern web applications often use JavaScript frameworks to develop single-page applications that communicate with backend APIs.`,`msa-ui|Static web content can be served using Amazon Simple Storage Service (Amazon S3) and Amazon CloudFront.`]}),t({id:`blueprint-hall-008`,building:`blueprint-hall`,bullets:[`2.1-K10`],d:1,stem:`A company is designing the data tier of a three-tier order system. The data consists of structured business objects, and the team needs to join several tables with queries instead of writing join logic in the application. Which data store BEST fits this data tier?`,correct:[`A relational database on Amazon RDS`,`Relational databases are popular for structured data and business objects, and they allow tables to be joined.`],wrong:[[`Amazon DynamoDB tables with a partition key`,`DynamoDB cannot join tables, so the join logic would have to be implemented in the application.`],[`An in-memory Amazon ElastiCache cluster`,`A cache sits between the application servers and a database to reduce read load, and it is not the data tier itself.`],[`Objects stored in an Amazon S3 bucket`,`S3 stores objects and does not run queries that join tables the way a relational database does.`]],slot:2,evidence:[`msa-data-store|Relational databases are still very popular to store structured data and business objects.`,`msa-data-store|It is important to understand that NoSQL databases have different access patterns than relational databases.`,`msa-data-store|If this is necessary, the logic has to be implemented in the application.`]}),t({id:`blueprint-hall-009`,building:`blueprint-hall`,bullets:[`2.1-K10`],d:2,stem:`The application servers of a three-tier application repeatedly read the same product-catalog records from an Amazon RDS database. Database read load is high and page latency is rising. The company wants to reduce the read load on the database and improve latency. Which solution meets these requirements MOST effectively?`,correct:[`Place an Amazon ElastiCache cache between the application servers and the database`,`A cache between the application servers and a database reduces the read load on the database and can improve latency.`],wrong:[[`Convert the database to a Multi-AZ DB instance deployment and read from the standby`,`The standby of a Multi-AZ DB instance deployment cannot serve read traffic.`],[`Raise the maximum size of the Auto Scaling group so that more application servers run`,`More application servers would send even more read queries to the same database.`],[`Put an Application Load Balancer between the application servers and the database`,`A load balancer distributes traffic across targets and does not keep copies of frequently read records.`]],slot:3,evidence:[`msa-data-store|Putting a cache between application servers and a database is a common mechanism for reducing the read load on the database, which, in turn, may allow resources to be used to support more writes.`,`msa-data-store|Caches can also improve latency.`,`rds-multi-az-instance|You can't use a standby replica to serve read traffic.`]}),e({id:`blueprint-hall-010`,building:`blueprint-hall`,bullets:[`2.1-K10`,`2.1-S1`],d:3,stem:`A company runs a three-tier web application. The web servers also serve large static assets, the application tier is one large Amazon EC2 instance that is saturated at peak, and the Amazon RDS database is overloaded by repeated reads. The company wants each tier to scale independently and to be MOST resilient to the loss of an Availability Zone. Which THREE changes meet these requirements? (Choose three.)`,correct:[[`Run the application tier in an Auto Scaling group across Availability Zones behind an Application Load Balancer`,`With scaling policies, the Auto Scaling group can launch instances as demand increases, and it distributes the desired capacity across the Availability Zones you specify. If one zone becomes unavailable, the load balancer can route traffic to healthy targets in another zone.`],[`Place an Amazon ElastiCache cache between the application tier and the database`,`Putting a cache between application servers and a database is a common mechanism for reducing the read load on the database, which relieves the repeated reads that overload it.`],[`Serve the static assets from Amazon S3 through Amazon CloudFront`,`Static content leaves the web servers, so the presentation tier no longer has to scale with asset traffic.`]],wrong:[[`Move the web, application and database tiers onto one larger Amazon EC2 instance`,`One instance cannot scale each tier independently, and it is a single point of failure for all the tiers, which AWS design principles avoid.`],[`Resize the single application instance to the largest available instance type`,`Scaling one instance up keeps the tier on one server in one place, and AWS design principles avoid single points of failure.`],[`Run a database copy on each application server to avoid network calls to the data tier`,`Copies on each server mix the data into the application servers instead of separating it from the core application logic, so the tiers no longer scale independently.`]],slots:[0,3,5],evidence:[`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`,`asg-groups|When instances are launched, if you specified multiple Availability Zones, the desired capacity is distributed across these Availability Zones.`,`elb-how-it-works|If one Availability Zone becomes unavailable or has no healthy targets, the load balancer can route traffic to the healthy targets in another Availability Zone.`,`elb-what-is|Elastic Load Balancing automatically distributes your incoming traffic across multiple targets, such as EC2 instances, containers, and IP addresses, in one or more Availability Zones.`,`msa-data-store|Putting a cache between application servers and a database is a common mechanism for reducing the read load on the database, which, in turn, may allow resources to be used to support more writes.`,`msa-ui|Static web content can be served using Amazon Simple Storage Service (Amazon S3) and Amazon CloudFront.`,`waf-multi-location|A fundamental principle for service design in AWS is to avoid single points of failure, including the underlying physical infrastructure.`,`waf-stateless|Decouple data by separating and managing user data from the core application logic.`]}),t({id:`blueprint-hall-011`,building:`blueprint-hall`,bullets:[`2.1-K10`,`2.1-S1`],d:2,stem:`A web tier calls an application tier synchronously over HTTP to generate PDF reports. During traffic spikes the application tier is overwhelmed and the web tier returns errors, although users do not need the report immediately. The company wants spikes in one tier to stop failing the other with the LEAST rework. Which solution BEST meets these requirements?`,correct:[`Add an Amazon SQS queue between the tiers and have the application tier take requests at its own pace`,`An intermediate queue makes the interaction asynchronous and buffers requests, so spikes no longer fail the web tier.`],wrong:[[`Raise the idle timeout of the load balancer so that the web tier waits much longer for every slow response from the application tier`,`The web tier would still depend on an immediate response, and a saturated application tier would still fail requests.`],[`Add a second Application Load Balancer in front of the same application tier`,`The calls remain synchronous, so the application tier is still overwhelmed during spikes.`],[`Move the application tier to one larger Amazon EC2 instance that can absorb the spikes`,`One larger instance has a fixed limit and the direct, synchronous coupling between the tiers remains.`]],slot:0,evidence:[`waf-loose-coupling|To further improve resiliency through loose coupling, make component interactions asynchronous where possible.`,`waf-loose-coupling|Directly invoking APIs between workload tiers with no capability of failover or asynchronous processing of the request.`,`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`]}),t({id:`blueprint-hall-012`,building:`blueprint-hall`,bullets:[`2.1-S1`],d:2,stem:`When a customer places an order, the inventory, billing and shipping services must each react to it. The order service should not know which services consume the event, and new consumers must be added without changing it. The company wants the MOST loosely coupled design with the LEAST custom code. Which solution meets these requirements?`,correct:[`Publish an order-placed event to an Amazon EventBridge event bus and let each service subscribe with its own rule`,`An event router filters and pushes events to consumers, so the producer stays decoupled and consumers can be added without custom code.`],wrong:[[`Have the order service call each downstream service's Amazon API Gateway endpoint in turn`,`The order service would know every consumer and need code changes whenever a consumer is added.`],[`Have each downstream service poll the order database on a schedule for new rows`,`Polling needs custom code in every service and couples each of them to the order database.`],[`Merge the services into one application on a single Amazon EC2 instance that makes in-process calls between the modules`,`One application with in-process calls is tightly coupled and cannot be updated or scaled independently.`]],slot:1,evidence:[`eda-overview|Producer services and consumer services are decoupled, which allows them to be scaled, updated, and deployed independently.`,`eda-overview|You no longer need to write custom code to poll, filter, and route events; the event router will automatically filter and push events to consumers.`]}),e({id:`blueprint-hall-013`,building:`blueprint-hall`,bullets:[`2.1-S1`,`2.1-K4`],d:2,stem:`A start-up is building a stateless microservices backend that must follow serverless principles: no infrastructure to provision or manage, and capacity that scales automatically with use. The team wants the LEAST operational overhead. Which TWO compute options meet these requirements? (Choose two.)`,correct:[[`AWS Lambda functions`,`Lambda is a serverless compute service that suits stateless services, with no servers to provision or manage.`],[`AWS Fargate to run the containers of the services`,`Fargate is a serverless compute option for containers, so there are no instances to provision or manage.`]],wrong:[[`Amazon EC2 instances in an Auto Scaling group that the team patches`,`The team must still provision and manage instances, which breaks the serverless principle of no infrastructure to manage.`],[`A cluster of self-managed Amazon EC2 container instances`,`The team would manage and patch the instances that host the containers.`],[`Amazon EC2 Dedicated Hosts that run the services`,`Dedicated Hosts are physical servers that the team provisions and manages.`]],slots:[2,3],evidence:[`msa-whitepaper|Serverless is characterized by the following principles: No infrastructure to provision or manage Automatically scaling by unit of consumption "Pay for value" billing model Built-in availability and fault tolerance Event Driven Architecture (EDA)`,`waf-stateless|Once designed to be stateless, you can then use serverless compute services, such as AWS Lambda or AWS Fargate.`]}),t({id:`blueprint-hall-014`,postGuide:[`eventbridge-pipes`],building:`blueprint-hall`,bullets:[`2.1-S1`],d:3,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A company builds an order system with event sourcing: every change is recorded as an event, which creates a timeline of system state for auditing and lets several parts of the application react to the same events. The company needs a central event store and durable storage for all event records. Which combination of AWS services BEST meets these requirements?`,correct:[`Amazon Kinesis Data Streams as the central event store and Amazon S3 for durable storage of the event records`,`Kinesis Data Streams can serve as the central event store, several applications can consume it independently, and S3 stores the records durably.`],wrong:[[`An Amazon SQS standard queue as the event store and Amazon EBS snapshots for durable storage`,`Consumers delete a message after processing it, so a queue does not keep a timeline that several parts can react to.`],[`An Amazon SNS topic as the central event store and Amazon S3 for the durable storage of the event records`,`An SNS topic delivers messages to subscribers and is not an event store that keeps the timeline of events.`],[`An Amazon EventBridge pipe as the event store and Amazon ElastiCache for durable storage`,`A pipe connects one source to one target and does not store events, and an in-memory cache is not durable storage for all records.`]],slot:2,evidence:[`msa-distributed-data|Every change in the application is recorded as an event, creating a timeline of the system's state.`,`msa-distributed-data|As you can see in Figure 7, Amazon Kinesis Data Streams can serve as your central event store, while Amazon S3 provides a durable storage for all event records.`,`kinesis-streams|Multiple Kinesis Data Streams applications can consume data from a stream, so that multiple actions, like archiving and processing, can take place concurrently and independently.`]}),t({id:`blueprint-hall-015`,building:`blueprint-hall`,bullets:[`2.1-K4`,`2.1-S1`],d:2,tags:[`mock-reserve`],stem:`A three-person team is building an internal tool with low, predictable traffic and a simple domain. A colleague proposes splitting it into many microservices from the start. Which guidance from AWS is MOST appropriate for this decision?`,correct:[`Weigh scale, complexity and the use case, because a monolith or another approach can be more appropriate`,`AWS says the choice between microservices and a monolith is made case by case, and alternatives may be more appropriate.`],wrong:[[`Always choose microservices, because they are the only architecture that can scale`,`AWS does not say microservices always win, and it says other approaches may be more appropriate in some cases.`],[`Always choose a monolith for teams of fewer than five people, whatever the use case`,`AWS recommends deciding case by case on scale, complexity and use case, not by a fixed team size.`],[`Choose microservices only if the application already uses a relational database in the data tier of the design`,`The data store is not the deciding factor, and AWS points to scale, complexity and use case.`]],slot:3,evidence:[`msa-whitepaper|Monolithic architecture or alternative approaches may be more appropriate in some cases.`,`msa-whitepaper|Deciding between microservices or monoliths should be made on a case-by-case basis, considering factors like scale, complexity, and specific use cases.`]}),t({id:`blueprint-hall-016`,building:`blueprint-hall`,bullets:[`2.1-K4`,`2.1-K10`],d:3,tags:[`mock-reserve`],stem:`The web tier of a three-tier application keeps session data in instance memory and relies on Application Load Balancer sticky sessions. The company wants to run the web tier on Amazon EC2 Spot Instances to reduce cost, without logging users out when an instance is interrupted. Which solution meets these requirements MOST cost-effectively?`,correct:[`Move the session data to an Amazon ElastiCache cache and run the stateless web tier on Spot Instances`,`With state offloaded, an interrupted instance loses no sessions, and Spot Instances suit applications that can be interrupted.`],wrong:[[`Keep the sticky sessions and lengthen the duration of the stickiness cookie on the load balancer target group`,`Stickiness still binds each session to one instance, and an interrupted instance takes its sessions with it.`],[`Keep the session data in memory and run the web tier on Spot Instances with a larger instance type`,`A larger instance is still interrupted when capacity is needed back, and its memory is lost with it.`],[`Move the session data to the local disk of each Spot Instance so that it survives restarts`,`Local disk data is tied to the instance and does not move to another instance when one is interrupted.`]],slot:0,evidence:[`waf-stateless|A stateless architecture decouples user data and offloads the session data.`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`,`alb-target-attrs|you can use the sticky session feature (also known as session affinity) to enable the load balancer to bind a user's session to a specific target.`]})],r=[t({id:`cache-edge-breakwater-001`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`],d:1,stem:`A company serves product images through an Amazon CloudFront distribution with an Amazon S3 bucket as the origin. The images almost never change. The company wants to reduce the number of requests that reach the origin and speed up delivery to viewers. What should the company do?`,correct:[`Increase the cache duration for the images`,`A longer cache duration makes it more likely that files are served from the edge location and reduces the load on the origin.`],wrong:[[`Set the cache duration for the images to zero`,`A duration of zero makes every request go back to the origin, which increases the load that the company wants to reduce.`],[`Invalidate all of the images every hour`,`Every invalidated file is fetched from the origin again, which creates origin requests that a longer cache duration avoids.`],[`Add a second S3 bucket as an additional origin for the same images`,`A second origin does not keep copies at the edge locations, so viewers are not served faster and requests still reach an origin.`]],slot:0,tags:[`trap:cloudfront-vs-global-accelerator`],evidence:[`cloudfront-expiration|Increasing the duration means that your users get better performance because your files are more likely to be served directly from the edge cache.`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`]}),t({id:`cache-edge-breakwater-002`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`],d:2,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A company runs a multiplayer game on Network Load Balancers in two AWS Regions. Players connect over UDP. Partner firewalls must allow-list a small fixed set of IP addresses, and traffic must move quickly to the healthy Region if one fails. Which solution BEST meets these requirements?`,correct:[`Create an AWS Global Accelerator accelerator with both Network Load Balancers as endpoints`,`An accelerator provides static anycast IP addresses as the entry point, handles UDP, and routes only to healthy regional endpoints.`],wrong:[[`Create an Amazon CloudFront distribution with both Network Load Balancers as origins`,`CloudFront speeds up web content with caching at edge locations, while this need is fixed addresses and fast failover for UDP game traffic.`],[`Create Amazon Route 53 failover records that point to the DNS names of the two load balancers`,`DNS answers can be cached by client devices and resolvers for long periods, and the load balancer addresses are not a fixed set.`],[`Place a Gateway Load Balancer in each Region in front of the game servers`,`A Gateway Load Balancer deploys virtual appliances and does not give clients fixed addresses or fail traffic over between Regions.`]],slot:1,evidence:[`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`,`ga-faq|AWS Global Accelerator automatically checks the health of your applications and routes user traffic only to healthy application endpoints.`,`ga-faq|Some client devices and internet resolvers cache DNS answers for long periods of time.`]}),t({id:`cache-edge-breakwater-003`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`],d:2,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A company hosts a static website in an Amazon S3 bucket. Visitors around the world report slow loading of images and scripts, and many visitors request the same files. The company wants the lowest latency for repeat visits with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an Amazon CloudFront distribution that uses the S3 bucket as its origin`,`Files are cached at edge locations close to viewers, so repeat requests are answered at the edge instead of from the bucket.`],wrong:[[`Create an AWS Global Accelerator accelerator that uses the S3 bucket as its endpoint`,`The endpoints of a standard accelerator are load balancers, EC2 instances and Elastic IP addresses, and it proxies packets rather than caching files.`],[`Replicate the bucket to every Region and add Amazon Route 53 latency records`,`This works but needs a bucket, replication and records for every Region to manage, which is more overhead than a CDN.`],[`Place an Amazon ElastiCache cluster in front of the bucket for the website files`,`An in-memory cache sits between an application and its data store inside a Region and does not bring content closer to viewers around the world.`]],slot:2,evidence:[`cloudfront-what-is|You also get increased reliability and availability because copies of your files (also known as objects) are now held (or cached) in multiple edge locations around the world.`,`ga-what-is|Endpoints for standard accelerators can be Network Load Balancers, Application Load Balancers, Amazon EC2 instances, or Elastic IP addresses that are located in one AWS Region or multiple Regions.`,`ga-faq|Global Accelerator improves performance for a wide range of applications over TCP or UDP by proxying packets at the edge to applications running in one or more AWS Regions.`]}),t({id:`cache-edge-breakwater-004`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`],d:2,tags:[`placement-eligible`],stem:`A website is delivered through Amazon CloudFront from an Amazon S3 origin. Every release changes many JavaScript and CSS files, and visitors must get the new versions immediately after release. The company wants to keep the long cache duration for all other files and pay the LOWEST cost with the LEAST effort. Which approach meets these requirements?`,correct:[`Put a version identifier in the file names and update the links in the pages to the new names`,`New names are new objects, so viewers get them at once without waiting for expiry or paying for invalidations, and other files stay cached.`],wrong:[[`Delete the old objects from the S3 bucket and upload the new ones under the same names`,`CloudFront continues to show viewers the cached content until the files expire, so visitors would keep receiving old versions.`],[`Set the cache duration to zero for the whole distribution`,`This removes the long cache duration the company wants to keep for all other files, and every request would reach the origin.`],[`Invalidate every file in the distribution after each release`,`This also removes the unchanged files from the cache and has to be repeated each release, while versioned names avoid invalidation fees.`]],slot:3,evidence:[`cloudfront-versioning|To update existing content that CloudFront is set up to distribute for you, we recommend that you use a version identifier in file names or in folder names.`,`cloudfront-versioning|With versioning, you don't have to wait for an object to expire before CloudFront begins to serve a new version of it, and you don't have to pay for object invalidation.`,`cloudfront-versioning|However, CloudFront will continue to show viewers content from the edge cache until the files expire.`]}),t({id:`cache-edge-breakwater-005`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`,`2.1-K3`],d:3,tags:[`placement-eligible`],stem:`A web application is delivered through Amazon CloudFront with an Application Load Balancer as the origin. Images under /images/ never change after upload. HTML pages under /pages/ change every few minutes and must not be stale for longer than that. The company wants to cut origin load as far as possible without serving outdated pages. Which configuration BEST meets these requirements?`,correct:[`Create one cache behavior per path pattern, with a long TTL for /images/ and a short TTL for /pages/`,`Cache duration is set per path pattern in a cache behavior, so images get a long duration and pages stay fresh while still being cached briefly.`],wrong:[[`Use one cache behavior with a long TTL for all paths`,`A long duration for the HTML pages means viewers could see outdated pages for far longer than the few minutes allowed.`],[`Use one cache behavior with a TTL of zero for all paths`,`The images would be fetched from the origin on every request, so the origin load is not reduced.`],[`Serve /pages/ directly from the origin and use CloudFront only for /images/`,`The pages would never be cached, so their requests all reach the origin instead of being absorbed by a short TTL at the edge.`]],slot:0,evidence:[`cloudfront-expiration|To change the cache duration for all files that match the same path pattern, you can change the CloudFront settings for Minimum TTL, Maximum TTL, and Default TTL for a cache behavior.`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`,`cloudfront-expiration|By reducing the duration, you can serve dynamic content.`]}),t({id:`cache-edge-breakwater-006`,building:`cache-edge-breakwater`,bullets:[`2.1-K3`],d:2,tags:[`placement-eligible`],stem:`A mobile game stores player profiles in Amazon DynamoDB. A small number of popular profiles are read many times per second, eventually consistent reads are acceptable, and the game needs microsecond read latency. The company wants the LEAST change to the application code. Which solution BEST meets these requirements?`,correct:[`Create a DynamoDB Accelerator (DAX) cluster and point the DynamoDB client at it`,`DAX is a DynamoDB-compatible in-memory cache that serves eventually consistent reads in microseconds and needs only minimal changes to use.`],wrong:[[`Add an Amazon ElastiCache cluster and write code that checks the cache before each DynamoDB request`,`ElastiCache can cache the data, but the application must implement the cache logic itself, which is more code change than DAX.`],[`Increase the provisioned read capacity of the table`,`More read capacity adds throughput and does not move reads from single-digit milliseconds to microseconds.`],[`Convert the table to a DynamoDB global table in a second Region`,`Replicating the table to another Region does not add an in-memory cache, so reads stay at DynamoDB response times.`]],slot:1,evidence:[`dax|As an in-memory cache, DAX reduces the response times of eventually consistent read workloads by an order of magnitude from single-digit milliseconds to microseconds.`,`dax|DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`,`dax|Therefore, it requires only minimal functional changes to use with an existing application.`]}),t({id:`cache-edge-breakwater-007`,building:`cache-edge-breakwater`,bullets:[`2.1-K3`],d:3,tags:[`placement-eligible`],stem:`A serverless API uses an Amazon API Gateway REST API, AWS Lambda and Amazon DynamoDB. A GET method returns the same product data to every user, and the same few products are requested again and again. The company wants fewer Lambda invocations, fewer DynamoDB reads and lower response latency for these repeated requests, with the LEAST code change. Which solution BEST meets these requirements?`,correct:[`Enable API caching on the API stage with a suitable time-to-live`,`The stage cache answers repeated requests from cached responses instead of calling the endpoint, so neither Lambda nor DynamoDB is used for them.`],wrong:[[`Create a DynamoDB Accelerator (DAX) cluster in front of the table`,`DAX speeds up DynamoDB reads, but every request still invokes the Lambda function, so the invocations are not reduced.`],[`Configure provisioned concurrency for the Lambda function`,`Provisioned concurrency prepares execution environments and does not stop repeated requests from invoking the function and reading the table.`],[`Increase the provisioned read capacity of the DynamoDB table`,`Extra capacity adds read throughput, but each request still invokes the function and reads the table, so nothing is reduced.`]],slot:2,evidence:[`apigw-caching|With caching, you can reduce the number of calls made to your endpoint and also improve the latency of requests to your API.`,`apigw-caching|API Gateway then responds to the request by looking up the endpoint response from the cache instead of making a request to your endpoint.`]}),t({id:`cache-edge-breakwater-008`,building:`cache-edge-breakwater`,bullets:[`2.1-K3`],d:2,tags:[`placement-eligible`],stem:`AWS Lambda functions read user profiles from Amazon DynamoDB through an Amazon ElastiCache cache. Profiles change a few times a day, and a profile read right after an update must never return old data. The application can tolerate a small delay on writes. Which caching strategy BEST meets these requirements?`,correct:[`Write-through, so that every profile write also adds or updates the item in the cache`,`The cache is updated every time data is written to the database, so data in the cache is never stale.`],wrong:[[`Lazy loading only, so that a profile is cached the first time it is read`,`Data is written to the cache only on a miss, so a cached profile can become stale after the database is updated.`],[`Lazy loading with a long time to live on each cached profile`,`A time to live keeps data from getting too stale but does not guarantee that a value is not stale, so reads right after an update can be old.`],[`Load all profiles into the cache once at startup and never change them`,`The cached copies would never reflect later updates, so they would be stale after the first change.`]],slot:3,evidence:[`elasticache-strategies|The write-through strategy adds data or updates data in the cache whenever data is written to the database.`,`elasticache-strategies|The advantages of write-through are as follows: Data in the cache is never stale.`,`elasticache-strategies|If data is written to the cache only when there is a cache miss, data in the cache can become stale.`,`elasticache-strategies|This approach doesn't guarantee that a value isn't stale.`]}),e({id:`cache-edge-breakwater-009`,building:`cache-edge-breakwater`,bullets:[`2.1-K3`],d:3,stem:`A company caches product details from an Amazon RDS database in Amazon ElastiCache. Only data that customers actually request should take up space in the cache, a failed cache node must not break the application, and cached data must not stay stale for long. Which TWO design choices BEST meet these requirements? (Choose two.)`,correct:[[`Use lazy loading, so that data is cached only when the application requests it`,`Only requested data is cached, and a failed node is replaced by an empty one that the application refills with cache misses instead of failing.`],[`Add a time to live to each cached item`,`Expiry keeps cached data from getting too stale because values are refreshed from the database from time to time.`]],wrong:[[`Use write-through for every database write`,`Most written data is never read, so this fills the cache with data nobody requested, and a new node lacks data until it is written.`],[`Load the whole catalogue into the cache at deployment and keep it without expiry`,`This caches data nobody requested and lets entries go stale because nothing refreshes them.`],[`Remove the cache and send every read to the database`,`Without a cache there is nothing to go stale, but this fails the goal of caching requested data and increases the load on the database.`]],slots:[0,2],evidence:[`elasticache-strategies|The advantages of lazy loading are as follows: Only requested data is cached.`,`elasticache-strategies|Node failures aren't fatal for your application.`,`elasticache-strategies|However, it keeps data from getting too stale and requires that values in the cache are occasionally refreshed from the database.`,`elasticache-strategies|Most data is never read, which is a waste of resources.`]}),e({id:`cache-edge-breakwater-010`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`,`2.1-K3`],d:2,tags:[`placement-eligible`],stem:`A company hosts a single-page application in an Amazon S3 bucket and a public REST API that uses Amazon API Gateway, AWS Lambda and Amazon DynamoDB. Users around the world repeatedly request the same static files and the same read-mostly GET response. The company wants lower latency and fewer requests reaching S3 and Lambda, with the LEAST code change. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an Amazon CloudFront distribution that uses the S3 bucket as its origin`,`Static files are served from edge locations close to users, which cuts latency and the number of requests that reach S3.`],[`Enable caching on the API Gateway stage`,`Repeated GET requests are answered from cached responses instead of invoking the Lambda function and reading the table.`]],wrong:[[`Create an AWS Global Accelerator accelerator with the S3 bucket as an endpoint`,`An S3 bucket is not an endpoint of a standard accelerator, and an accelerator proxies packets instead of caching files.`],[`Create a DynamoDB Accelerator (DAX) cluster in front of the table`,`DAX caches DynamoDB reads, but each API request would still invoke the Lambda function.`],[`Place an Amazon ElastiCache cluster in front of the S3 bucket for the static files`,`ElastiCache is an in-memory store for applications and does not serve the files from locations close to users.`]],slots:[1,4],evidence:[`cloudfront-what-is|You also get increased reliability and availability because copies of your files (also known as objects) are now held (or cached) in multiple edge locations around the world.`,`apigw-caching|With caching, you can reduce the number of calls made to your endpoint and also improve the latency of requests to your API.`,`ga-what-is|Endpoints for standard accelerators can be Network Load Balancers, Application Load Balancers, Amazon EC2 instances, or Elastic IP addresses that are located in one AWS Region or multiple Regions.`]}),t({id:`cache-edge-breakwater-011`,building:`cache-edge-breakwater`,bullets:[`2.1-K3`],d:1,tags:[`mock-reserve`],stem:`A company wants a managed in-memory data store that sits between its application servers and a relational database and holds frequently read query results. The store must support the Redis OSS or Memcached engines, and the company wants the LEAST operational overhead. Which service should the company use?`,correct:[`Amazon ElastiCache`,`ElastiCache is a fully managed in-memory data store and cache that supports the Redis OSS and Memcached engines.`],wrong:[[`Amazon DynamoDB Accelerator (DAX)`,`DAX is a caching service for DynamoDB tables and does not cache results from a relational database.`],[`Amazon CloudFront`,`CloudFront caches web content at edge locations and is not an in-memory store that application servers query before a database.`],[`An Amazon RDS read replica`,`A read replica is another database instance and is not an in-memory cache based on Redis OSS or Memcached.`]],slot:0,evidence:[`elasticache-what-is|Amazon ElastiCache is a web service that makes it easy to set up, manage, and scale a distributed in-memory data store or cache environment in the cloud.`,`elasticache-what-is|Since ElastiCache is a fully-managed service, it automatically manages hardware provisioning, monitoring, node replacements, and software patching for your cluster.`,`dax|DAX is a DynamoDB-compatible caching service that enables you to benefit from fast in-memory performance for demanding applications.`]}),t({id:`cache-edge-breakwater-012`,building:`cache-edge-breakwater`,bullets:[`2.1-K7`],d:2,tags:[`mock-reserve`,`trap:cloudfront-vs-global-accelerator`],stem:`A company serves a personalised web application from Application Load Balancers in two AWS Regions. The responses cannot be cached. Clients send POST and PUT requests as well as GET requests. Partner networks must allow-list fixed IP addresses, and traffic, including the POST and PUT requests, must shift to the other Region quickly when one becomes unhealthy. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an AWS Global Accelerator accelerator and add both load balancers as endpoints`,`The accelerator provides static IP addresses as fixed entry points and routes traffic only to healthy endpoints in either Region.`],wrong:[[`Create an Amazon CloudFront distribution and turn off caching for the behaviors`,`CloudFront origin failover applies only when the viewer request is a GET, HEAD or OPTIONS request, so POST and PUT requests would not shift to the other Region.`],[`Create Amazon Route 53 failover records that point to the two load balancers`,`DNS answers are cached by client devices and resolvers, so a shift to the other Region is not deterministic and fast.`],[`Run proxy instances with Elastic IP addresses in each Region and fail over with a script`,`The company would patch, scale and script the proxies itself, which is far more operational overhead than a managed service.`]],slot:1,evidence:[`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`,`ga-how|The static IP addresses provided by AWS Global Accelerator serve as single fixed entry points for your clients.`,`ga-faq|Some client devices and internet resolvers cache DNS answers for long periods of time.`,`cf-origin-failover|CloudFront does not fail over when the viewer sends a different HTTP method (for example POST, PUT, and so on).`]})],i=[t({id:`cargo-hall-001`,building:`cargo-hall`,bullets:[`2.1-K13`],d:1,tags:[`trap:ebs-efs-fsx`],stem:`A media company stores millions of video files that a streaming application reads through an API over the internet. The workload is read-heavy, and the company does not want to run file servers or manage volumes. Which storage type and service BEST meet these requirements?`,correct:[`Object storage, using Amazon S3 buckets that the application reads through the S3 API`,`Object storage is accessed through an API over the internet and suits read-heavy streaming workloads, with no servers or volumes to run.`],wrong:[[`Block storage, using Amazon EBS volumes attached to the streaming servers`,`Block storage is attached to an instance for low-latency disk access, not read through an API over the internet.`],[`File storage, using an Amazon EFS file system mounted on the streaming servers`,`File storage is mounted by clients over NFS, which does not match access through an API over the internet.`],[`File storage, using Amazon FSx for Windows File Server shares reached over SMB`,`File storage is mounted by clients over SMB, which does not match access through an API over the internet.`]],slot:0,evidence:[`storage-decision|Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`,`storage-decision|Read-heavy workloads such as content distribution, web hosting, big data analytics, and ML workflows.`]}),t({id:`cargo-hall-002`,building:`cargo-hall`,bullets:[`2.1-K13`],d:2,tags:[`trap:ebs-efs-fsx`,`trap:instance-store-vs-ebs`],stem:`A company runs a self-managed relational database on one Amazon EC2 instance, and no other server accesses the data. The database needs durable storage with low-latency, consistent I/O that works like a local disk. Which storage option meets these requirements with the LEAST change to the application?`,correct:[`An Amazon EBS volume attached to the instance and formatted with the database file system`,`Block storage attached to a single instance gives low-latency, durable disk access and behaves like a local hard drive.`],wrong:[[`An Amazon S3 bucket that the database engine reads and writes through the S3 API`,`Object storage is accessed through an API rather than as a local disk, so the database engine would need to change.`],[`An Amazon EFS file system mounted on the instance over NFS to hold the database files`,`File storage is built for shared access across many clients, which this single-instance database does not need.`],[`Instance store volumes on the host computer, copied nightly to a second Amazon S3 bucket`,`Instance store data does not persist if the instance is stopped or terminated, so the storage is not durable.`]],slot:1,evidence:[`storage-decision|Storage services or tools Block Applications requiring low-latency, high-performance durable storage attached to single Amazon EC2 instances or containers, such as databases and general-purpose local instance storage.`,`ebs-what-is|After you attach a volume to an instance, you can use it in the same way you would use a local hard drive attached to a computer, for example to store files or to install applications.`,`instance-store-lifetime|When the instance is stopped, hibernated, or terminated, every block of the instance store volume is cryptographically erased.`]}),e({id:`cargo-hall-003`,building:`cargo-hall`,bullets:[`2.1-K13`],d:2,tags:[`trap:ebs-efs-fsx`],stem:`A company is moving two shared-file workloads to AWS. Linux analytics servers on Amazon EC2 need shared read and write access to the same files over NFS. A Windows-based finance team needs file shares that use the SMB protocol on a native Windows file system. The company wants fully managed storage with the LEAST operational overhead. Which TWO solutions meet these requirements? (Choose two.)`,correct:[[`An Amazon EFS file system that the Linux analytics servers mount over NFS`,`Amazon EFS is shared file storage that supports NFS, so many Linux clients can read and write the same files without servers to manage.`],[`An Amazon FSx for Windows File Server file system that serves the finance team over SMB`,`FSx for Windows File Server is a fully managed native Windows file system with SMB support.`]],wrong:[[`Amazon EBS Multi-Attach volumes shared by the Linux analytics servers`,`Multi-Attach is block storage limited to Provisioned IOPS SSD volumes in one Availability Zone, and it is not an NFS file system.`],[`An Amazon EFS file system that the Windows-based finance team uses for its shares`,`Amazon EFS does not support Microsoft Windows-based EC2 instances, and the team needs SMB shares.`],[`An Amazon S3 bucket that both teams read and write through the S3 API`,`Object storage is reached through an API, not mounted as NFS or SMB file shares.`]],slots:[1,4],evidence:[`storage-decision|Applications and workloads requiring shared read and write access across multiple Amazon EC2 instances or containers, or from multiple on-premises servers, such as team file shares, highly available enterprise applications, analytics workloads, and ML training.`,`efs-what-is|Amazon EFS supports the Network File System version 4 (NFSv4.1 and NFSv4.0) protocol, so the applications and tools that you use today work seamlessly with Amazon EFS.`,`efs-what-is|Using Amazon EFS with Microsoft Windows–based Amazon EC2 instances is not supported.`,`fsx-windows|Amazon FSx has native support for Windows file system features and for the industry-standard Server Message Block (SMB) protocol to access file storage over a network.`]}),t({id:`cargo-hall-004`,building:`cargo-hall`,bullets:[`2.1-K13`],d:3,tags:[`trap:ebs-efs-fsx`],stem:`A company runs a clustered application on two Amazon EC2 instances built on the Nitro System in the same Availability Zone. Both instances must read and write the same block device at the same time, and the application coordinates concurrent writes itself. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create one io2 volume with Multi-Attach enabled and attach it to both instances`,`Multi-Attach lets a single io1 or io2 volume attach to several instances in the same Availability Zone for applications that manage concurrent writes.`],wrong:[[`Create one General Purpose SSD (gp3) volume and attach it to both instances at once`,`Multi-Attach is documented for Provisioned IOPS SSD (io1 or io2) volumes, so a gp3 volume cannot be shared this way.`],[`Create an Amazon EFS file system and mount it on both instances over NFS`,`EFS is file storage over NFS, and the application needs a shared block device.`],[`Create an io2 volume in a different Availability Zone and attach it to both instances`,`A volume and the instance it is attached to must be in the same Availability Zone.`]],slot:2,evidence:[`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`,`ebs-multi-attach|Multi-Attach makes it easier for you to achieve higher application availability in applications that manage concurrent write operations.`,`ebs-volumes|The volume and instance must be in the same Availability Zone.`]}),t({id:`cargo-hall-005`,building:`cargo-hall`,bullets:[`2.1-K13`],d:1,stem:`A company keeps application data on an Amazon EBS volume. The company needs a point-in-time backup of the volume that remains available even if the volume itself is deleted. Which feature meets this requirement?`,correct:[`Amazon EBS snapshots of the volume, taken on a regular schedule and kept separately`,`Snapshots are point-in-time backups of volumes that persist independently from the volume, and new volumes can be restored from them.`],wrong:[[`Amazon EBS encryption turned on for the volume with an AWS KMS key`,`Encryption protects data on the volume and its snapshots but does not create a backup copy.`],[`Amazon EBS Multi-Attach turned on for the volume and a second instance attached`,`Multi-Attach lets more instances use the same volume, so deleting the volume still removes the data.`],[`An instance store volume on the same instance, with the files copied to it each night`,`Instance store data does not persist when the instance is stopped or terminated, so it is not a lasting backup.`]],slot:3,evidence:[`ebs-what-is|Amazon EBS snapshots — These are point-in-time backups of Amazon EBS volumes that persist independently from the volume itself.`,`ebs-what-is|You can then restore new volumes from those snapshots at any time.`,`instance-store-lifetime|When the instance is stopped, hibernated, or terminated, every block of the instance store volume is cryptographically erased.`]}),t({id:`cargo-hall-006`,building:`cargo-hall`,bullets:[`2.1-S6`],d:2,stem:`A company packages a web application as Docker containers and runs them on Amazon ECS. The company does not want to provision, configure or scale clusters of virtual machines for the containers. Which compute option BEST meets these requirements?`,correct:[`AWS Fargate as the launch type for the Amazon ECS tasks that run the containers`,`Fargate runs containers without managing servers or clusters of EC2 instances, and it works with Amazon ECS.`],wrong:[[`Amazon EC2 instances registered to the ECS cluster and scaled by an Auto Scaling group`,`The company would still provision, patch and scale the cluster of virtual machines that run the containers.`],[`Amazon EKS with self-managed worker nodes in an Auto Scaling group of EC2 instances`,`The company would still run and scale virtual machines, and it would also have to adopt Kubernetes.`],[`Amazon ECS Anywhere with servers that the company runs in its own data center`,`ECS Anywhere registers external servers to the cluster, which the company would still own and manage.`]],slot:0,evidence:[`compute-decision|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`compute-decision|Amazon ECS Anywhere provides support for registering an external instance such as an on-premises server or VM, to your Amazon ECS cluster.`]}),t({id:`cargo-hall-007`,building:`cargo-hall`,bullets:[`2.1-S6`],d:2,stem:`A small team has a Java web application. The team wants to deploy only its application code while the service provides the runtime on Amazon EC2 instances and applies patches to the operating system and runtime. Which service meets these requirements with the LEAST operational overhead?`,correct:[`AWS Elastic Beanstalk with a Java platform environment that runs the code on EC2`,`Elastic Beanstalk is designed for web applications and manages updates for OS patches and runtime on the EC2 instances it manages.`],wrong:[[`Amazon EC2 instances that the team builds, configures with Java and patches itself`,`The team would be responsible for setup, scaling, patching and securing the servers.`],[`AWS Batch with a job definition that wraps the web application`,`Batch plans, schedules and runs batch workloads, and it is not a service for running web applications.`],[`Amazon EKS with a managed node group and the application packaged as a container`,`The team would have to containerize the application and operate Kubernetes workloads, which adds overhead.`]],slot:1,evidence:[`compute-decision|Elastic Beanstalk is specifically designed for running web applications.`,`compute-decision|Elastic Beanstalk provides managed updates for OS patches, runtime and framework on EC2 instances it manages so customers can just run their application code.`,`compute-decision|For instance, managing EC2 instances involves responsibility for setup, scaling, patching, and securing servers.`]}),t({id:`cargo-hall-008`,building:`cargo-hall`,bullets:[`2.1-S6`],d:3,tags:[`trap:s3-storage-classes`],stem:`A research company keeps 200 TB of datasets in Amazon S3 Standard. Some datasets are read daily for weeks and then not touched for months, and the pattern differs by dataset. The company wants storage costs reduced automatically, with no application changes and no planning of access patterns. Which solution is the MOST cost-effective?`,correct:[`Move the datasets to S3 Intelligent-Tiering so objects move between access tiers as access changes`,`Intelligent-Tiering is the ideal class for unknown or changing access patterns and moves data automatically with no application changes.`],wrong:[[`Create an S3 Lifecycle rule that moves every object to S3 Standard-IA after a fixed number of days`,`A fixed schedule cannot follow each dataset's access pattern, so datasets that are read again would stay in the wrong class.`],[`Move all datasets to S3 Glacier Flexible Retrieval to cut the cost of storing them`,`Access times range from minutes to hours, which does not suit datasets that are read daily.`],[`Copy the datasets to an Amazon EFS file system and use EFS Lifecycle management to move cold files`,`EFS is file storage, so the applications that use the S3 API would need to change.`]],slot:2,evidence:[`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`,`storage-decision|Use storage classes and tiering features that match your access patterns.`,`s3-glacier-classes|S3 Glacier Flexible Retrieval offers flexible retrieval times to help you balance costs, with access times ranging from a few minutes to hours, and free bulk retrievals.`]}),e({id:`cargo-hall-009`,building:`cargo-hall`,bullets:[`2.1-S6`],d:3,stem:`A retail company needs two databases. The order-processing system needs a fully managed relational database with full SQL support, automated backups and Multi-AZ deployments. A reporting team needs to run large-scale analytics queries over years of sales data. The company wants managed services with the LEAST operational overhead. Which TWO choices meet these requirements? (Choose two.)`,correct:[[`Amazon RDS for the order-processing system, with automated backups and Multi-AZ`,`RDS is a fully managed relational database with automated backups, software patching and Multi-AZ deployments.`],[`Amazon Redshift for the reporting workload, querying the full sales history`,`Redshift is a fully managed data warehousing service designed for large-scale analytics.`]],wrong:[[`Amazon DynamoDB for the order-processing system, with joins done in the application`,`DynamoDB is a key-value NoSQL database and is not a relational database with full SQL support.`],[`Amazon ElastiCache for the reporting workload, holding the full sales history`,`ElastiCache is an ephemeral cache for frequently accessed data and not a store for years of sales data.`],[`Amazon Neptune for the reporting queries over the sales history`,`Neptune is a graph database for traversing relationships and is not a data warehouse for analytics.`]],slots:[0,2],evidence:[`database-decision|Optimized for structured data with full SQL support, automated backups, software patching, and Multi-AZ deployments for high availability.`,`database-decision|Amazon Redshift is a fully managed, cloud-based data warehousing service that is designed to handle large-scale analytics workloads.`,`database-decision|Optimized to support microsecond reads and sub-millisecond writes as an ephemeral cache for frequently accessed data.`]}),t({id:`cargo-hall-010`,building:`cargo-hall`,bullets:[`2.1-S6`],d:2,tags:[`trap:aurora-vs-rds`],stem:`A company runs a Microsoft SQL Server database on Amazon EC2 for an internal line-of-business application. The company wants a fully managed database service that keeps the SQL Server engine and removes patching and backup administration. Which solution meets these requirements?`,correct:[`Migrate the database to Amazon RDS for SQL Server and keep the engine`,`RDS offers SQL Server among its engines as a fully managed service, so the application keeps its engine and AWS handles patching and backups.`],wrong:[[`Migrate the database to Amazon Aurora PostgreSQL-Compatible Edition`,`Aurora supports MySQL and PostgreSQL-compatible engines, so the SQL Server engine would be lost and the application would change.`],[`Migrate the data to Amazon DynamoDB and rewrite the queries as key-value requests`,`DynamoDB is a key-value NoSQL database, so the SQL queries and the SQL Server engine would be lost.`],[`Migrate the data to Amazon Redshift and run the application against the warehouse`,`Redshift is a data warehouse for large-scale analytics, not an engine for a transactional line-of-business application.`]],slot:3,evidence:[`database-decision|Use when you need a fully managed relational database with your choice of six popular engines: PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`database-decision|Supports MySQL and PostgreSQL-compatible engines with up to five times the throughput of standard MySQL.`,`database-decision|While rehosting is a fast path to the cloud, you're still left with the operational tasks such as upgrades, patches, backups, capacity planning and management, maintaining performance, and availability targets.`]}),t({id:`cargo-hall-011`,building:`cargo-hall`,bullets:[`2.1-K13`,`2.1-S6`],d:2,tags:[`mock-reserve`,`trap:ebs-efs-fsx`],stem:`A company is migrating from on-premises NetApp appliances. Linux servers reach the data over NFS and Windows servers reach the same data over SMB, and the company wants a fully managed service that serves both protocols at once. Which solution BEST meets these requirements?`,correct:[`An Amazon FSx for NetApp ONTAP file system that both server groups mount`,`FSx for NetApp ONTAP supports NFS and SMB with concurrent multi-protocol access to the same data, which suits mixed Linux and Windows clients.`],wrong:[[`An Amazon EFS file system mounted by both the Linux and the Windows servers`,`EFS supports NFS only and is not supported with Microsoft Windows-based EC2 instances, so the SMB clients cannot use it.`],[`An Amazon FSx for Lustre file system mounted by both groups of servers`,`FSx for Lustre is designed for Unix and Linux file systems and speed-sensitive workloads, not for Windows SMB clients.`],[`Amazon EBS Multi-Attach volumes shared by all of the servers`,`Multi-Attach is block storage for instances in one Availability Zone, not a file system with NFS and SMB access.`]],slot:0,evidence:[`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`storage-decision|This makes it suitable for mixed environments where both Linux and Windows clients need access to shared data, such as when migrating from on-premises NetApp appliances.`,`storage-decision|Amazon FSx for Lustre (for high-performance file systems) is designed for use with Unix/Linux-based file systems.`]}),t({id:`cargo-hall-012`,building:`cargo-hall`,bullets:[`2.1-S6`],d:2,tags:[`mock-reserve`],stem:`A research company runs thousands of containerized simulation jobs every night. The company wants a fully managed service that plans, schedules and runs the jobs across Spot and On-Demand Instances, with the LEAST custom scheduling code. Which service should the company use?`,correct:[`AWS Batch with a compute environment that uses Spot and On-Demand Instances`,`Batch is a fully managed batch computing service that plans, schedules and runs containerized batch workloads across Spot and On-Demand capacity.`],wrong:[[`AWS Elastic Beanstalk with a worker environment that wraps the simulations`,`Elastic Beanstalk is designed for running web applications and does not plan and schedule batch jobs across Spot capacity.`],[`Amazon ECR with a repository that holds the simulation images`,`ECR is a container image registry, which stores images but does not schedule or run jobs.`],[`An Amazon EC2 Auto Scaling group with a custom scheduler that the company writes`,`Auto Scaling launches and terminates instances when scaling policies respond to demand, and the company would write the job scheduling itself.`]],slot:1,evidence:[`compute-decision|AWS Batch is a fully managed batch computing service that plans, schedules, and runs your containerized batch machine learning, simulation, and analytics workloads across the full range of AWS compute offerings, such as Amazon ECS, Amazon EKS, Fargate, and Spot or On-Demand Instances.`,`compute-decision|Amazon ECR is an AWS managed container image registry service that is secure, scalable, and reliable.`,`compute-decision|Elastic Beanstalk is specifically designed for running web applications.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`]})],a=[t({id:`container-dock-001`,building:`container-dock`,bullets:[`2.1-K8`],d:1,stem:`A company is moving an application into Docker containers. The team needs a private, managed place to store the container images, with access controlled through IAM. Which AWS service BEST meets this requirement?`,correct:[`Amazon ECR`,`Amazon ECR is a managed container image registry that supports private repositories with permissions controlled through IAM.`],wrong:[[`Amazon ECS`,`Amazon ECS orchestrates containers that run from images, and it is not the registry where the images are stored.`],[`AWS Fargate`,`Fargate provides serverless compute capacity to run containers and does not store container images.`],[`Amazon EKS`,`Amazon EKS provides managed Kubernetes to orchestrate containers and does not act as the image registry.`]],slot:0,evidence:[`ecr-what-is|Amazon Elastic Container Registry (Amazon ECR) is an AWS managed container image registry service that is secure, scalable, and reliable.`,`ecr-what-is|Amazon ECR supports private repositories with resource-based permissions using AWS IAM.`]}),t({id:`container-dock-002`,building:`container-dock`,bullets:[`2.1-K14`],d:1,stem:`A company runs an application on Kubernetes in its own data center and uses community Kubernetes tooling. The company wants to move it to AWS with a managed Kubernetes control plane and without refactoring the application. Which service BEST meets these requirements?`,correct:[`Amazon EKS`,`Amazon EKS is certified Kubernetes-conformant, so Kubernetes-compatible applications deploy without refactoring, and AWS manages the control plane.`],wrong:[[`Amazon ECS`,`Amazon ECS is the AWS-native orchestrator with its own task definitions and services, so the application would have to be reworked.`],[`AWS Lambda with container images`,`Lambda runs event-driven functions and does not run Kubernetes workloads or tooling.`],[`Amazon EC2 instances that run a self-managed Kubernetes cluster`,`The company would operate the control plane itself instead of using a managed one.`]],slot:1,evidence:[`eks-what-is|Amazon EKS is certified Kubernetes-conformant, so you can deploy Kubernetes-compatible applications without refactoring and use Kubernetes community tooling and plugins.`,`eks-what-is|EKS standard: AWS manages the Kubernetes control plane when you create a cluster with EKS.`]}),t({id:`container-dock-003`,building:`container-dock`,bullets:[`2.1-S4`],d:1,stem:`A development team finds that an application behaves differently on developer laptops, in testing and in production because the environments differ. The team wants the application to run the same way on any platform that supports the runtime. Which approach BEST meets this requirement?`,correct:[`Package the application and its dependencies in container images`,`Containers give a consistent runtime environment that runs on any platform that supports the container runtime.`],wrong:[[`Install the dependencies by hand on the same Amazon EC2 instance type in every environment`,`Manual installs drift apart over time and do not travel with the application to other platforms.`],[`Place each environment in its own AWS account and VPC with the same security groups`,`Account and network isolation separates the environments and does not make the runtime consistent.`],[`Document the setup steps for each environment in a shared runbook that the team follows`,`A runbook relies on people following steps and does not guarantee the same runtime everywhere.`]],slot:2,evidence:[`container-decision|Portability: Benefit from a consistent runtime environment that can run on any platform that supports the container runtime.`,`container-decision|Consistency: Ensure that the application runs the same way in all environments with a consistent runtime environment.`]}),t({id:`container-dock-004`,building:`container-dock`,bullets:[`2.1-S4`,`2.1-K14`],d:2,stem:`A company is moving a containerized, stateless web API to AWS. The team has no Kubernetes experience, and it wants the API to run behind a load balancer with no Amazon EC2 instances to patch or scale. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`An Amazon ECS service that uses AWS Fargate, registered with an Application Load Balancer`,`Fargate runs the containers without servers to manage, and ECS services on Fargate support Application Load Balancers.`],wrong:[[`An Amazon ECS service that runs on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer`,`With EC2 capacity the team chooses the instance type and number of instances and manages the capacity, which it wants to avoid.`],[`An Amazon EKS cluster with self-managed worker nodes behind an Application Load Balancer`,`The team would need Kubernetes skills and would manage the worker nodes, which conflicts with both requirements.`],[`Docker installed on one Amazon EC2 instance that sits behind an Application Load Balancer`,`The team would patch and scale the instance itself, and one instance cannot follow demand or replace failures on its own.`]],slot:3,evidence:[`ecs-what-is|With Fargate you don't need to manage servers, handle capacity planning, or isolate container workloads for security.`,`ecs-what-is|Amazon EC2 instances in the AWS cloud You choose the instance type, the number of instances, and manage the capacity.`,`ecs-service-lb|Amazon ECS services hosted on AWS Fargate support the Application Load Balancers, Network Load Balancers, and Gateway Load Balancers.`]}),t({id:`container-dock-005`,building:`container-dock`,bullets:[`2.1-K8`],d:2,stem:`A company stores container images in a private Amazon ECR repository. The security team requires every newly pushed image to be checked for known software vulnerabilities automatically, with the LEAST operational effort. Which solution meets this requirement?`,correct:[`Configure the repository to scan images on push`,`ECR image scanning identifies software vulnerabilities, and a repository set to scan on push scans each new image as it is pushed.`],wrong:[[`Add a lifecycle policy to the repository that expires images that contain vulnerabilities`,`Lifecycle policies clean up unused images by rule and do not scan images for vulnerabilities.`],[`Turn on cross-Region replication so that a second copy of every image exists in another Region`,`Replication places images where they are needed and does not check them for vulnerabilities.`],[`Run a nightly script on an Amazon EC2 instance that pulls every image and runs a scanner`,`This is custom tooling that the team must build and operate, and new images stay unscanned until the nightly run.`]],slot:0,evidence:[`ecr-what-is|Image scanning helps in identifying software vulnerabilities in your container images.`,`ecr-what-is|Each repository can be configured to scan on push.`,`ecr-what-is|This ensures that each new image pushed to the repository is scanned.`,`ecr-what-is|You define rules that result in the cleaning up of unused images.`]}),t({id:`container-dock-006`,building:`container-dock`,bullets:[`2.1-K14`],d:2,stem:`A containerized application runs as tasks in Amazon ECS on AWS Fargate and must read objects from an Amazon S3 bucket. The security team prohibits long-term access keys in container images and task definitions. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an IAM role with the S3 permissions and set it as the task role in the task definition`,`The task role vends its permissions to the containers in the task, so the application can use Amazon S3 without any stored access keys.`],wrong:[[`Attach an EC2 instance profile with the S3 permissions to the Fargate infrastructure that runs the tasks`,`EC2 instance profiles are not available for containers in tasks that run on Fargate.`],[`Create an IAM user with the S3 permissions and bake its access keys into the container image`,`Long-term access keys inside an image are exactly what the security team prohibits.`],[`Create an IAM user with the S3 permissions and put its access keys in plain-text task definition variables`,`Long-term access keys in the task definition are prohibited, and anyone who can read the definition can read them.`]],slot:1,evidence:[`ecs-task-role|The task role is required when your application accesses other AWS services, such as Amazon S3.`,`ecs-task-role|The permissions granted in the IAM role are vended to containers running in the task.`,`ecs-task-role|On ECS Fargate, EC2 instance profiles are not available for containers in your tasks.`]}),t({id:`container-dock-007`,building:`container-dock`,bullets:[`2.1-K14`],d:2,stem:`A company must keep some workloads on its own on-premises servers because of data residency rules. It runs its cloud containers on Amazon ECS and wants to deploy to the on-premises servers with the same ECS APIs and tooling. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Register the on-premises servers to the Amazon ECS cluster by using Amazon ECS Anywhere`,`ECS Anywhere registers an external server or VM to an ECS cluster, so the same ECS tooling deploys to it.`],wrong:[[`Run AWS Fargate tasks on the on-premises servers and keep the existing on-premises servers as the compute capacity`,`Fargate is the serverless compute option in the AWS Cloud, and it cannot be installed on the servers of the company.`],[`Install a self-managed Kubernetes cluster on the on-premises servers and manage it separately`,`This creates a second orchestrator with different tooling instead of the same ECS APIs and tooling.`],[`Copy the images to Amazon S3 and start them on each server with a custom deployment script`,`Custom scripts replace the ECS scheduler and APIs that the company wants to keep using.`]],slot:2,evidence:[`ecs-what-is|Amazon ECS Anywhere provides support for registering an external instance such as an on-premises server or virtual machine (VM), to your Amazon ECS cluster.`,`ecs-what-is|Serverless in the AWS cloud Fargate is a serverless, pay-as-you-go compute engine.`]}),t({id:`container-dock-008`,building:`container-dock`,bullets:[`2.1-K14`],d:2,stem:`A company runs a containerized web service as an Amazon ECS service on AWS Fargate. CPU use rises sharply during business hours. The company wants the number of running tasks to follow demand automatically and keep average CPU utilization near a target value, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Configure Amazon ECS Service Auto Scaling with a target tracking policy on average CPU utilization`,`Service Auto Scaling increases or decreases the desired number of tasks based on a target value for a metric.`],wrong:[[`Configure Cluster Auto Scaling to add Amazon EC2 instances to the cluster when CPU use rises`,`Cluster Auto Scaling manages EC2 instances registered to a cluster, and tasks on Fargate do not run on instances that the company manages.`],[`Create an Amazon CloudWatch alarm that notifies an operator who then raises the desired task count by hand`,`This is a manual process that does not follow demand automatically.`],[`Raise the CPU and memory values in the task definition to the largest values that Fargate offers`,`Bigger tasks do not change the number of running tasks, so the service does not follow demand.`]],slot:3,evidence:[`ecs-autoscaling|Automatic scaling is the ability to increase or decrease the desired number of tasks in your Amazon ECS service automatically.`,`ecs-autoscaling|Increase or decrease the number of tasks that your service runs based on a target value for a specific metric.`,`ecs-what-is|Cluster Auto Scaling Amazon ECS manages the scaling of Amazon EC2 instances that are registered to your cluster.`]}),t({id:`container-dock-009`,building:`container-dock`,bullets:[`2.1-K14`,`2.1-S4`],d:3,stem:`A small company is containerizing its microservices. The team has no Kubernetes experience, does not need Kubernetes APIs or tooling, and wants tight control over network and security configuration on AWS. The number of services will grow, and the team wants to keep cluster operations to a minimum. Which solution meets these requirements?`,correct:[`Amazon ECS with AWS Fargate as the capacity`,`ECS gives control over network and security configuration without Kubernetes, and Fargate removes server and capacity management.`],wrong:[[`Amazon EKS with managed node groups that the team sizes and patches as the number of services grows`,`EKS adds the Kubernetes operating model that the team does not need, and the nodes still need sizing and patching.`],[`Amazon ECS with self-managed Amazon EC2 instances that the team scales as the number of services grows`,`The team would choose instance types and manage the capacity, which adds the operations it wants to minimize.`],[`Amazon EKS with self-managed worker nodes so that the team can learn Kubernetes while it grows`,`The company has no need for Kubernetes, and self-managed nodes add the most cluster operations.`]],slot:0,evidence:[`container-decision|One of the first considerations is your preference for either a serverless operational model or a Kubernetes operation model.`,`container-decision|Amazon ECS is a good choice if you need more control over the network and security configurations without sacrificing scale or features.`,`ecs-what-is|With Fargate you don't need to manage servers, handle capacity planning, or isolate container workloads for security.`]}),t({id:`container-dock-010`,building:`container-dock`,bullets:[`2.1-S4`],d:2,stem:`A company runs 20 small services, each on its own Amazon EC2 instance at low utilization. Releases are slow, and the company wants to use compute resources more efficiently and to ship changes faster, with the LEAST change to the application code. Which solution meets these requirements?`,correct:[`Package each service as a container image and run the services together on a shared Amazon ECS cluster`,`Containers use fewer resources than virtual machines and speed up packaging and deployment, and the code does not change.`],wrong:[[`Move each service to a larger Amazon EC2 instance type to make releases finish sooner`,`Larger instances add more unused capacity and do not make the packaging or deployment process any faster.`],[`Rewrite each service as an AWS Lambda function and invoke the functions through Amazon API Gateway`,`This rewrite is a large change to the application code, which the company wants to avoid.`],[`Keep one instance for each service and add a separate Auto Scaling group to every service`,`One instance per service keeps the low utilization and adds more groups to operate.`]],slot:1,evidence:[`container-decision|Efficiency: Use fewer resources than traditional virtual machines with lightweight containers.`,`container-decision|Agility: Reduce the time that it takes to bring new features or applications to market by quickly packaging and deploying applications.`]}),t({id:`container-dock-011`,building:`container-dock`,bullets:[`2.1-K8`],d:3,stem:`A company is containerizing a monolithic web application that runs on one Amazon EC2 instance. The application keeps user sessions in instance memory and saves uploaded files on the instance disk. The containers will run as Amazon ECS tasks that deployments and scaling events replace often. Which solution prevents data loss when tasks are replaced, with the LEAST operational overhead?`,correct:[`Keep session data in an external managed store such as Amazon ElastiCache and save uploaded files in Amazon S3`,`The application no longer depends on data stored locally on disk or in memory, so tasks can be replaced freely.`],wrong:[[`Turn on sticky sessions on the load balancer and keep the uploaded files on the ephemeral storage of each task`,`Sticky sessions bind a user to one task, and the session and files are lost when that task is replaced.`],[`Increase the CPU and memory of each task so that deployments and scaling events replace tasks less often`,`Tasks are still replaced by deployments and failures, and the state in memory and on disk is lost each time.`],[`Run the containers on Amazon EC2 instances and keep sessions in the memory of each host instance`,`The state would still depend on a single host and would be lost when that host is replaced.`]],slot:2,evidence:[`waf-stateless|Systems should either not require state, or should offload state such that between different client requests, there is no dependence on locally stored data on disk and in memory.`,`waf-stateless|This allows servers to be replaced at will without causing an availability impact.`,`ecs-what-is|Service A long running stateless application.`]}),e({id:`container-dock-012`,building:`container-dock`,bullets:[`2.1-K8`],d:3,stem:`A company is moving container images from a self-managed registry to AWS. The images must be stored in a private registry with access limited through IAM, every pushed image must be scanned for software vulnerabilities, and unused images must be cleaned up automatically. Which THREE actions meet these requirements with the LEAST operational overhead? (Choose three.)`,correct:[[`Create a private Amazon ECR repository and control access with IAM permissions`,`ECR supports private repositories with resource-based permissions that use IAM.`],[`Configure the repository to scan each image when it is pushed`,`A repository can be configured to scan on push, so each new image is checked for software vulnerabilities.`],[`Define a lifecycle policy that cleans up unused images in the repository`,`Lifecycle policies use rules to clean up unused images automatically.`]],wrong:[[`Store the images as tar files in an Amazon S3 bucket and pull them with custom scripts`,`This is not a container registry, and scanning and cleanup would need custom tooling.`],[`Run a self-managed registry on an Amazon EC2 instance and clean it with a nightly script`,`The company would operate the registry, the scanning and the cleanup itself.`],[`Create pull through cache rules so that old images are removed from the repository`,`Pull through cache rules cache an upstream registry and do not remove unused images.`]],slots:[0,2,4],evidence:[`ecr-what-is|Amazon ECR supports private repositories with resource-based permissions using AWS IAM.`,`ecr-what-is|Each repository can be configured to scan on push.`,`ecr-what-is|You define rules that result in the cleaning up of unused images.`,`ecr-what-is|Pull through cache rules provide a way to cache repositories in an upstream registry in your private Amazon ECR registry.`]}),e({id:`container-dock-013`,building:`container-dock`,bullets:[`2.1-K14`],d:2,stem:`A company deploys a containerized API on Amazon ECS with AWS Fargate. The API must always run three copies, a failed copy must be replaced automatically, and incoming HTTP traffic must be spread evenly across the copies. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Run the task definition as an Amazon ECS service with a desired count of three`,`An ECS service maintains the desired number of tasks and launches a replacement when a task fails or stops.`],[`Register the service with an Application Load Balancer target group whose target type is ip`,`A load balancer distributes traffic across the tasks of the service, and Fargate tasks need an ip target type.`]],wrong:[[`Run the task definition as three standalone tasks and restart any task that stops`,`Standalone tasks are not maintained by a service scheduler, so replacing a failed task would be manual work.`],[`Register the service with a target group whose target type is instance`,`Tasks on Fargate use their own network interface and are not EC2 instances, so the target type must be ip.`],[`Place a Gateway Load Balancer in front of the service to route the HTTP traffic`,`Gateway Load Balancers are used with virtual appliances such as firewalls, and an Application Load Balancer routes HTTP and HTTPS traffic.`]],slots:[2,3],evidence:[`ecs-task-definitions|An Amazon ECS service runs and maintains your desired number of tasks simultaneously in an Amazon ECS cluster.`,`ecs-task-definitions|if any of your tasks fail or stop for any reason, the Amazon ECS service scheduler launches another instance based on your task definition`,`ecs-service-lb|Your service can optionally be configured to use Elastic Load Balancing to distribute traffic evenly across the tasks in your service.`,`fargate-ecs|When you create a target group for these services, you must choose ip as the target type, not instance.`,`ecs-service-lb|Use virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`]}),e({id:`container-dock-014`,building:`container-dock`,bullets:[`2.1-K8`],d:3,stem:`A team is containerizing an application that reads its database password from a configuration file baked into a machine image. The containers will run as Amazon ECS tasks on AWS Fargate. The password must not be stored in the container image or in the task definition text, it must be rotated automatically, and it must reach the container at runtime. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Store the password as a secret in AWS Secrets Manager and enable automatic rotation`,`Secrets Manager can automatically rotate secrets, which a plain parameter store does not do.`],[`Reference the secret in the secrets parameter of the container definition and grant access only to the IAM principals that need it`,`Secrets are injected into containers at runtime, and access is restricted to specific IAM principals.`]],wrong:[[`Pass the password as a plain-text environment variable in the task definition`,`The password would sit in the task definition text, which the team wants to avoid.`],[`Bake the password into the container image in an encrypted file that the application decrypts at startup`,`The password would still be stored in the image and would not rotate automatically.`],[`Store the password in an object in an Amazon S3 bucket that the container downloads when it starts`,`Nothing rotates the password automatically, and the team would build the retrieval logic itself.`]],slots:[0,3],evidence:[`ecs-sensitive-data|Secrets can be seamlessly injected into containers from AWS Secrets Manager and Amazon EC2 Systems Manager Parameter Store.`,`ecs-sensitive-data|Secrets Manager, however, also includes the ability to automatically rotate secrets, generate random secrets, and share secrets across accounts.`,`ecs-sensitive-data|Access to these secrets should be restricted to specific IAM principals that are using IAM and injected into containers at runtime.`,`ecs-sensitive-data|They're referenced as environment variables that use the secrets container definition parameter.`]}),t({id:`container-dock-015`,building:`container-dock`,bullets:[`2.1-K14`],d:2,tags:[`mock-reserve`],stem:`A company runs Kubernetes workloads on Amazon EKS and needs Amazon EC2 instances as worker nodes built from a custom AMI, with extra kubelet arguments set at the node level. The company wants AWS to automate creating, updating and terminating the nodes, with nodes drained during updates, and wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Add a managed node group to the EKS cluster`,`Managed node groups automate the provisioning and lifecycle management of nodes, and updates and terminations drain nodes automatically.`],wrong:[[`Launch EC2 instances in an Auto Scaling group that the company builds and join them to the cluster as self-managed nodes`,`The company would create, update and drain these nodes itself, which is the overhead it wants to avoid.`],[`Install the Kubernetes Cluster Autoscaler on self-managed node groups`,`The Cluster Autoscaler adjusts the number of nodes, but the company still builds, updates and drains them.`],[`Create an Amazon ECS cluster with Amazon EC2 capacity and move the workloads to ECS task definitions`,`This abandons Kubernetes and still leaves the company managing the EC2 capacity.`]],slot:3,evidence:[`eks-managed-node-groups|You can create, automatically update, or terminate nodes for your cluster with a single operation.`,`eks-managed-node-groups|Node updates and terminations automatically drain nodes to ensure that your applications stay available.`,`eks-managed-node-groups|For example, you can specify extra kubelet arguments and use a custom AMI.`]}),t({id:`container-dock-016`,building:`container-dock`,bullets:[`2.1-K14`],d:2,tags:[`mock-reserve`],stem:`A company runs a set of stateless pods on Amazon EKS because it depends on Kubernetes tooling. The team does not want to provision or scale groups of EC2 instances for these pods, and each pod must have its own compute boundary. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Define a Fargate profile in the cluster so that the pods run on AWS Fargate`,`Fargate profiles control which pods start on Fargate, where each pod has its own compute boundary and no instances are provisioned or scaled.`],wrong:[[`Move the application to Amazon ECS tasks on AWS Fargate and drop the Kubernetes tooling`,`The company depends on Kubernetes tooling, so leaving Kubernetes breaks that requirement.`],[`Create managed node groups in each Availability Zone and size them by hand for the pods`,`Node groups are groups of EC2 instances that the team would still provision and scale.`],[`Install Karpenter in the cluster to launch right-sized instances for the pods`,`Karpenter is open-source software that customers install, configure and manage, and it still launches EC2 instances.`]],slot:0,evidence:[`eks-fargate|You can control which Pods start on Fargate and how they run with Fargate profiles.`,`eks-fargate|Each Pod that runs on Fargate has its own compute boundary.`,`eks-fargate|With Fargate, you don’t have to provision, configure, or scale groups of virtual machines on your own to run containers.`,`eks-autoscaling|Karpenter is open-source software which AWS customers are responsible for installing, configuring, and managing in their Kubernetes clusters.`]})],o=[t({id:`disaster-bunker-001`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:1,stem:`A company's disaster recovery plan says that after a disruption the customer portal must be serving users again within 30 minutes. Which recovery metric BEST describes this requirement?`,correct:[`Recovery time objective (RTO), the maximum acceptable delay before service is restored`,`RTO is the maximum acceptable delay between the interruption of service and restoration of service, which is the 30-minute window in the plan.`],wrong:[[`Recovery point objective (RPO), the maximum acceptable time since the last recovery point`,`RPO limits how much data can be lost, not how long the portal may be unavailable.`],[`Business continuity plan (BCP), the organization-wide plan for keeping the business running`,`A BCP is the wider plan of which the DR plan is a subset; it is not a measure of acceptable downtime.`],[`Availability, the percentage of time a workload is available for use over a month or year`,`Availability is a percentage of uptime over a period, not the acceptable delay after one disruption.`]],slot:0,evidence:[`dr-objectives|Recovery Time Objective (RTO) is the maximum acceptable delay between the interruption of service and restoration of service.`,`dr-objectives|Your disaster recovery plan should be a subset of your organization’s business continuity plan (BCP), it should not be a standalone document.`,`waf-availability|Availability is the percentage of time that a workload is available for use.`]}),t({id:`disaster-bunker-002`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:2,tags:[`trap:dr-strategies`],postGuide:[`backup-hourly-frequency`],postGuideKey:[`backup-hourly-frequency`],stem:`A company runs an order system on Amazon EC2 and Amazon RDS in one Region. After a Regional disaster the system must be recoverable in a second AWS Region with an RPO of 1 hour and an RTO of 12 hours. The company wants the LOWEST ongoing cost. Which solution meets these requirements?`,correct:[`Create an AWS Backup plan that backs up the database and instances hourly and copies the backups to the second Region`,`How often the backup runs sets the achievable recovery point, so hourly backups meet the RPO, and restoring from backups is the lowest-cost approach for a 12-hour RTO.`],wrong:[[`Keep a scaled-down but fully functional copy of the whole environment running in the second Region and replicate the data`,`Warm standby keeps a copy running in another Region. The page calls it a more complex strategy than backups, and a 12-hour RTO does not require that cost.`],[`Run the workload in both Regions at the same time, serve users from both Regions and replicate the data between them`,`Multi-site active/active is the most complex and costly approach, far more than a 12-hour RTO requires.`],[`Keep the database and instances in one Region and use a Multi-AZ deployment for recovery`,`A Multi-AZ deployment keeps its standby replica in a different Availability Zone of the same Region, so it does not protect against a Regional disaster.`]],slot:1,evidence:[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`dr-options|Or, you can use AWS Backup to copy backups across accounts and to other AWS Regions.`,`aws-backup-plan-options|You can also create a cron expression that creates snapshot backups as frequently as hourly.`,`dr-options|Disaster recovery strategies available to you within AWS can be broadly categorized into four approaches, ranging from the low cost and low complexity of making backups to more complex strategies using multiple active Regions.`,`dr-options|This approach extends the pilot light concept and decreases the time to recovery because your workload is always-on in another Region.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`]}),t({id:`disaster-bunker-003`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:1,tags:[`trap:dr-strategies`],stem:`A company replicates its database to a second Region and provisions a copy of its core infrastructure there. The application servers in that Region are loaded with code and configuration but switched off until a failover. Which disaster recovery strategy BEST describes this design?`,correct:[`Pilot light`,`Data is replicated to another Region and a copy of the core infrastructure is provisioned, while the application servers stay switched off until failover.`],wrong:[[`Warm standby`,`Warm standby keeps a scaled-down but fully functional copy running, so its application servers would already be on.`],[`Backup and restore`,`This strategy restores data from backups at failover, without core infrastructure that is always available in the second Region.`],[`Multi-site active/active`,`This strategy runs the workload in several Regions at once and serves traffic from all of them.`]],slot:2,evidence:[`dr-options|With the pilot light approach, you replicate your data from one Region to another and provision a copy of your core workload infrastructure.`,`dr-options|Other elements, such as application servers, are loaded with application code and configurations, but are "switched off" and are only used during testing or when disaster recovery failover is invoked.`,`dr-options|Unlike the backup and restore approach, your core infrastructure is always available and you always have the option to quickly provision a full scale production environment by switching on and scaling out your application servers.`]}),e({id:`disaster-bunker-004`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:2,tags:[`trap:dr-strategies`],stem:`A company uses a pilot light strategy for an application that stores uploads in Amazon S3 and session data in Amazon DynamoDB. The company wants continuous cross-Region replication of both data stores so that the RPO stays near zero, with the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Configure Amazon S3 Replication from the upload bucket to a bucket in the DR Region`,`S3 Replication provides continuous, cross-Region, asynchronous replication of objects.`],[`Convert the table to an Amazon DynamoDB global table with a replica in the DR Region`,`DynamoDB global tables provide continuous, cross-Region, asynchronous replication of table data.`]],wrong:[[`Run an AWS Lambda function every hour that copies new objects and exported table data to the DR Region`,`An hourly copy is not continuous replication, leaves a recovery point up to an hour old, and is custom code to maintain.`],[`Schedule a nightly AWS Backup plan that copies both data stores to a vault in the DR Region`,`A nightly backup leaves a recovery point up to a day old, and the backups must still be restored at failover.`],[`Take Amazon EBS snapshots of the application servers and copy them to the DR Region`,`EBS snapshots are point-in-time backups of volumes and do not replicate S3 objects or DynamoDB items.`]],slots:[0,3],evidence:[`dr-options|AWS provides continuous, cross-region, asynchronous data replication for data using the following services and resources: Amazon Simple Storage Service (Amazon S3) Replication Amazon RDS read replicas Amazon Aurora global databases Amazon DynamoDB global tables`,`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`]}),t({id:`disaster-bunker-005`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:3,tags:[`trap:dr-strategies`],stem:`A company uses backup and restore for an Amazon EC2 application, with backups copied to a second Region. In a DR test the data restore finished in 1 hour, but engineers then spent 10 hours recreating networking, load balancers and instance configuration by hand, which exceeds the 4-hour RTO. The company wants to meet the RTO at the LOWEST additional cost. Which action should the company take?`,correct:[`Define the infrastructure in AWS CloudFormation templates and deploy them in the second Region at recovery`,`Deploying with infrastructure as code lets the infrastructure be redeployed quickly without errors, which removes the manual rebuild time without keeping extra resources running.`],wrong:[[`Take database backups every 15 minutes instead of every hour and copy each one to the second Region`,`Backup frequency sets the recovery point (RPO), so it does not shorten the time to rebuild the infrastructure.`],[`Keep a scaled-down but fully functional copy of the whole environment running in the second Region at all times`,`Warm standby would shorten recovery but runs an environment all the time, which costs more than fixing the redeployment step.`],[`Enable S3 versioning on the bucket that stores the copied backups in the second Region and keep older versions`,`Versioning protects objects from deletion or modification and does not speed up redeploying infrastructure.`]],slot:3,evidence:[`dr-options|Without IaC, it may be complex to restore workloads in the recovery Region, which will lead to increased recovery times and possibly exceed your RTO.`,`dr-options|To enable infrastructure to be redeployed quickly without errors, you should always deploy using infrastructure as code (IaC)`,`dr-options|Object versioning protects your data in S3 from the consequences of deletion or modification actions by retaining the original version before the action.`]}),t({id:`disaster-bunker-006`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:1,stem:`A company runs an application behind an Application Load Balancer in one Region and keeps a standby copy behind another load balancer in a second Region. Users must be sent to the standby only when the primary is unhealthy, with the LEAST operational effort. Which Amazon Route 53 configuration meets this requirement?`,correct:[`Create primary and secondary failover records, with health checking set for the primary record`,`The failover routing policy is used for active-passive failover, and Route 53 answers with the secondary only when the primary is unhealthy.`],wrong:[[`Create two weighted records with equal weights, one for each load balancer, and enable Evaluate Target Health`,`Weighted records are an active-active configuration that sends traffic to both load balancers all the time.`],[`Create two geolocation records that send each country to one of the load balancers, with health checks`,`Geolocation is an active-active routing policy that splits users between the sites, not a primary and a standby.`],[`Create two latency records, one for each load balancer, and associate a health check with each of them`,`Latency records are active-active, so users nearest the standby would be sent there while the primary is healthy.`]],slot:0,evidence:[`route53-failover-types|You configure active-active failover using any routing policy (or combination of routing policies) other than failover, and you configure active-passive failover using the failover routing policy.`,`route53-failover-types|When the primary resource is unhealthy, Route 53 responds to DNS queries using the secondary record.`]}),t({id:`disaster-bunker-007`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:2,tags:[`trap:cloudfront-vs-global-accelerator`],stem:`A company runs an application in two Regions. Some client networks cache DNS answers for longer than the record TTL, so failover through DNS is slow for them. Traffic must move automatically to the healthy Regional endpoint, and clients should keep using the same static IP addresses. Which solution BEST meets these requirements?`,correct:[`Use AWS Global Accelerator with an endpoint in each Region and let its health checks route to the healthy one`,`Global Accelerator health checks route user traffic to a healthy endpoint behind the same static IP addresses, and it avoids the caching issues of DNS.`],wrong:[[`Use Amazon Route 53 failover records with health checks and set a low TTL on each of the records in the hosted zone`,`Clients would still depend on DNS answers, which some networks cache for longer than the TTL, so failover stays slow for them.`],[`Use Amazon CloudFront with an origin group that holds the primary and secondary Regional endpoints as its origins`,`CloudFront origin failover is done per request, and all subsequent requests still go to the primary endpoint.`],[`Use Route 53 weighted records and change the weights by hand when the primary Region fails or becomes unhealthy`,`Changing weights is a manual control plane operation, and clients would still depend on cached DNS answers.`]],slot:1,evidence:[`dr-options|Using AnyCast IP, you can associate multiple endpoints in one or more AWS Regions with the same static public IP address or addresses.`,`dr-options|Global Accelerator health checks monitor endpoints.`,`dr-options|Global Accelerator also avoids caching issues that can occur with DNS systems (like Route 53).`,`dr-options|Unlike the failover operations described previously, all subsequent requests still go to the primary endpoint, and failover is done per each request.`]}),e({id:`disaster-bunker-008`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:3,stem:`A company uses an active/passive design with its recovery site in a second Region. The company wants the failover operation to rely only on data plane operations, which have higher availability design goals than control plane operations. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use Amazon Route 53 health checks with failover records so that DNS shifts traffic to the recovery Region automatically`,`Automatically initiated DNS failover based on Route 53 health checks is a highly reliable operation done on the data plane.`],[`Deploy enough capacity in the recovery Region ahead of time to handle the full production load`,`A statically stable configuration does not depend on Auto Scaling, which is a control plane activity, during the failover.`]],wrong:[[`Change the weights of weighted DNS records at failover time so that all traffic goes to the recovery Region`,`Changing the weights is a control plane operation, which makes it less resilient than a data plane approach.`],[`Raise the desired capacity of the Auto Scaling group in the recovery Region when the failover starts`,`Auto Scaling is a control plane activity, so depending on it lowers the resiliency of the recovery strategy.`],[`Restore the production database in the recovery Region from the latest backup when the failover starts`,`Restoring data from a backup is a control plane operation, so it should not be needed during the failover itself.`]],slots:[1,4],evidence:[`dr-options|For maximum resiliency, you should use only data plane operations as part of your failover operation.`,`dr-options|Using these health checks, you can configure automatically initiated DNS failover to ensure traffic is sent only to healthy endpoints, which is a highly reliable operation done on the data plane.`,`dr-options|Because Auto Scaling is a control plane activity, taking a dependency on it will lower the resiliency of your overall recovery strategy.`,`dr-options|However, be aware this is a control plane operation and therefore not as resilient as the data plane approach`,`dr-options|Implementing a scheduled periodic data restore is a good idea as data restore from backup is a control plane operation.`]}),t({id:`disaster-bunker-009`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:2,stem:`A company runs an active/passive application across two Regions. A false-alarm failover would cause avoidable data loss, so the company wants engineers to decide when to fail over. After that decision, recovery must be fast and repeatable. Which approach BEST meets these requirements?`,correct:[`Automate every failover step in a tested script that engineers start by hand when they decide to fail over`,`Manual initiation avoids false-alarm failovers, and automated steps make the failover quick and repeatable, like the push of a button.`],wrong:[[`Configure Amazon Route 53 health checks so that failover starts automatically when the primary looks unhealthy`,`Automatically initiated failover has to be used with caution because a false alarm incurs losses, and no engineer decides.`],[`Write a runbook of console steps that engineers carry out one by one after they decide to fail over`,`The steps are not automated, so recovery would be slower and less repeatable than a scripted failover.`],[`Create an Amazon CloudWatch alarm that invokes an AWS Lambda function to promote the replica and redirect traffic`,`The alarm starts the failover with no engineer deciding, so a false alarm would trigger it.`]],slot:2,evidence:[`dr-options|Automatically initiated failover based on health checks or alarms should be used with caution.`,`dr-options|If you fail over when you don’t need to (false alarm), then you incur those losses.`,`dr-options|Manually initiated failover is therefore often used.`,`dr-options|In this case, you should still automate the steps for failover, so that the manual initiation is like the push of a button.`]}),t({id:`disaster-bunker-010`,building:`disaster-bunker`,bullets:[`2.2-S6`],d:2,tags:[`trap:dr-strategies`],stem:`A company runs a well-architected, highly available workload across multiple Availability Zones. Its DR requirement covers only the disruption or loss of one physical data center, and no regulation requires surviving the loss of a Region. The company wants the LOWEST cost and complexity. Which strategy meets this requirement?`,correct:[`Backup and restore, with periodic backups of the data and the infrastructure definitions`,`For the loss of one data center in a highly available workload, backup and restore may be all that is required, and it has the lowest cost and complexity.`],wrong:[[`Pilot light, with data replicated to a second Region and core infrastructure provisioned there`,`Pilot light is intended for disasters that reach a Region, which this requirement does not include, and it costs more.`],[`Warm standby, with a scaled-down but fully functional copy running in a second Region`,`Warm standby keeps an environment running all the time for a Regional disaster that the requirement does not cover.`],[`Multi-site active/active, with the workload serving traffic from two Regions at once`,`This is the most complex and costly approach, far beyond a requirement that covers one data center.`]],slot:3,evidence:[`dr-options|For a disaster event based on disruption or loss of one physical data center for a well-architected, highly available workload, you may only require a backup and restore approach to disaster recovery.`,`dr-options|If your definition of a disaster goes beyond the disruption or loss of a physical data center to that of a Region or if you are subject to regulatory requirements that require it, then you should consider Pilot Light, Warm Standby, or Multi-Site Active/Active.`]}),t({id:`disaster-bunker-011`,building:`disaster-bunker`,bullets:[`2.2-S6`],d:2,tags:[`trap:dr-strategies`],stem:`A company needs to recover in a second Region after a Regional disaster. The recovery environment must be able to handle user traffic immediately at reduced capacity and then scale up. The company does not want the cost and complexity of serving production traffic from both Regions all the time. Which strategy BEST meets these requirements?`,correct:[`Warm standby, with a scaled-down but fully functional copy of production running in the second Region`,`Warm standby can handle traffic at reduced capacity immediately and only needs to scale up, and it is more economical than running active/active.`],wrong:[[`Pilot light, with the core infrastructure provisioned in the second Region and the application servers switched off`,`Pilot light cannot process requests until additional action is taken, so it cannot handle traffic immediately.`],[`Backup and restore, with backups copied to the second Region and restored into new infrastructure at failover`,`Data stored as backups must be restored at failover, so nothing can handle traffic immediately.`],[`Multi-site active/active, with the workload serving production traffic from both Regions all the time`,`This is the most complex and costly approach, and it serves traffic from both Regions all the time.`]],slot:0,evidence:[`dr-options|The distinction is that pilot light cannot process requests without additional action taken first, whereas warm standby can handle traffic (at reduced capacity levels) immediately.`,`dr-options|Alternatively, if you do not want to use both Regions to handle user traffic, then Warm Standby offers a more economical and operationally less complex approach.`,`dr-options|Any data stored in the disaster recovery Region as backups must be restored at time of failover.`]}),t({id:`disaster-bunker-012`,building:`disaster-bunker`,bullets:[`2.2-S6`],d:3,tags:[`trap:dr-strategies`],stem:`A company's payment platform needs a recovery time near zero if a whole Region fails, and it must also be recoverable if an engineer corrupts or deletes data. Users connect from several continents, and the company accepts the highest complexity and cost. Which design BEST meets these requirements?`,correct:[`Multi-site active/active across two Regions, with data replication and point-in-time backups`,`Active/active can reduce recovery time to near zero, and backups are still needed because replicated data can be corrupted or deleted.`],wrong:[[`Multi-site active/active across two Regions, with data replication only and no point-in-time backups`,`Replication also copies corruption or deletion, so the strategy must include point-in-time backups as well.`],[`Warm standby in a second Region, with data replication and point-in-time backups of the data stores`,`The warm standby copy runs at reduced capacity and must scale up, so recovery time is not near zero.`],[`Pilot light in a second Region, with data replication and point-in-time backups of the data stores`,`Pilot light cannot process requests until servers are switched on, so recovery time is not near zero.`]],slot:1,evidence:[`dr-options|This approach is the most complex and costly approach to disaster recovery, but it can reduce your recovery time to near zero for most disasters with the correct technology choices and implementation`,`dr-options|In addition to replication, your strategy must also include point-in-time backups to protect against data corruption or destruction events.`,`dr-options|The distinction is that pilot light cannot process requests without additional action taken first, whereas warm standby can handle traffic (at reduced capacity levels) immediately.`]}),e({id:`disaster-bunker-013`,building:`disaster-bunker`,bullets:[`2.2-K4`,`2.2-S6`],d:3,tags:[`trap:dr-strategies`],stem:`A company uses pilot light with continuous cross-Region replication of its database to meet an RPO of seconds. A security review warns that an attacker with stolen credentials could delete data in the primary Region, and the deletion would replicate. The company must be able to recover the deleted data. Which TWO actions will BEST meet these requirements? (Choose two.)`,correct:[[`Create point-in-time backups of the replicated data in the DR Region`,`Continuous replication may not protect against unauthorized deletion as well as point-in-time backups, and the replicated data can be backed up in the DR Region.`],[`Use AWS Backup to copy backups to a separate AWS account`,`The cross-account backup capability helps protect from disaster events that include insider threats or account compromise.`]],wrong:[[`Add a second cross-Region replica of the database in another DR Region`,`Another replica receives the same replicated deletion, so it adds no way to recover the deleted data.`],[`Switch to multi-site active/active so that both Regions serve traffic`,`This strategy still replicates data, including deletions, and must also include point-in-time backups.`],[`Increase the number of application servers that run in the DR Region`,`More servers add capacity but give no way to recover deleted data.`]],slots:[0,2],evidence:[`dr-options|Continuous replication of data has the advantage of being the shortest time (near zero) to back up your data, but may not protect against disaster events such as data corruption or malicious attack (such as unauthorized data deletion) as well as point-in-time backups.`,`dr-options|You can back up the replicated data in the disaster Region to create point-in-time backups in that same Region.`,`dr-options|The cross-account backup capability helps protect from disaster events that include insider threats or account compromise.`]}),t({id:`disaster-bunker-014`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:2,stem:`A company runs identical copies of an application in two Regions, and both must serve users all the time. The company wants Amazon Route 53 to answer each user with the Region that gives the lowest latency and to stop returning a Region whose endpoint is unhealthy. Which configuration meets these requirements with the LEAST operational effort?`,correct:[`Create a latency record for each Region and associate a health check with each record`,`Active-active failover uses a routing policy other than failover, and Route 53 stops including a resource that it considers unhealthy.`],wrong:[[`Create a primary and a secondary failover record for the two Regions`,`Failover routing is active-passive, so the secondary would receive queries only when the primary is unhealthy.`],[`Create a latency record for each Region without associating any health checks`,`Without health checking Route 53 cannot detect an unhealthy endpoint, so it would keep returning the failed Region.`],[`Create a weighted record for each Region with equal weights and a health check on each`,`Weighted records split users by weight rather than sending each user to the Region with the lowest latency.`]],slot:2,evidence:[`route53-failover-types|Use this failover configuration when you want all of your resources to be available the majority of the time.`,`route53-failover-types|When a resource becomes unavailable, Route 53 can detect that it's unhealthy and stop including it when responding to queries.`,`route53-failover-types|You configure active-active failover using any routing policy (or combination of routing policies) other than failover, and you configure active-passive failover using the failover routing policy.`]}),t({id:`disaster-bunker-015`,building:`disaster-bunker`,bullets:[`2.2-S6`],d:2,tags:[`trap:dr-strategies`],stem:`A company uses backup and restore for a database, with a nightly backup copied to a second Region. The business now requires an RPO of a few seconds in a Regional disaster, and the company wants to keep application servers switched off to limit cost. Which change BEST meets the new requirement?`,correct:[`Replicate the database continuously to a live database in the second Region and keep servers off`,`For pilot light, continuous data replication to live data stores in the DR Region is the best approach for a low RPO, and the servers stay off until failover.`],wrong:[[`Run the database backup every hour instead of nightly and copy each backup to the second Region`,`Even hourly backups leave a recovery point up to an hour old, so an RPO of a few seconds is not met.`],[`Keep the nightly backup and extend the retention period of the backup copies held in the second Region`,`Longer retention keeps backups for longer but does not make the latest recovery point any newer.`],[`Switch to multi-site active/active, with the workload serving production traffic from both Regions`,`This can meet the RPO, but it is the most complex and costly approach and runs servers all the time.`]],slot:3,evidence:[`dr-options|For pilot light, continuous data replication to live databases and data stores in the DR region is the best approach for low RPO (when used in addition to the point-in-time backups discussed previously).`,`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`dr-options|A pilot light approach minimizes the ongoing cost of disaster recovery by minimizing the active resources, and simplifies recovery at the time of a disaster because the core infrastructure requirements are all in place.`]}),t({id:`disaster-bunker-016`,building:`disaster-bunker`,bullets:[`2.2-K4`],d:2,tags:[`mock-reserve`],stem:`A company uses Amazon S3 Replication to copy objects to a bucket in a DR Region. The replication rule uses the latest version of the replication configuration, with a Filter element. After a malicious deletion in the source bucket, the company wants the objects in the DR Region to remain available. Which approach meets this requirement with the LEAST effort?`,correct:[`Leave delete marker replication turned off on the replication rule, so a delete adds a delete marker in the source bucket only`,`With the latest configuration version the delete marker is not replicated by default, so it stays in the source bucket only, which protects data in the DR Region from malicious deletions in the source Region.`],wrong:[[`Configure the replication rule to also replicate delete markers from the source bucket to the DR bucket`,`Replicating delete markers sends the deletion to the DR bucket as well, which is what the company wants to avoid.`],[`Turn on S3 Replication Time Control for the replication rule between the source and the DR bucket`,`Replication Time Control is for monitoring replication times and does not change how deletes are handled.`],[`Replicate the objects to a second bucket in the source Region instead of to a bucket in the DR Region`,`A second bucket in the source Region does not protect the data from the loss of that Region.`]],slot:0,evidence:[`dr-options|If you are using S3 replication to back up data to your DR region, then, by default, when an object is deleted in the source bucket, Amazon S3 adds a delete marker in the source bucket only.`,`dr-options|This approach protects data in the DR Region from malicious deletions in the source Region.`,`s3-replication-what-is-isnot-replicated|If you are using the latest version of the replication configuration (that is, you specify the Filter element in a replication configuration rule), Amazon S3 does not replicate the delete marker by default.`,`dr-options|You can also configure whether or not to replicate delete markers between buckets in your active Regions.`,`dr-options|Actual replication times can be monitored using service features like S3 Replication Time Control (S3 RTC) for S3 objects and management features of Amazon Aurora global databases.`]}),t({id:`disaster-bunker-017`,building:`disaster-bunker`,bullets:[`2.2-K6`],d:3,tags:[`mock-reserve`],stem:`A company runs an internal application in a primary Region and a standby Region. The failover records are in an Amazon Route 53 private hosted zone, and the instances have only private IP addresses. Route 53 must fail over to the standby when the primary instances fail their EC2 status checks. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create a CloudWatch alarm on the status check metric and a Route 53 health check based on that alarm`,`Route 53 health checkers are outside the VPC, so a health check based on the data stream of a CloudWatch alarm can check instances that have only private IP addresses.`],wrong:[[`Create a Route 53 health check that monitors the private IP address of each of the primary instances`,`Route 53 health checkers are outside the VPC, so they cannot check an instance that has only a private IP address.`],[`Create a calculated health check that monitors the status of all of the other health checks in the zone`,`A calculated health check only combines the status of other health checks, and none of them could reach the instances.`],[`Create the failover records without any health checks and rely on the failover routing policy alone`,`Active-passive failover needs health checking to detect an unhealthy primary, so the policy alone never fails over.`]],slot:1,evidence:[`route53-failover-private|Route 53 health checkers are outside the VPC.`,`route53-failover-private|To check the health of an endpoint within a VPC by IP address, you must assign a public IP address to the instance in the VPC.`,`route53-failover-private|For example, you might create a CloudWatch metric that checks the status of the EC2 StatusCheckFailed metric, add an alarm to the metric, and then create a health check that is based on the data stream for the alarm to check instances within a Virtual Private Cloud (VPC) that only have private IP addresses.`,`route53-hc-types|You can create a health check that monitors whether Route 53 considers other health checks healthy or unhealthy.`]})],s=[t({id:`durable-dock-001`,postGuide:[`s3-express-one-zone`],building:`durable-dock`,bullets:[`2.2-K11`],d:1,tags:[`trap:s3-storage-classes`],stem:`A company keeps scanned contracts in Amazon S3. The objects are read about once a month, need millisecond access, and must stay available if an entire Availability Zone fails. The company wants the LOWEST storage cost that meets these requirements. Which storage class should the company use?`,correct:[`S3 Standard-IA, which stores objects across at least three Availability Zones`,`Standard-IA is designed for long-lived, infrequently accessed data and keeps objects in multiple Availability Zones, so it survives the loss of one.`],wrong:[[`S3 One Zone-IA, which stores objects redundantly within a single Availability Zone`,`Objects are held in one Availability Zone, so an Availability Zone failure can make them unavailable.`],[`S3 Express One Zone, which stores objects redundantly within a single Availability Zone`,`This class also keeps data in one Availability Zone, and it targets latency-sensitive applications rather than monthly reads.`],[`S3 Standard, which is designed for data that is read more than once a month`,`It is built for frequently accessed data, so it is not the lowest-cost fit for objects read about once a month.`]],slot:0,evidence:[`s3-durability|S3 Standard, S3 Intelligent-Tiering, S3 Standard-IA, S3 Glacier Instant Retrieval, S3 Glacier Flexible Retrieval, and S3 Glacier Deep Archive redundantly store objects on multiple devices across a minimum of three Availability Zones in an AWS Region.`,`s3-durability|The S3 One Zone-IA storage class stores data redundantly across multiple devices within a single Availability Zone.`,`s3-storage-classes|The S3 Standard-IA and S3 One Zone-IA storage classes are designed for long-lived and infrequently accessed data.`,`s3-storage-classes|S3 Standard (STANDARD) Frequently accessed data (more than once a month) with millisecond access`]}),t({id:`durable-dock-002`,building:`durable-dock`,bullets:[`2.2-K11`],d:2,tags:[`trap:ebs-efs-fsx`],stem:`Linux web servers in three Availability Zones must share one directory of user uploads through NFS. The files must stay available if any one Availability Zone becomes unavailable, and the company wants the LEAST operational overhead. Which storage solution meets these requirements?`,correct:[`An Amazon EFS Regional file system that the servers in all three zones mount`,`A Regional file system stores data redundantly across multiple Availability Zones, so the shared directory stays reachable when one zone is down.`],wrong:[[`An Amazon EFS One Zone file system that the servers in all three zones mount`,`A One Zone file system keeps its data in a single Availability Zone, so that zone failing makes the uploads unavailable.`],[`An Amazon EBS io2 volume with Multi-Attach enabled and attached to every server`,`Multi-Attach works only for instances in the same Availability Zone, so servers in the other zones cannot use the volume.`],[`An Amazon EBS volume on one server, shared to the others by an NFS export`,`The volume and its server sit in one Availability Zone and the export adds a server to manage, so a zone failure loses the uploads.`]],slot:1,evidence:[`efs-features|Regional – Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`,`efs-features|Storing data across multiple Availability Zones provides continuous availability to the data, even when one or more Availability Zones in an AWS Region are unavailable.`,`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`]}),t({id:`durable-dock-003`,building:`durable-dock`,bullets:[`2.2-S5`],d:1,stem:`A team keeps build reports in an Amazon S3 bucket. Developers sometimes overwrite or delete an object by mistake, and the team must be able to get back an earlier copy of any object. Which action BEST meets this requirement?`,correct:[`Enable S3 Versioning so that overwrites and deletes keep earlier versions`,`Versioning preserves every version of every object, so an earlier version can be restored after an overwrite or delete.`],wrong:[[`Enable default encryption with an AWS KMS key so that objects are protected`,`Encryption protects confidentiality but does not keep an earlier copy after an overwrite or delete.`],[`Create a lifecycle rule that moves objects to S3 Glacier Flexible Retrieval`,`A transition changes the storage class of the current object and does not keep the copy that an overwrite replaces.`],[`Turn on S3 Intelligent-Tiering so that objects move between access tiers`,`Access tiers change cost by access pattern and do not preserve earlier versions of an object.`]],slot:2,evidence:[`s3-versioning|You can use the S3 Versioning feature to preserve, retrieve, and restore every version of every object stored in your buckets.`,`s3-versioning|For example, if you delete an object, Amazon S3 inserts a delete marker instead of removing the object permanently.`,`s3-durability|With versioning, you can easily recover from both unintended user actions and application failures.`]}),t({id:`durable-dock-004`,building:`durable-dock`,bullets:[`2.2-K11`],d:2,stem:`A company created an Amazon S3 replication rule from a bucket in one Region to a bucket in another Region. The source bucket already holds millions of objects, but only objects uploaded after the rule was created appear in the destination. The company wants the existing objects copied as well, with the LEAST custom code. Which solution meets this requirement?`,correct:[`Run an S3 Batch Replication job for the objects that already exist`,`Batch Replication is the on-demand action that replicates existing objects, which live replication does not copy.`],wrong:[[`Enable S3 Replication Time Control on the replication rule for the bucket`,`This option speeds up and measures replication of new objects, and it does not copy objects that existed before the rule.`],[`Add a second replication rule with an empty filter that matches all objects`,`Live replication skips objects that existed before replication was set up, however many rules match them.`],[`Enable S3 Versioning again on the source bucket and the destination bucket`,`Versioning is already required for the rule to exist, and turning it on again copies no older objects.`]],slot:3,evidence:[`s3-replication|Live replication doesn't replicate any objects that existed in the bucket before you set up replication.`,`s3-replication|On-demand replication – To replicate existing objects from the source bucket to one or more destination buckets on demand, use S3 Batch Replication.`,`s3-replication|S3 RTC replicates 99.99 percent of new objects stored in Amazon S3 within 15 minutes (backed by a service-level agreement).`]}),t({id:`durable-dock-005`,building:`durable-dock`,bullets:[`2.2-K11`],d:2,stem:`A bank must keep a copy of the objects in an Amazon S3 bucket in a second Region. A policy requires new objects to be replicated within a predictable time frame that is backed by a service-level agreement. Which configuration meets this requirement with the LEAST administrative effort?`,correct:[`A Cross-Region Replication rule with S3 Replication Time Control enabled`,`Cross-Region Replication places copies in another Region, and Replication Time Control adds the 15-minute, SLA-backed time frame.`],wrong:[[`A Same-Region Replication rule with S3 Replication Time Control enabled`,`The copy would stay in the same Region as the source, so the second-Region requirement is not met.`],[`A Cross-Region Replication rule with replication metrics sent to Amazon CloudWatch`,`Metrics let the bank monitor replication, but they carry no time commitment or service-level agreement.`],[`A scheduled S3 Batch Replication job that runs on a recurring basis`,`Batch Replication is an on-demand action, and it comes with no predictable time frame for new objects.`]],slot:0,evidence:[`s3-replication|Replicate objects within 15 minutes – To replicate your data in the same AWS Region or across different Regions within a predictable time frame, you can use S3 Replication Time Control (S3 RTC).`,`s3-replication|Cross-Region Replication (CRR) – You can use CRR to replicate objects across Amazon S3 buckets in different AWS Regions.`,`s3-replication|S3 RTC replicates 99.99 percent of new objects stored in Amazon S3 within 15 minutes (backed by a service-level agreement).`]}),t({id:`durable-dock-006`,building:`durable-dock`,bullets:[`2.2-S5`,`2.2-K11`],d:3,tags:[`trap:instance-store-vs-ebs`],stem:`An application runs on one Amazon EC2 instance with its data on an Amazon EBS gp3 volume. The company needs to be able to bring the application back in a different Availability Zone of the same Region with its data intact if the current zone is disrupted, with the LEAST ongoing management. Which solution meets these requirements?`,correct:[`Back up the volume on a schedule with AWS Backup and restore it in another zone`,`Snapshot data is replicated across the Availability Zones in the Region, so a new volume can be restored in any of them from the scheduled backups.`],wrong:[[`Change the volume to io2 Block Express and keep the instance in the same zone`,`The highest-durability volume type still lives in one Availability Zone, so a zone disruption leaves the data unreachable.`],[`Enable Multi-Attach on the volume and attach it to a standby instance in a second zone`,`Multi-Attach supports only instances in the same Availability Zone as the volume, so a standby in another zone cannot attach.`],[`Move the data to instance store volumes on a larger instance in the same zone`,`Instance store data is lost when the instance fails or stops, and the instance still sits in the single disrupted zone.`]],slot:1,evidence:[`ebs-snapshots|Snapshot data is automatically replicated across all Availability Zones in the Region.`,`ebs-snapshots|For data resiliency and disaster recovery, it is your responsibility to create EBS snapshots on a regular basis, or to set up automatic snapshot creation by using Automate backups with Amazon Data Lifecycle Manager or AWS Backup.`,`ebs-volumes|The volume and instance must be in the same Availability Zone.`,`ebs-what-is|Data availability and durability — io2 Block Express volumes provide 99.999% durability with an annual failure rate of 0.001%.`]}),t({id:`durable-dock-007`,building:`durable-dock`,postGuide:[`backup-hourly-frequency`],postGuideKey:[`backup-hourly-frequency`],bullets:[`2.2-S5`],d:3,stem:`A research company writes analysis output to an Amazon EFS Regional file system. A faulty job occasionally corrupts files, and the damage is noticed hours later. The company needs to restore files to an earlier point in time with a recovery point objective of one hour, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an AWS Backup plan that runs at least hourly and restore from a recovery point`,`Backups are point-in-time copies whose frequency sets the achievable recovery point, so files can be restored to a state from before the corruption.`],wrong:[[`Enable EFS replication to a file system in a second Region and fail over to the replica`,`Replication copies changes to the destination continuously, so the corrupted files reach the replica as well.`],[`Migrate to an EFS One Zone file system that AWS Backup protects automatically`,`Changing the storage class does not choose a backup frequency: the one-hour recovery point still needs a backup schedule that runs hourly, and the migration adds work and keeps all data in one Availability Zone.`],[`Turn on EFS lifecycle management so that older files move to Infrequent Access`,`Lifecycle management moves files between storage classes by access time and keeps no earlier copy of a corrupted file.`]],slot:2,evidence:[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`dr-options|Continuous data replication protects you against some types of disaster, but it may not protect you against data corruption or destruction unless your strategy also includes versioning of stored data or options for point-in-time recovery.`,`aws-backup-plan-options|You can also create a cron expression that creates snapshot backups as frequently as hourly.`,`efs-replication|When you enable replication on an EFS file system, Amazon EFS automatically and transparently replicates the data and metadata on the source file system to a destination file system.`]}),t({id:`durable-dock-008`,building:`durable-dock`,bullets:[`2.2-S5`],d:2,stem:`A company has Amazon EBS volumes, Amazon EFS file systems and Amazon DynamoDB tables spread over many accounts in AWS Organizations. Auditors want one place to define backup schedules and retention for all of them, applied to resources by tag. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use AWS Backup with backup plans and organization policies that select resources by tag`,`AWS Backup centralises backup management across services and accounts and applies backup plans to tagged resources.`],wrong:[[`Run AWS Lambda functions on Amazon EventBridge schedules that call each service's backup API`,`This is custom code to write and maintain in every account, and there is no single place for schedules and retention.`],[`Configure each service's own scheduled backup settings separately in every account`,`Schedules and retention would live in many places per service and account, not in the single place the auditors want.`],[`Use AWS Systems Manager Run Command to run snapshot scripts on instances in each account`,`Scripts on instances cannot back up Amazon EFS file systems or DynamoDB tables, and they are scripts to maintain.`]],slot:3,evidence:[`backup-what-is|With AWS Backup, you can centrally manage backup policies that meet your backup requirements.`,`backup-what-is|With cross-account management, you can automatically use backup policies to apply backup plans across the AWS accounts within your organization.`,`backup-what-is|Integration with AWS tags enables you to quickly apply a backup plan to a group of AWS resources, so that they are backed up in a consistent and compliant manner.`]}),e({id:`durable-dock-009`,building:`durable-dock`,bullets:[`2.2-S5`],d:3,stem:`A company must keep copies of its production backups in a second AWS Region for business continuity. Backups of Amazon EBS volumes, Amazon EFS file systems and Amazon RDS databases must run on a schedule, and every resource tagged backup=prod must be included automatically. The company wants the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Add a copy to a destination Region to the rule of an AWS Backup plan that schedules the backups`,`A backup plan can copy backups to another Region automatically as part of the schedule.`],[`Assign resources to the backup plan by the backup=prod tag`,`Tag-based assignment applies the plan to every tagged resource, including resources created later.`]],wrong:[[`Copy a manual snapshot of each resource to the second Region once a week`,`This is manual work that also leaves long gaps between copies, where the plan copies on its schedule.`],[`Enable Amazon EFS replication to the second Region for the file systems`,`This covers only the file systems, and the EBS volumes and RDS databases would still have no copies in the second Region.`],[`Run a script on an Amazon EC2 instance that calls each service's copy API every night`,`A script on an instance is custom code to maintain and does not apply to resources through tags.`]],slots:[1,3],evidence:[`backup-what-is|Using AWS Backup, you can copy backups to multiple different AWS Regions on demand or automatically as part of a scheduled backup plan.`,`backup-what-is|Integration with AWS tags enables you to quickly apply a backup plan to a group of AWS resources, so that they are backed up in a consistent and compliant manner.`]}),e({id:`durable-dock-010`,building:`durable-dock`,bullets:[`2.2-K11`],d:2,tags:[`trap:ebs-efs-fsx`,`trap:s3-storage-classes`],stem:`A company is choosing storage for new workloads. The data must stay available if an entire Availability Zone in the Region becomes unavailable, and the company will not set up replication or copy backups for this requirement. Which TWO storage options meet this requirement with the LEAST configuration? (Choose two.)`,correct:[[`An Amazon S3 bucket that uses the S3 Standard-IA storage class`,`The class stores objects across a minimum of three Availability Zones, so it is designed to sustain the loss of one.`],[`An Amazon EFS file system of the Regional type`,`Regional file systems store data redundantly across multiple Availability Zones in the Region.`]],wrong:[[`An Amazon S3 bucket that uses the S3 One Zone-IA storage class`,`This class stores its data in a single Availability Zone.`],[`An Amazon EFS file system of the One Zone type`,`One Zone file systems store data within a single Availability Zone, and data there may be lost if the zone is damaged.`],[`An Amazon EBS gp3 volume attached to an Amazon EC2 instance`,`An EBS volume is tied to one Availability Zone, so it needs snapshots or other copies to cover a zone failure.`]],slots:[0,2],evidence:[`s3-durability|S3 Standard, S3 Intelligent-Tiering, S3 Standard-IA, S3 Glacier Instant Retrieval, S3 Glacier Flexible Retrieval, and S3 Glacier Deep Archive redundantly store objects on multiple devices across a minimum of three Availability Zones in an AWS Region.`,`efs-features|Regional – Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`,`efs-features|One Zone – One Zone file systems store data within a single Availability Zone.`]}),e({id:`durable-dock-011`,building:`durable-dock`,bullets:[`2.2-K11`,`2.2-S5`],d:3,tags:[`mock-reserve`],stem:`An S3 bucket holds customer documents. The company must be able to recover a document after an accidental overwrite or deletion, and must also keep a copy of every new object in a different AWS Region. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Enable S3 Versioning on the source bucket and on the destination bucket`,`Versioning lets the company restore earlier versions, and replication requires versioning on both buckets.`],[`Create a Cross-Region Replication rule to a destination bucket in the other Region`,`Cross-Region Replication copies new objects to a bucket in a different Region.`]],wrong:[[`Create a Same-Region Replication rule to a second bucket in the same Region`,`The copy would stay in the same Region as the source, so the different-Region requirement fails.`],[`Enable S3 Transfer Acceleration on the source bucket for faster uploads`,`This speeds up transfers to the bucket and neither keeps earlier versions nor copies objects to another Region.`],[`Add a lifecycle rule that permanently deletes noncurrent versions after one day`,`Removing noncurrent versions quickly would discard the earlier versions the company needs to recover.`]],slots:[2,4],evidence:[`s3-replication-requirements|Both source and destination buckets must have versioning enabled.`,`s3-versioning|You can use the S3 Versioning feature to preserve, retrieve, and restore every version of every object stored in your buckets.`,`s3-replication|Cross-Region Replication (CRR) – You can use CRR to replicate objects across Amazon S3 buckets in different AWS Regions.`,`s3-lifecycle-expire|You can use the NoncurrentVersionExpiration action element to direct Amazon S3 to permanently delete noncurrent versions of objects.`]}),t({id:`durable-dock-012`,building:`durable-dock`,bullets:[`2.2-K11`],d:2,tags:[`mock-reserve`,`trap:ebs-efs-fsx`],stem:`A media company keeps project files on an Amazon EFS Regional file system. A policy requires a replica file system in another Region that stays in sync automatically, with a recovery point objective of about 15 minutes, and the team wants to rehearse failover in a game-day exercise. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Enable replication on the file system and fail over to the replica for the exercise`,`EFS replication keeps a destination file system in sync automatically and transparently, and the replica can be used for failover.`],wrong:[[`Run a nightly AWS Backup plan for the file system and copy each backup to the other Region`,`A nightly backup leaves a recovery point far beyond 15 minutes and needs a restore before the exercise.`],[`Mount both file systems on an Amazon EC2 instance and synchronise them with a scheduled rsync job`,`A scheduled copy job is custom tooling to maintain and does not keep a 15-minute recovery point by design.`],[`Switch the file system to the One Zone type and enable lifecycle management to Infrequent Access`,`A One Zone file system adds no second-Region replica, and lifecycle management only moves files between storage classes.`]],slot:0,evidence:[`efs-replication|When you enable replication on an EFS file system, Amazon EFS automatically and transparently replicates the data and metadata on the source file system to a destination file system.`,`efs-replication|After the initial replication is finished, Amazon EFS maintains a Recovery Point Objective (RPO) of 15 minutes for most file systems.`,`efs-replication|In the event of a disaster or when performing game day exercises, you can fail over to your replica file system.`]})],c=[t({id:`island-charts-001`,building:`island-charts`,bullets:[`2.2-K1`],d:1,stem:`A company runs a production web application on Amazon EC2 instances that are all in one Availability Zone. A power failure at that facility took the application offline. The company must keep all of its data in the same AWS Region and wants the SIMPLEST change that lets the application survive the loss of one facility. Which solution meets these requirements?`,correct:[`Launch the instances in subnets in at least two Availability Zones of the Region`,`Availability Zones have independent power and are physically separated, so one facility failing leaves the other zone running, and the data stays in the Region.`],wrong:[[`Run a second copy of the whole stack in another Region and replicate the data there`,`The data would leave the Region, which breaks the stated residency requirement, and the change is larger than needed.`],[`Move the instances into a cluster placement group on the same low-latency network`,`The instances would still sit in one Availability Zone, so the loss of that facility would still take them all down.`],[`Buy an On-Demand Capacity Reservation for the instance type in the current zone`,`A reservation keeps capacity in the same Availability Zone, so it does not help when that zone loses power.`]],slot:0,evidence:[`waf-multi-location|Availability Zones are resource hosting locations that are physically separated from each other to avoid correlated failures due to risks such as fires, floods, and tornadoes.`,`waf-multi-location|Deploy and operate all production workloads in at least two Availability Zones (AZs) in a Region.`]}),t({id:`island-charts-002`,building:`island-charts`,bullets:[`2.2-K1`],d:2,stem:`A company serves a global audience from Application Load Balancers in the US West (Oregon) Region and the Asia Pacific (Singapore) Region. Each DNS query should be answered with the load balancer in the Region that gives that user the lowest network latency. The company wants the LEAST ongoing administration. Which Amazon Route 53 configuration meets these requirements?`,correct:[`Create one latency record for each load balancer, each tagged with its own Region`,`Route 53 compares the latency between the user and each Region that has a latency record and answers with the record for the lowest one.`],wrong:[[`Create geolocation records that map every continent to the nearest of the two Regions`,`Geolocation answers by where the user is, not by measured latency, and every location would need its own mapping to maintain.`],[`Create weighted records with equal weights for both load balancers`,`Weighted records split queries in fixed proportions, so a user could be sent to the farther Region half of the time.`],[`Create failover records that name Oregon as primary and Singapore as secondary`,`Failover keeps all users on the primary until it is unhealthy, so users near Singapore would not get the lowest latency.`]],slot:1,evidence:[`route53-latency|To use latency-based routing, you create latency records for your resources in multiple AWS Regions.`,`route53-latency|finds which Region gives the user the lowest latency, and then picks a latency record for that Region.`]}),e({id:`island-charts-003`,building:`island-charts`,bullets:[`2.2-K1`],d:2,stem:`A media company must serve users in Europe from an Application Load Balancer in Frankfurt to meet content licensing terms, and all other users from an Application Load Balancer in Virginia. Some DNS queries come from IP addresses that Amazon Route 53 cannot map to a location, and every query must still receive an answer. The company wants the LEAST operational effort. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a geolocation record for the continent of Europe that points to the Frankfurt load balancer`,`Geolocation routing chooses the resource by where the user is located, and a record can be set for a whole continent.`],[`Create a default geolocation record that points to the Virginia load balancer`,`The default record answers queries from unmapped IP addresses and from locations that have no record of their own.`]],wrong:[[`Create latency records for both load balancers and let Route 53 pick the fastest`,`Latency routing could send European users to Virginia, which would break the licensing terms.`],[`Create a geoproximity record for each load balancer with a positive bias on Frankfurt`,`Geoproximity picks the closest resource and a bias only shifts the boundary, so it cannot guarantee the licensing split.`],[`Create weighted records that send a share of queries to each load balancer`,`Weighted records ignore where the user is, so European users would be spread across both load balancers.`]],slots:[1,3],evidence:[`route53-geo|You can specify geographic locations by continent, by country, or by state in the United States.`,`route53-geo|You can create a default record that handles both queries from unmapped IP addresses and queries from locations where you haven't created geolocation records.`,`route53-geo|You can also use geolocation routing to limit content to only the locations where you have distribution rights.`]}),t({id:`island-charts-004`,building:`island-charts`,bullets:[`2.2-K1`],d:2,stem:`A company hosts a static website in an Amazon S3 bucket behind an Amazon CloudFront distribution. The site must be reachable at the bare domain example.com, which is the zone apex of its Amazon Route 53 hosted zone. The company wants the LEAST operational effort and no manual change if the addresses behind the distribution change. Which record meets these requirements?`,correct:[`An alias A record for example.com that targets the CloudFront distribution`,`An alias record can be created at the zone apex, and Route 53 answers with the current addresses of the distribution automatically.`],wrong:[[`A CNAME record for example.com whose value is the distribution domain name`,`A CNAME record cannot be created at the zone apex, so the record could not be created at all for example.com.`],[`An A record for example.com that lists the addresses returned by a lookup of the distribution`,`The fixed addresses would be wrong as soon as they change, which needs the manual updates the company wants to avoid.`],[`An alias record for example.com that targets a CNAME record named www in the same hosted zone`,`An alias at the zone apex cannot redirect to a record of type CNAME in the same hosted zone, so this is not supported.`]],slot:2,evidence:[`route53-alias|Unlike a CNAME record, you can create an alias record at the top node of a DNS namespace, also known as the zone apex.`,`route53-alias|The one exception is when you want to redirect queries from the zone apex (such as example.com) to a record in the same hosted zone that has a type of CNAME (such as zenith.example.com).`,`route53-alias|If the IP address of the load balancer changes, Route 53 starts responding to DNS queries with the new IP address.`]}),t({id:`island-charts-005`,building:`island-charts`,bullets:[`2.2-K3`],d:1,stem:`A company launches Amazon EC2 instances that have public IPv4 addresses into a new subnet of a custom VPC. An internet gateway is attached to the VPC, and the instances must be reachable from the internet. Which route table entry BEST makes the subnet a public subnet?`,correct:[`A route with destination 0.0.0.0/0 and the internet gateway as its target`,`A subnet whose route table has a route to an internet gateway is a public subnet, and 0.0.0.0/0 covers all internet-bound traffic.`],wrong:[[`A route with destination 0.0.0.0/0 and a NAT gateway as its target`,`A NAT gateway lets private instances start outbound connections only, and the internet cannot initiate connections to them.`],[`A route with destination 0.0.0.0/0 and a VPC peering connection as its target`,`A peering connection routes traffic to another VPC by private address, not to the internet.`],[`A route with destination 10.0.0.0/16 and local as its target`,`The local route covers traffic inside the VPC only, and it is created automatically with the route table.`]],slot:3,evidence:[`vpc-igw|If a subnet is associated with a route table that has a route to an internet gateway, it's known as a public subnet.`,`vpc-igw|In your public subnet's route table, you can specify a route for the internet gateway to all destinations not explicitly known to the route table (0.0.0.0/0 for IPv4 or ::/0 for IPv6).`]}),t({id:`island-charts-006`,building:`island-charts`,bullets:[`2.2-K3`],d:2,stem:`Application servers in a private subnet must download operating system patches from the internet over IPv4. They must not accept connections that are initiated from the internet. The VPC already has an internet gateway and a public subnet. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create a public NAT gateway in the public subnet and route 0.0.0.0/0 from the private subnet to it`,`A NAT gateway lets private instances start outbound connections while external services cannot initiate connections to them, and AWS manages it.`],wrong:[[`Route 0.0.0.0/0 from the private subnet to the internet gateway and give the servers public IPv4 addresses`,`This turns the subnet into a public one, so hosts on the internet could initiate connections to the servers.`],[`Create an egress-only internet gateway and route 0.0.0.0/0 from the private subnet to it`,`An egress-only internet gateway handles IPv6 traffic only, and the servers need IPv4 access.`],[`Create a public NAT gateway in the private subnet and route 0.0.0.0/0 from that subnet to it`,`A public NAT gateway has to be created in a public subnet, so one in the private subnet would have no path to the internet gateway.`]],slot:0,evidence:[`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`,`vpc-nat-gateway|You create a public NAT gateway in a public subnet and must associate an Elastic IP address with the NAT gateway at creation.`,`vpc-egress-only-igw|An egress-only internet gateway is for use with IPv6 traffic only.`]}),t({id:`island-charts-007`,building:`island-charts`,bullets:[`2.2-K3`],d:3,stem:`A subnet route table has these routes: 10.0.0.0/16 to local; 172.31.0.0/16 to a VPC peering connection; 172.31.0.0/24 to a virtual private gateway, propagated from a Site-to-Site VPN connection; and 172.31.0.0/24 to an internet gateway, added as a static route. An instance in the subnet sends a packet to 172.31.0.25. Which target does AWS use for this packet?`,correct:[`The internet gateway, because static routes take priority over propagated ones`,`Both /24 routes are more specific than the /16 route, and between two routes with an identical destination the static route takes priority.`],wrong:[[`The VPC peering connection, because peering routes are preferred for private address ranges`,`The /16 peering route is less specific than the two /24 routes, and the most specific matching route is used.`],[`The virtual private gateway, because propagated VPN routes are preferred over static routes`,`When a propagated route and a static route have the same destination, the static route is the one that takes priority.`],[`No target, because two routes with the same destination make the route table invalid`,`Overlapping routes are allowed, and AWS applies documented priority rules to pick one of them.`]],slot:1,evidence:[`vpc-route-priority|In general, we direct traffic using the most specific route that matches the traffic.`,`vpc-route-priority|If the destination of a propagated route is identical to the destination of a static route, the static route takes priority.`]}),t({id:`island-charts-008`,building:`island-charts`,bullets:[`2.2-K3`],d:3,tags:[`trap:peering-tgw-privatelink`],stem:`VPC A is peered with VPC B, and VPC A is also peered with VPC C. The CIDR blocks of the three VPCs do not overlap. Instances in VPC B must now reach instances in VPC C by private IP address, and the company wants the SIMPLEST change that adds no new type of connection. Which solution meets these requirements?`,correct:[`Create a peering connection between VPC B and VPC C and route each side to the other CIDR block`,`Peering is not transitive, so B and C need their own connection, and each side must add a route that points to the other VPC.`],wrong:[[`Add a route in VPC B for the CIDR block of VPC C with the peering connection to VPC A as the target`,`Traffic cannot be routed from VPC B to VPC C through VPC A, so the packets would not be delivered.`],[`Add routes in the VPC A route tables so that VPC A forwards traffic between VPC B and VPC C`,`VPC A cannot act as a transit point between two peer VPCs, because peering does not forward traffic between peers.`],[`Turn on route propagation in VPC A so that VPC B and VPC C learn each other's routes`,`Route propagation is for routes from a virtual private gateway and does not create a path between two peer VPCs.`]],slot:2,evidence:[`peering-basics|For example, if there are VPC peering connections between VPC A and VPC B, and between VPC A and VPC C, you can't route traffic from VPC B to VPC C through VPC A.`,`peering-basics|To route traffic between VPC B and VPC C, you must create a VPC peering connection between them.`,`peering-basics|the owner of each VPC in the VPC peering connection must manually add a route to one or more of their VPC route tables that points to the IP address range of the other VPC (the peer VPC).`]}),e({id:`island-charts-009`,building:`island-charts`,bullets:[`2.2-K3`,`2.2-S2`],d:2,stem:`A VPC has private subnets in two Availability Zones. Instances in both private subnets reach the internet through one NAT gateway in a public subnet of Availability Zone A. The company wants outbound internet access to continue if Availability Zone A is lost, with the LEAST manual intervention after a failure. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a second NAT gateway in a public subnet of Availability Zone B`,`A NAT gateway lives in one Availability Zone, so a second one in zone B keeps working when zone A is lost.`],[`Route each private subnet to the NAT gateway that is in its own Availability Zone`,`Each zone then depends only on its own NAT gateway, so the loss of zone A does not cut off zone B.`]],wrong:[[`Associate a second Elastic IP address with the existing NAT gateway`,`More addresses do not add a second Availability Zone, so the gateway is still a single point of failure.`],[`Create another NAT gateway in a public subnet of Availability Zone A`,`A second gateway in the same zone is lost together with the first when that zone fails.`],[`Add a 0.0.0.0/0 route to the internet gateway in both private route tables`,`This turns the subnets into public ones and needs public addresses, so the instances stop being private.`]],slots:[2,4],evidence:[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-basics|To improve resiliency, create a NAT gateway in each Availability Zone, and configure your routing to ensure that resources use the NAT gateway in the same Availability Zone.`]}),e({id:`island-charts-010`,building:`island-charts`,bullets:[`2.2-K1`,`2.2-S2`],d:3,stem:`A company runs its web application behind an Application Load Balancer in Region A. An identical stack with its own Application Load Balancer stands by in Region B. The company wants Amazon Route 53 to send all users to Region A while it is healthy and to Region B only when Region A is unavailable, with the LEAST custom code. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create alias records that use the failover routing policy, with Region A as primary and Region B as secondary`,`Failover routing is the active-passive policy: users go to the primary record and move to the secondary only when the primary is unhealthy.`],[`Set Evaluate Target Health to Yes on both alias records`,`For AWS resources that support alias records, this lets Route 53 detect an unhealthy target without a separate health check.`]],wrong:[[`Create weighted alias records that give Region A a weight of 100 and Region B a weight of 1`,`Region B would still receive a small share of users while Region A is healthy, so it is not a standby.`],[`Create latency alias records for both load balancers and let Route 53 choose`,`Users near Region B would be sent there even while Region A is healthy, so it is not a standby.`],[`Run a scheduled AWS Lambda function that rewrites the DNS record when Region A stops answering`,`This is custom code to build, run and monitor, which the company wants to avoid.`]],slots:[0,3],evidence:[`route53-failover-routing|With failover routing, you can route traffic to a resource when it's healthy or to a different resource when the first one is unhealthy.`,`route53-failover-types|you configure active-passive failover using the failover routing policy.`,`route53-failover-types|If you're using AWS resources that you can create alias records for, specify Yes for Evaluate Target Health.`,`route53-failover-types|Use an active-passive failover configuration when you want a primary resource or group of resources to be available the majority of the time and you want a secondary resource or group of resources to be on standby in case all the primary resources become unavailable.`]}),t({id:`island-charts-011`,building:`island-charts`,bullets:[`2.2-S2`],d:2,stem:`A company runs a customer portal on one Amazon EC2 instance in a single Availability Zone. The portal must keep running if an Availability Zone becomes unavailable, and failed instances must be replaced automatically. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use an Auto Scaling group across two Availability Zones behind an Application Load Balancer`,`The group balances instances across zones and replaces impaired ones, while the load balancer sends traffic only to instances that remain.`],wrong:[[`Run a second instance in the same Availability Zone and register both with an Application Load Balancer`,`Both instances would still be lost together if the Availability Zone becomes unavailable.`],[`Create an Amazon Machine Image and relaunch the instance by hand in another zone after a failure`,`The recovery is manual and slow, which fails the requirement that failed instances are replaced automatically.`],[`Assign an Elastic IP address and move it to a standby instance with a script when the primary fails`,`This is custom failover code to maintain, and the script has to detect failures itself.`]],slot:3,evidence:[`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`,`asg-what-is|Amazon EC2 Auto Scaling automatically monitors the health and availability of your instances using EC2 health checks and replaces terminated or impaired instances to maintain your desired capacity.`,`waf-multi-location|To direct traffic to available Availability Zones, place a load balancer in front of your compute, such as an Application Load Balancer or Network Load Balancer.`]}),t({id:`island-charts-012`,building:`island-charts`,bullets:[`2.2-S2`],d:3,stem:`A payment portal runs in one AWS Region behind an Application Load Balancer. Regulators now require it to keep serving customers if the entire Region becomes unavailable. The company needs the same infrastructure in a second Region without configuration drift, and traffic must move to the second Region automatically. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use CloudFormation StackSets for a second Region and Route 53 failover records with health checks`,`StackSets replicate the infrastructure across Regions consistently, and health-checked failover records move users to the second Region automatically.`],wrong:[[`Add more Availability Zones in the first Region and spread the portal across all of the zones`,`All of the zones belong to the same Region, so a Region-wide failure would still take the portal down.`],[`Copy the Amazon Machine Image to a second Region and launch instances by hand during an outage`,`The launch is manual, and nothing keeps the second Region configured the same way as the first.`],[`Build a second stack by hand in another Region and list both load balancers in one simple routing record`,`A simple record does not health check the load balancers, and the hand-built stack can drift from the first.`]],slot:1,evidence:[`waf-multi-location|To ease multi-Regional deployments and maintain consistency, AWS CloudFormation StackSets can replicate your entire AWS infrastructure across multiple Regions.`,`waf-multi-location|Even if you choose not to operate in multiple Regions for high availability, consider multiple Regions as part of your disaster recovery (DR) strategy.`,`route53-simple|With simple routing, although you can specify multiple IP addresses, they are not health checked.`]}),t({id:`island-charts-013`,building:`island-charts`,bullets:[`2.2-S2`],d:2,stem:`A company registered Amazon EC2 instances from three Availability Zones with an internet-facing Application Load Balancer, but the load balancer was created with subnets in only two of the zones. The instances in the third zone receive no traffic even though they pass their health checks. What is the SIMPLEST fix?`,correct:[`Enable the third Availability Zone on the load balancer by adding a subnet from that zone`,`Targets in a zone that is not enabled for the load balancer receive no traffic, so enabling the zone makes them eligible.`],wrong:[[`Turn on cross-zone load balancing for the load balancer`,`Cross-zone load balancing is always on for an Application Load Balancer and does not enable a zone that is missing.`],[`Register the instances in the third zone again by IP address instead of by instance ID`,`The registration type does not matter, because the zone itself is still not enabled for the load balancer.`],[`Increase the health check interval of the target group so the instances stay in service longer`,`The instances already pass their health checks, so the interval is not what keeps traffic away from them.`]],slot:0,evidence:[`elb-how-it-works|If you register targets in an Availability Zone but do not enable the Availability Zone, these registered targets do not receive traffic.`,`elb-how-it-works|With Application Load Balancers, cross-zone load balancing is always enabled at the load balancer level.`]}),t({id:`island-charts-014`,building:`island-charts`,bullets:[`2.2-K1`],d:1,stem:`A company wants one managed service that can register its domain name, answer DNS queries by routing users to its endpoints, and check whether those endpoints are healthy. Which AWS service BEST meets these requirements?`,correct:[`Amazon Route 53`,`Route 53 is a highly available DNS web service that performs domain registration, DNS routing and health checking in any combination.`],wrong:[[`Amazon CloudFront`,`CloudFront is a content delivery network that caches content at edge locations and is not a domain registration service.`],[`Elastic Load Balancing`,`A load balancer distributes traffic to targets and does not register domains or answer DNS queries for them.`],[`AWS Direct Connect`,`Direct Connect is a dedicated network connection to AWS and does not provide DNS or domain registration.`]],slot:2,evidence:[`route53-what-is|You can use Route 53 to perform three main functions in any combination: domain registration, DNS routing, and health checking.`]}),t({id:`island-charts-015`,building:`island-charts`,bullets:[`2.2-K1`],d:1,stem:`A company releases a new version of its application behind a separate Application Load Balancer. It wants Amazon Route 53 to send about 5 percent of the queries for www.example.com to the new version and the rest to the current version, and to raise the share gradually. Which routing policy BEST meets these requirements?`,correct:[`Weighted routing, with a small weight on the new version`,`Weighted routing sends traffic in the proportions you set, and changing the weights slowly shifts the balance.`],wrong:[[`Failover routing, with the new version set as the primary record`,`Failover sends all traffic to the primary until it is unhealthy, so it cannot split queries in a set proportion.`],[`Geolocation routing, with one record for each continent`,`Geolocation chooses by where the user is, not by a percentage of queries.`],[`Latency routing, with a record for each version`,`Latency routing picks the Region with the best latency for the user and does not split queries by a share.`]],slot:3,evidence:[`route53-weighted|You can slowly change the balance by changing the weights.`,`route53-routing|Weighted routing policy – Use to route traffic to multiple resources in proportions that you specify.`]}),t({id:`island-charts-016`,building:`island-charts`,bullets:[`2.2-K3`],d:2,tags:[`mock-reserve`],stem:`A VPC has two private subnets. A gateway VPC endpoint for Amazon S3 serves instances in subnet A, but instances in subnet B still reach Amazon S3 through the NAT gateway. The company wants subnet B to use the endpoint with the LEAST change. Which action meets this requirement?`,correct:[`Associate the route table of subnet B with the gateway endpoint`,`A gateway endpoint works through route table entries for the service prefix list, and it is added to the route tables you select.`],wrong:[[`Add an outbound rule for Amazon S3 to the security group of the instances in subnet B`,`Security groups filter traffic and do not choose the path, so the traffic would still follow the NAT gateway route.`],[`Create a CNAME record in Route 53 that maps the S3 bucket name to the endpoint ID`,`The endpoint is reached through a route and not through a DNS name that a CNAME could point to.`],[`Attach an internet gateway to the VPC and add a 0.0.0.0/0 route to it in subnet B`,`This sends S3 traffic over the internet instead of the endpoint and gives subnet B a public route it should not have.`]],slot:0,evidence:[`vpc-route-options|When you create a gateway endpoint, you specify the subnet route tables in your VPC that are used by the gateway endpoint.`,`vpc-route-options|A route is automatically added to each of the route tables with a destination that specifies the prefix list ID of the service (pl-xxxxxxxx), and a target with the endpoint ID (vpce-xxxxxxxxxxxxxxxxx).`,`vpce-gateway-s3|After you create the gateway endpoint, you can add it as a target in your route table for traffic destined from your VPC to Amazon S3.`]}),e({id:`island-charts-017`,building:`island-charts`,bullets:[`2.2-K1`],d:2,tags:[`mock-reserve`],stem:`A company runs three web servers on Amazon EC2 instances with Elastic IP addresses and no load balancer. The company wants Amazon Route 53 to return the addresses of healthy servers only and to spread clients roughly at random across them, with the LEAST additional infrastructure. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a multivalue answer record for each of the three servers`,`Multivalue answer routing returns several values for a name and spreads clients across them roughly at random.`],[`Associate a Route 53 health check with each of those records`,`Route 53 then returns a server address only when its health check is healthy.`]],wrong:[[`Create one simple routing record that lists all three IP addresses`,`Addresses in a simple record are not health checked, so an unhealthy server would still be returned.`],[`Place an Application Load Balancer in front of the servers and create an alias record for it`,`The load balancer is extra infrastructure that the company wants to avoid, and DNS can do the job.`],[`Create geolocation records that map each continent to one of the servers`,`Geolocation routes by where the user is and does not spread clients at random or check health.`]],slots:[1,4],evidence:[`route53-multivalue|With multivalue answer routing, you can set up Amazon Route 53 to return multiple values, such as IP addresses for your web servers, in response to DNS queries.`,`route53-multivalue|Route 53 then returns only values for healthy resources.`,`route53-hc-types|You can configure a health check that monitors an endpoint that you specify either by IP address or by domain name.`,`route53-simple|With simple routing, although you can specify multiple IP addresses, they are not health checked.`]}),t({id:`island-charts-018`,building:`island-charts`,bullets:[`2.2-K1`],d:3,tags:[`mock-reserve`],stem:`A company runs identical stacks in US East (N. Virginia) and Europe (Frankfurt). Route 53 should send each user to the closest stack, but the Frankfurt stack has spare capacity, so the company wants to widen the area of users it serves and to change that area later by editing a value, not the records. Which routing policy BEST meets these requirements?`,correct:[`Geoproximity routing, with a positive bias on Frankfurt`,`Geoproximity sends traffic to the closest available resource, and a positive bias expands the region that sends traffic to that resource.`],wrong:[[`Geolocation routing, with records for each country in Europe`,`Geolocation maps fixed locations to resources and does not route to the closest resource or shift a boundary with a value.`],[`Latency routing, with one record for each Region`,`Latency routing picks the best-latency Region and has no value that widens the area served by one Region.`],[`Weighted routing, with a higher weight on the Frankfurt record`,`Weighted routing ignores where the user is, so users near Virginia would also be sent to Frankfurt.`]],slot:2,evidence:[`route53-geoproximity|It sends traffic to the closest available resource.`,`route53-geoproximity|To expand the size of the geographic region from which Route 53 routes traffic to a resource, specify a positive integer from 1 to 99 for the bias.`]})],l=[t({id:`legacy-wharf-001`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:1,stem:`A retailer collects thousands of free-text product reviews every day and wants to find the sentiment and the key phrases in each review. The company has no machine learning engineers and wants the LEAST development effort. Which service should the company use?`,correct:[`Amazon Comprehend, called through its API with the pre-trained models`,`Comprehend uses natural language processing to recognize sentiments and key phrases in documents, and its pre-trained models need no training.`],wrong:[[`Amazon Rekognition, called through its API once for each review`,`Rekognition analyses images and video, so it does not extract sentiment or key phrases from review text.`],[`Amazon Polly, called through its API once for each review`,`Polly converts text into speech and does not analyse the meaning of the text.`],[`Amazon SageMaker AI, with a model that the team builds and trains`,`SageMaker AI is for building, training and deploying your own models, which is far more effort than calling a pre-trained service.`]],slot:0,evidence:[`comprehend-what-is|It develops insights by recognizing the entities, key phrases, language, sentiments, and other common elements in a document.`,`comprehend-what-is|You can use the pre-trained models that Amazon Comprehend provides, or you can train your own custom models for classification and entity recognition.`,`sagemaker-what-is|With SageMaker AI, data scientists and developers can quickly and confidently build, train, and deploy ML models into a production-ready hosted environment.`]}),t({id:`legacy-wharf-002`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:1,stem:`A news site wants every article to be available as spoken audio for visually impaired readers. The audio must use natural-sounding voices, and the company wants the LEAST development effort. Which service should the company use?`,correct:[`Amazon Polly, which converts the article text into lifelike speech`,`Polly is a managed service that turns text into lifelike speech with a variety of voices, so the site only has to call it.`],wrong:[[`Amazon Transcribe, which turns the article text into audio files`,`Transcribe works in the opposite direction: it converts audio to text, so it cannot produce spoken audio.`],[`Amazon Translate, which turns the article text into spoken language`,`Translate converts text from one language to another and returns text, not audio.`],[`Amazon Lex, which turns the article text into a voice conversation`,`Lex builds conversational interfaces that take requests, which is more than reading fixed articles aloud.`]],slot:1,evidence:[`polly-what-is|Amazon Polly is a cloud service that converts text into lifelike speech.`,`polly-what-is|Amazon Polly supports multiple languages and includes a variety of lifelike voices.`,`transcribe-what-is|Amazon Transcribe is an automatic speech recognition service that uses machine learning models to convert audio to text.`]}),t({id:`legacy-wharf-003`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:2,stem:`A legacy web application keeps each user's login session in the memory of the server that handled the login. The application cannot be changed. When the company puts four servers behind a load balancer, users are logged out as their requests reach different servers. Which solution BEST fixes this with the LEAST effort?`,correct:[`Use an Application Load Balancer and enable sticky sessions on its target group`,`Sticky sessions send all requests in a user's session to the same target, which suits servers that keep state, and need no code change.`],wrong:[[`Move the session data into Amazon ElastiCache and read it from every server`,`The application would have to be changed to read and write sessions in the cache, and it cannot be changed.`],[`Use Amazon Route 53 weighted records that point to the address of each server`,`Weighted records spread DNS answers by weight and do not bind a user's session to one server.`],[`Place Amazon CloudFront in front of the servers and cache the login pages`,`Caching pages at edge locations does not bind a user's requests to the server that holds the session.`]],slot:2,evidence:[`alb-target-attrs|you can use the sticky session feature (also known as session affinity) to enable the load balancer to bind a user's session to a specific target.`,`alb-target-attrs|This feature is useful for servers that maintain state information in order to provide a continuous experience to clients.`,`alb-target-attrs|Sticky sessions are enabled at the target group level.`]}),t({id:`legacy-wharf-004`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A legacy order application uses a single-AZ Amazon RDS for MySQL DB instance, and its code cannot be modified. The company wants the database to fail over automatically to another Availability Zone if the instance or its zone fails, with the LEAST operational effort. Which solution meets these requirements?`,correct:[`Modify the DB instance to use a Multi-AZ DB instance deployment`,`RDS keeps a synchronous standby in another Availability Zone and switches to it automatically, so the application needs no change.`],wrong:[[`Create a read replica in another zone and promote it by hand during an outage`,`Promotion is a manual step and the replica is updated asynchronously, so failover is neither automatic nor free of data loss.`],[`Take automated snapshots and restore the latest one to a new DB instance after a failure`,`Restoring from a snapshot is a manual recovery that takes time and loses recent changes, not an automatic failover.`],[`Scale the DB instance up to a larger instance class in the same Availability Zone`,`A larger instance in the same zone adds capacity but no standby, so a zone failure still stops the database.`]],slot:3,evidence:[`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`rds-failover|Amazon RDS handles failovers automatically so you can resume database operations as quickly as possible without administrative intervention.`,`rds-promote|When you promote a read replica, RDS reboots the DB instance before making it available.`]}),t({id:`legacy-wharf-005`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:2,stem:`A licensed legacy application runs on one Amazon EC2 instance and is tied to the instance's ID and Elastic IP address. If the underlying hardware fails a system status check, the instance must return on a new host with the same instance ID, IP addresses and Availability Zone, with the LEAST operational effort. Which solution meets these requirements?`,correct:[`Use EC2 automatic instance recovery, which moves the instance to a different host`,`Recovery restores availability after a failed system status check and preserves the instance ID, IP addresses and Availability Zone.`],wrong:[[`Run the instance in an Auto Scaling group with a minimum and maximum size of one`,`The group replaces an impaired instance with a new one, so the replacement does not keep the original instance ID.`],[`Add a Route 53 failover record that points to a second instance running the application`,`The second instance has its own instance ID and address, so the licence tied to the original instance is not satisfied.`],[`Stop and start the instance by hand each time a status check alert arrives`,`This is a manual step for each failure, and a restarted instance gets a new public IPv4 address unless it uses an Elastic IP address.`]],slot:0,evidence:[`ec2-recover|These recovery mechanisms are designed to restore instance availability when AWS detects an underlying hardware or software issue that causes a system status check to fail.`,`ec2-recover|Preserved elements: Instance ID Public, private, and Elastic IP addresses Instance metadata Placement group Attached EBS volumes Availability Zone`,`asg-what-is|Amazon EC2 Auto Scaling automatically monitors the health and availability of your instances using EC2 health checks and replaces terminated or impaired instances to maintain your desired capacity.`]}),t({id:`legacy-wharf-006`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:2,stem:`A bank receives scanned loan applications as PDF and image files. It must extract the text, the form fields and the tables from each document as structured data, and its team has little machine learning expertise. Which service meets these requirements with the LEAST development effort?`,correct:[`Amazon Textract, using its document analysis API on each scanned file`,`Textract extracts text, forms and tables from documents as structured data through a simple API that needs no machine learning expertise.`],wrong:[[`Amazon Comprehend, using its pre-trained models on each scanned file`,`Comprehend finds entities, key phrases and sentiment in text content and does not extract form fields and tables from scans.`],[`Amazon Rekognition, using its image analysis API on each scanned file`,`Rekognition detects objects, scenes, faces and text in images and video, and does not return forms and tables as structured data.`],[`Amazon SageMaker AI, using a custom model that the team builds and hosts`,`The team would have to build, train and host a model, which needs the expertise and effort the company wants to avoid.`]],slot:1,evidence:[`textract-what-is|Extract text, forms, and tables from documents with structured data, using the Amazon Textract Document Analysis API.`,`textract-what-is|You don't need any machine learning expertise to use it, as Amazon Textract includes simple, easy-to-use API operations that can analyze image files and PDF files.`,`comprehend-what-is|It develops insights by recognizing the entities, key phrases, language, sentiments, and other common elements in a document.`]}),t({id:`legacy-wharf-007`,building:`legacy-wharf`,bullets:[`2.2-K2`,`2.2-S8`],d:1,stem:`A photo-sharing application must detect unsafe content and identify objects in the images that users upload to Amazon S3. The company has no machine learning team and wants the LEAST effort to build and run the feature. Which service should the company use?`,correct:[`Amazon Rekognition, which analyses the uploaded images through an API`,`Rekognition is a managed image and video analysis service that detects objects and unsafe content, so no model has to be built.`],wrong:[[`Amazon Textract, which analyses the uploaded images through an API`,`Textract extracts text, forms and tables from documents and does not detect objects or unsafe content in photos.`],[`Amazon Comprehend, which analyses the uploaded images through an API`,`Comprehend extracts insights from the content of text documents, not from objects within photos.`],[`Amazon SageMaker AI, with an image model that the team trains and hosts`,`SageMaker AI is for building, training and deploying your own models, which costs more effort than calling a purpose-built service.`]],slot:2,evidence:[`rekognition-what-is|You can add features that detect objects, text, unsafe content, analyze images/videos, and compare faces to your application using Rekognition's APIs.`,`rekognition-what-is|Amazon Rekognition is a cloud-based image and video analysis service that makes it easy to add advanced computer vision capabilities to your applications.`,`sagemaker-what-is|With SageMaker AI, data scientists and developers can quickly and confidently build, train, and deploy ML models into a production-ready hosted environment.`]}),t({id:`legacy-wharf-008`,building:`legacy-wharf`,bullets:[`2.2-S8`],d:2,stem:`A company wants a chatbot on its website and mobile app that understands typed or spoken customer requests and holds a conversation. The developers have no deep learning expertise, and the company wants the LEAST effort to build the bot. Which service should the company use?`,correct:[`Amazon Lex, with the conversation flow defined in its console`,`Lex builds text and voice chatbots from a conversation flow that is defined in the console, and no deep learning expertise is necessary.`],wrong:[[`Amazon Polly, with the conversation flow defined in its console`,`Polly only converts text into speech and has no conversation flow or understanding of customer requests.`],[`Amazon Transcribe, with the conversation flow defined in its console`,`Transcribe converts audio to text but does not hold a conversation or decide how to respond.`],[`Amazon Comprehend, with the conversation flow defined in its console`,`Comprehend extracts insights from documents and has no conversational interface for customers.`]],slot:3,evidence:[`lex-what-is|With Amazon Lex V2, no deep learning expertise is necessary—to create a chatbot, you specify the basic conversation flow in the Amazon Lex V2 console.`,`lex-what-is|Using the console, you can build, test, and publish your text or voice chatbot.`,`polly-what-is|Amazon Polly is a cloud service that converts text into lifelike speech.`]}),t({id:`legacy-wharf-009`,building:`legacy-wharf`,bullets:[`2.2-S8`],d:2,stem:`Analysts run ad-hoc SQL queries a few times a week on terabytes of CSV log files that are stored in Amazon S3. The company does not want to provision or manage any infrastructure and wants to pay only when queries run. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Query the files in place with Amazon Athena using standard SQL`,`Athena analyses data directly in S3 with standard SQL and is serverless, so there is nothing to set up and charges apply only per query.`],wrong:[[`Load the files into an Amazon RDS for PostgreSQL instance and query them there`,`An RDS instance has to be provisioned, sized and loaded, and it incurs charges whether or not queries run.`],[`Run a long-lived Amazon EMR cluster and query the files from it with Apache Spark`,`A cluster has to be provisioned and managed, and it costs money while it sits idle between the weekly queries.`],[`Copy the files into an Amazon Redshift provisioned cluster and query them there`,`A provisioned cluster has to be sized and managed and keeps running between queries, which the company wants to avoid.`]],slot:0,evidence:[`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`athena-what-is|Athena SQL and Apache Spark on Amazon Athena are serverless, so there is no infrastructure to set up or manage, and you pay only for the queries you run.`]}),t({id:`legacy-wharf-010`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:3,stem:`A legacy web application runs on Amazon EC2 instances behind an Application Load Balancer. Occasionally the application process on an instance stops responding while the instance still passes its EC2 status checks. The application cannot be changed, and the company wants unresponsive instances replaced automatically with the LEAST operational effort. Which solution meets these requirements?`,correct:[`Run the instances in an Auto Scaling group that uses the load balancer health checks`,`The group replaces any instance that the load balancer reports as unhealthy, so a hung application process is caught and replaced.`],wrong:[[`Rely on EC2 simplified automatic recovery, which is enabled by default on supported instances`,`Recovery acts on a failed system status check from an underlying issue, so a hung application on healthy hardware goes unnoticed.`],[`Lengthen the deregistration delay on the target group of the load balancer for each instance`,`The delay only lets in-flight requests finish when a target is deregistered, and it never replaces an unresponsive instance.`],[`Create a Route 53 failover record with a health check that points at the load balancer`,`Failover shifts DNS answers to a standby when the primary is unhealthy, but it does not replace the unresponsive instances.`]],slot:1,evidence:[`asg-health-checks|When Amazon EC2 Auto Scaling determines that an InService instance is unhealthy, it replaces it with a new instance to maintain the desired capacity of the group.`,`elb-how-it-works|When the load balancer detects an unhealthy target, it stops routing traffic to that target.`,`ec2-recover|These recovery mechanisms are designed to restore instance availability when AWS detects an underlying hardware or software issue that causes a system status check to fail.`,`alb-target-attrs|By default, Elastic Load Balancing waits 300 seconds before completing the deregistration process, which can help in-flight requests to the target to complete.`]}),t({id:`legacy-wharf-011`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:3,stem:`A support team receives thousands of emails each month and must route each one to one of twelve company-specific categories. The categories are not part of any pre-trained model, but the team has many labeled example emails. The company has no data scientists and wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Train an Amazon Comprehend custom classification model on the labeled emails`,`Comprehend lets you train your own custom classification models without building or hosting a model, which fits labeled data and no data scientists.`],wrong:[[`Call the Amazon Comprehend pre-trained models for entities and sentiment on every email`,`Pre-trained models find entities and sentiment, and they know nothing about the twelve company-specific categories.`],[`Build, train and host a classifier of the team's own design in Amazon SageMaker AI`,`This is a full machine learning project to build, train and operate, which needs the data science skills the company lacks.`],[`Create an Amazon Lex bot with one intent for each of the twelve categories`,`Lex builds conversational interfaces and is not a service for classifying stored email documents.`]],slot:2,evidence:[`comprehend-what-is|You can use the pre-trained models that Amazon Comprehend provides, or you can train your own custom models for classification and entity recognition.`,`sagemaker-what-is|With SageMaker AI, data scientists and developers can quickly and confidently build, train, and deploy ML models into a production-ready hosted environment.`,`lex-what-is|Amazon Lex V2 enables any developer to build conversational chatbots quickly.`]}),e({id:`legacy-wharf-012`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:2,stem:`A call center stores recorded customer calls as audio files in Amazon S3. The company wants a written transcript of every call and wants to know whether each customer sounded positive or negative. The company wants managed AI services and the LEAST development effort. Which TWO services should the company use? (Choose two.)`,correct:[[`Amazon Transcribe, to convert the call audio into text`,`Transcribe is an automatic speech recognition service that converts audio to text.`],[`Amazon Comprehend, to detect the sentiment in each transcript`,`Comprehend recognizes sentiments in documents, and the transcripts supply the text it needs.`]],wrong:[[`Amazon Polly, to convert the call audio into text`,`Polly converts text into speech, the opposite of the transcription that is needed.`],[`Amazon Rekognition, to detect the sentiment in each recording`,`Rekognition analyses images and video, not the sentiment of spoken customer calls.`],[`Amazon Translate, to detect the sentiment in each transcript`,`Translate converts text from one language to another and does not detect sentiment.`]],slots:[0,3],evidence:[`transcribe-what-is|Amazon Transcribe is an automatic speech recognition service that uses machine learning models to convert audio to text.`,`comprehend-what-is|It develops insights by recognizing the entities, key phrases, language, sentiments, and other common elements in a document.`,`translate-what-is|Amazon Translate is a text translation service that uses advanced machine learning technologies to provide high-quality translation on demand.`]}),e({id:`legacy-wharf-013`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`A legacy three-tier application keeps user sessions in the memory of its web servers and uses a single-AZ Amazon RDS database. All the servers are in one Availability Zone. The application cannot be changed, and the company wants it to survive the loss of one Availability Zone with the LEAST operational effort. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Run the web servers in an Auto Scaling group across two zones behind an Application Load Balancer with sticky sessions enabled`,`Servers in two zones survive a zone loss, and sticky sessions keep each user on the server that holds the session without code changes.`],[`Convert the database to a Multi-AZ DB instance deployment`,`RDS keeps a standby in another Availability Zone and fails over automatically, and the application is not changed.`]],wrong:[[`Rewrite the application to keep sessions in Amazon DynamoDB instead of server memory`,`This is a code change, and the application cannot be changed.`],[`Add an RDS read replica in a second zone and point the application at it`,`The connection settings and replica promotion are manual changes, and a replica is not an automatic failover target.`],[`Add an Amazon ElastiCache cluster to hold the user sessions for all of the servers`,`The application would need code changes to use the cache, which are not possible.`]],slots:[1,2],evidence:[`alb-target-attrs|This feature is useful for servers that maintain state information in order to provide a continuous experience to clients.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`]}),e({id:`legacy-wharf-014`,building:`legacy-wharf`,bullets:[`2.2-K2`,`2.2-S8`],d:3,stem:`A company is building a multilingual support portal. Customers upload scanned forms and write tickets in their own languages. The portal must extract the fields from each scanned form, translate each ticket into English, and read answers aloud to customers. The company wants managed AI services and the LEAST machine learning work. Which THREE services should the company use? (Choose three.)`,correct:[[`Amazon Textract, to extract the fields from the scanned forms`,`Textract extracts text, forms and tables from documents with a simple API.`],[`Amazon Translate, to translate the ticket text into English`,`Translate is a text translation service that provides translation on demand.`],[`Amazon Polly, to read the answers aloud to customers`,`Polly converts text into lifelike speech.`]],wrong:[[`Amazon Lex, to extract the fields from the scanned forms`,`Lex is a service for building conversational interfaces for applications using voice and text, so it does not extract fields from scanned documents.`],[`Amazon Rekognition, to translate the ticket text into English`,`Rekognition analyzes image and video files, so it does not translate ticket text.`],[`Amazon Transcribe, to read the answers aloud to customers`,`Transcribe is an automatic speech recognition service that converts audio to text, so it does not read answers aloud.`]],slots:[0,2,4],evidence:[`textract-what-is|Extract text, forms, and tables from documents with structured data, using the Amazon Textract Document Analysis API.`,`translate-what-is|Amazon Translate is a text translation service that uses advanced machine learning technologies to provide high-quality translation on demand.`,`polly-what-is|Amazon Polly is a cloud service that converts text into lifelike speech.`,`lex-what-is|Amazon Lex V2 is an AWS service for building conversational interfaces for applications using voice and text.`,`rekognition-what-is|Amazon Rekognition includes a simple, easy-to-use API that can quickly analyze any image or video file that’s stored in Amazon S3.`,`transcribe-what-is|Amazon Transcribe is an automatic speech recognition service that uses machine learning models to convert audio to text.`]}),t({id:`legacy-wharf-015`,building:`legacy-wharf`,bullets:[`2.2-S8`],d:2,stem:`Business analysts want to build interactive dashboards from several data sources and embed them in an internal web application. The company wants a managed service and the LEAST infrastructure to run itself. Which service should the company use?`,correct:[`Amazon Quick, to connect the data sources and build the dashboards`,`Quick provides interactive visualization and business intelligence with dashboards that can be embedded in applications.`],wrong:[[`Amazon Athena, to connect the data sources and build the dashboards`,`Athena runs SQL queries on data in S3 and has no dashboard authoring or embedding.`],[`Amazon CloudWatch, to connect the data sources and build the dashboards`,`CloudWatch dashboards show operational metrics and logs rather than business data from several sources.`],[`Amazon EMR, to connect the data sources and build the dashboards`,`EMR runs big data processing frameworks and gives analysts no dashboard tool.`]],slot:3,evidence:[`quick-what-is|Amazon Quick Sight – Interactive data visualization and business intelligence.`,`quick-what-is|Connect to data sources, build dashboards, and embed analytics in applications.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`]}),t({id:`legacy-wharf-016`,building:`legacy-wharf`,bullets:[`2.2-S7`],d:2,tags:[`mock-reserve`],stem:`A legacy application runs on Amazon EC2 instances in two Availability Zones. It reads and writes shared files through a mounted NFS directory that is hosted on a single server, which is a single point of failure. The application cannot be changed. The company wants the shared files to stay available if one Availability Zone fails, with the LEAST effort. Which solution meets these requirements?`,correct:[`Move the files to an Amazon EFS file system and mount it on the instances in both Availability Zones`,`EFS supports the NFS protocol, so the application works unchanged, and storing data across multiple Availability Zones keeps it available if one zone fails.`],wrong:[[`Move the files to an Amazon S3 bucket and have the application call the S3 API to read and write them`,`S3 stores objects and is not mounted as an NFS directory, so the application would have to be changed.`],[`Move the files to an Amazon EBS io2 volume with Multi-Attach and attach it to the instances in both zones`,`Multi-Attach works only for instances in the same Availability Zone, so the second zone cannot use the volume.`],[`Keep the NFS server and run a second NFS server in the other Availability Zone to be set up by hand`,`Two servers that are managed by hand add operational work and replication to build, where EFS is a managed NFS file system.`]],slot:0,evidence:[`efs-what-is|Amazon EFS supports the Network File System version 4 (NFSv4.1 and NFSv4.0) protocol, so the applications and tools that you use today work seamlessly with Amazon EFS.`,`efs-what-is|Storing data across multiple Availability Zones provides continuous availability to the data, even when one or more Availability Zones in an AWS Region are unavailable.`,`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`,`s3-what-is|How Amazon S3 works Amazon S3 is an object storage service that stores data as objects, hierarchical data, or tabular data within buckets.`]}),t({id:`legacy-wharf-017`,building:`legacy-wharf`,bullets:[`2.2-K2`],d:2,tags:[`mock-reserve`],stem:`Customer service agents and customers use a chat feature in their own languages. Each message must reach the other side in the reader's language, and the company does not want to build or train translation models. Which service meets this requirement with the LEAST development effort?`,correct:[`Amazon Translate, called for each chat message that is sent`,`Translate is a text translation service that can translate customer service chat so people can connect in their preferred language.`],wrong:[[`Amazon Comprehend, called for each chat message that is sent`,`Comprehend analyses a message for entities, key phrases and sentiment, and it does not translate it.`],[`Amazon Polly, called for each chat message that is sent`,`Polly turns text into speech and returns audio, not the message in another language.`],[`Amazon Transcribe, called for each chat message that is sent`,`Transcribe converts audio to text and does not translate chat text between languages.`]],slot:1,evidence:[`translate-what-is|Translate interpersonal communications, such as email, in-game chat, customer service chat, so that customers and employees can connect in their preferred language.`,`translate-what-is|Amazon Translate is a text translation service that uses advanced machine learning technologies to provide high-quality translation on demand.`]})],u=[t({id:`message-quay-001`,building:`message-quay`,bullets:[`2.1-K5`],d:1,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A company wants its applications to react to events from AWS services and SaaS applications. Rules must select events and send them to targets, and the company wants a serverless service with the LEAST operational overhead. Which service BEST meets these requirements?`,correct:[`Amazon EventBridge, with rules that send matching events to targets`,`EventBridge is a serverless service that connects application components with events, and a rule specifies which events go to which targets.`],wrong:[[`Amazon SQS, with a queue that each application polls for events`,`A queue buffers messages for consumers and does not select events by rules and route them to targets.`],[`Amazon Kinesis Data Streams, with a stream that each application reads`,`A stream collects and processes large streams of data records, and the applications would have to implement their own routing.`],[`AWS Step Functions, with a workflow that waits for each event to arrive`,`Step Functions coordinates the steps of a workflow and is not a service for routing events from sources to targets.`]],slot:0,evidence:[`eda-overview|Amazon EventBridge is recommended when you want to build an application that reacts to events from SaaS applications, AWS services, or custom applications.`,`eventbridge-what-is|EventBridge is a serverless service that uses events to connect application components together, making it easier for you to build scalable event-driven applications.`,`eventbridge-rules|A rule specifies which events to send to which targets for processing.`]}),t({id:`message-quay-002`,building:`message-quay`,bullets:[`2.1-K5`],d:2,stem:`A company wants an AWS Lambda function to run whenever any Amazon EC2 instance in the account is terminated. The company wants the LEAST custom code and no polling of the EC2 API. Which solution meets these requirements?`,correct:[`Create an Amazon EventBridge rule with an event pattern that matches the terminated state and set the function as its target`,`The rule matches EC2 instance state-change events pushed by EventBridge, so no code polls for the change.`],wrong:[[`Invoke a function every minute that calls the EC2 describe API and compares the instance list with the last result`,`This polls the API and needs custom comparison code, which the company wants to avoid.`],[`Install a script on every instance that writes a record to an Amazon Kinesis data stream during shutdown`,`This needs custom code on each instance and misses instances that fail without running a shutdown script.`],[`Install an agent on every instance that publishes to an Amazon SNS topic when the operating system shuts down`,`This needs custom code on each instance, and an instance that fails abruptly never publishes anything.`]],slot:1,evidence:[`eventbridge-patterns|The following event pattern selects all Amazon EC2 instance-termination events.`,`eda-overview|You no longer need to write custom code to poll, filter, and route events; the event router will automatically filter and push events to consumers.`]}),e({id:`message-quay-003`,building:`message-quay`,bullets:[`2.1-K5`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A company receives events from AWS services. Events with certain values in the event body must start two AWS Lambda functions at the same time, and the company does not want to pay for continuous polling. The company wants the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an Amazon EventBridge rule with an event pattern that matches the required fields of the events`,`Rules filter on event data before pushing events to consumers, so only the events with the required values are delivered.`],[`Add both Lambda functions as targets of the same rule so that they run in parallel`,`A single rule can send an event to multiple targets, which then run in parallel.`]],wrong:[[`Run an Amazon EC2 instance that polls for the events and forwards each one to the functions`,`Polling and forwarding code on an instance adds operational overhead and continuous polling.`],[`Create a scheduled rule that invokes a function every minute to check for new events`,`A schedule polls on a timer instead of reacting to events as they happen.`],[`Create an Amazon Kinesis data stream and write one application to read it for each function`,`This adds stream capacity and consumer applications to manage, where a rule can route events directly.`]],slots:[0,2],evidence:[`eda-overview|EventBridge uses a predefined schema for events and allows you to create rules that are applied across the entire event body to filter before pushing to consumers.`,`eventbridge-rules|A single rule can send an event to multiple targets, which then run in parallel.`,`eda-overview|This way, you’re not paying for continuous polling to check for an event.`]}),t({id:`message-quay-004`,postGuide:[`eventbridge-pipes`],postGuideKey:[`eventbridge-pipes`],building:`message-quay`,bullets:[`2.1-K5`],d:3,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A company wants to take change records from an Amazon DynamoDB stream, enrich them with extra data, and deliver the resulting events to five consumer applications, each of which is selected by rules on the event contents. The company wants the LEAST custom code. Which solution BEST meets these requirements?`,correct:[`Create an Amazon EventBridge pipe that reads the stream and sends events to an event bus whose rules select the consumers`,`A pipe handles the single source with enrichment, and an event bus then routes events to multiple targets according to its rules.`],wrong:[[`Create one Amazon EventBridge pipe that reads the stream and has all five consumers as its targets`,`Each pipe delivers events from a single source to a single target, so one pipe cannot feed five consumers.`],[`Send the records to one Amazon SQS queue that all five consumer applications poll`,`A queue typically processes each message through a single subscriber, so the five consumers would not all receive each event.`],[`Write an AWS Lambda function that reads the stream, enriches the records and calls the five consumers`,`This is custom code that couples the function to every consumer, which the company wants to avoid.`]],slot:2,evidence:[`eventbridge-what-is|EventBridge Pipes is intended for point-to-point integrations; each pipe receives events from a single source for processing and delivery to a single target.`,`eventbridge-what-is|Pipes also include support for advanced transformations and enrichment of events prior to delivery to a target.`,`eventbridge-what-is|A common use case is to create a pipe with an event bus as its target; the pipe sends events to the event bus, which then sends those events on to multiple targets.`,`sqs-what-is|It processes messages through a single subscriber typically, ideal for workflows where order and loss prevention are critical.`]}),t({id:`message-quay-005`,building:`message-quay`,bullets:[`2.1-K11`],d:1,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A web tier accepts image uploads, and a separate fleet of workers resizes the images. During sales, uploads arrive faster than the workers can resize them, and requests must not be lost if the workers are briefly unavailable. Which solution BEST decouples the two tiers?`,correct:[`Send a message for each upload to an Amazon SQS queue that the workers poll when they are ready`,`A queue buffers requests so each worker can take messages when ready, and the queue absorbs spikes without losing messages.`],wrong:[[`Publish a message for each upload to an Amazon SNS topic that the workers subscribe to over HTTPS`,`A topic pushes messages to subscribers, so messages can be lost when subscribers are offline unless a queue holds them.`],[`Have the web tier send every upload to the workers through an Application Load Balancer`,`The tiers stay directly coupled, so a slow or unavailable worker fails the upload request.`],[`Add more web servers so that each upload is resized inline before the response returns`,`Resizing stays tied to the request, and spikes still overload the servers with no buffer between the tiers.`]],slot:3,evidence:[`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`,`sqs-what-is|To prevent message loss when subscribers are offline, integrating Amazon SNS with Amazon SQS queue messages ensures consistent delivery.`]}),t({id:`message-quay-006`,building:`message-quay`,bullets:[`2.1-K11`,`2.1-S3`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`When an order is placed, the same message must reach a fulfillment service, an analytics service and a test environment. Each consumer must work at its own pace and must not lose messages while it is offline. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Publish the message to an Amazon SNS topic and subscribe a separate Amazon SQS queue for each consumer`,`The topic replicates the message to every queue, and each queue holds messages for its consumer until it is ready.`],wrong:[[`Send the message to one Amazon SQS queue that all three consumers poll`,`A queue typically processes each message through a single subscriber, so the consumers would not each receive the message.`],[`Publish the message to an Amazon SNS topic and subscribe each consumer directly by its own HTTPS endpoint`,`Subscribers that are offline can miss messages, because no queue holds them for later processing.`],[`Have the order service call the endpoint of each consumer in turn and retry on failure`,`The order service stays coupled to every consumer, and the retry logic is custom code that it must maintain.`]],slot:0,evidence:[`sns-what-is|The Fanout scenario is when a message published to an SNS topic is replicated and pushed to multiple endpoints, such as Firehose delivery streams, Amazon SQS queues, HTTP(S) endpoints, and Lambda functions.`,`sqs-what-is|It processes messages through a single subscriber typically, ideal for workflows where order and loss prevention are critical.`,`sns-sqs-fanout|The messages also persist in an Amazon SQS queue for other applications to process later.`]}),e({id:`message-quay-007`,building:`message-quay`,bullets:[`2.1-K11`],d:2,stem:`An application processes messages from an Amazon SQS standard queue. Some messages fail repeatedly because of unexpected content. The company wants to set the failed messages aside so that engineers can examine them, while the main queue keeps flowing. Which TWO actions BEST meet these requirements? (Choose two.)`,correct:[[`Create a second queue in the same AWS account and Region and configure it as the dead-letter queue of the source queue`,`A dead-letter queue collects messages that are not processed successfully, and it must be in the same account and Region as its source queue.`],[`Set a redrive policy with a maxReceiveCount high enough to allow sufficient retries before a message moves`,`The redrive policy sets how many times a message can be received before it moves, and a high enough value keeps the system resilient to errors.`]],wrong:[[`Create the dead-letter queue in a different AWS Region so that it survives a Regional outage`,`A dead-letter queue must be in the same AWS account and Region as the source queue.`],[`Set the maxReceiveCount to 1 so that a single failure moves the message`,`One failure to receive a message would move it, which gives no room for retries after temporary errors.`],[`Delete each message that fails once, and log the message identifier`,`The messages would be lost and the engineers could not examine their contents.`]],slots:[3,4],evidence:[`sqs-dlq|Amazon SQS supports dead-letter queues (DLQs), which source queues can target for messages that are not processed successfully.`,`sqs-dlq|The dead-letter queue must be in the same AWS account and Region as the source queue.`,`sqs-dlq|To ensure that your system is resilient against errors, set the maxReceiveCount high enough to allow for sufficient retries.`]}),t({id:`message-quay-008`,building:`message-quay`,bullets:[`2.1-K11`],d:3,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`An e-commerce company must process the events of each customer in the exact order in which they were sent. Events of different customers can be processed in parallel by many consumers, and duplicates must not be introduced into the queue. Which solution BEST meets these requirements?`,correct:[`An Amazon SQS FIFO queue that uses the customer ID as the message group ID`,`A FIFO queue preserves the order of messages and adds no duplicates, and message groups provide separate ordered streams within one queue.`],wrong:[[`An Amazon SQS standard queue whose consumers sort the messages by timestamp`,`A standard queue can deliver more than one copy of a message and out of order, so the consumers would have to correct this themselves.`],[`One Amazon SQS standard queue for each customer, each read by a single consumer`,`Standard queues make only a best-effort attempt at ordering and can deliver duplicates, whatever the number of queues.`],[`An Amazon SNS standard topic with one Amazon SQS standard queue subscribed for all events`,`Standard queues and topics do not strictly preserve order, and the queue can still receive duplicates.`]],slot:1,evidence:[`sqs-fifo|The order in which messages are sent and received is strictly preserved and a message is delivered once and remains unavailable until a consumer processes and deletes it.`,`sqs-fifo|Additionally, FIFO queues support message groups that allow multiple ordered message groups within a single queue.`,`sqs-standard|Standard queues ensure at-least-once message delivery, but due to the highly distributed architecture, more than one copy of a message might be delivered, and messages may occasionally arrive out of order.`]}),t({id:`message-quay-009`,building:`message-quay`,bullets:[`2.1-K11`],d:1,stem:`A company runs its own Apache ActiveMQ message broker whose applications use JMS and AMQP. It wants a managed broker on AWS and does not want to rewrite the messaging code of the applications. Which service BEST meets these requirements?`,correct:[`Amazon MQ with an Apache ActiveMQ broker`,`Amazon MQ is a managed message broker service for ActiveMQ, and existing brokers can be migrated without rewriting messaging code.`],wrong:[[`Amazon SQS with standard queues`,`SQS does not support the AMQP protocol, and AWS recommends Amazon MQ for applications that rely on JMS and AMQP compatibility.`],[`Amazon SNS with topics for each application`,`SNS is a publish and subscribe service and is not a managed broker for JMS and AMQP applications.`],[`Amazon EventBridge with an event bus`,`EventBridge routes events to targets and is not a message broker that supports JMS and AMQP clients.`]],slot:2,evidence:[`mq-what-is|You can create a new Amazon MQ broker using industry standard messaging protocols, or migrate existing message brokers to Amazon MQ without rewriting messaging code.`,`sqs-what-is|We recommend Amazon MQ for migrating applications from existing message brokers that rely on compatibility with APIs such as JMS or protocols such as Advanced Message Queuing Protocol (AMQP), MQTT, OpenWire, and Simple Text Oriented Message Protocol (STOMP).`]}),t({id:`message-quay-010`,building:`message-quay`,bullets:[`2.1-K11`],d:2,stem:`Consumers call ReceiveMessage on an Amazon SQS queue in a continuous loop, and most of the calls return empty responses, which increases the cost of using the queue. The company wants the LOWEST cost with the LEAST change to the consumers. Which solution meets these requirements?`,correct:[`Enable long polling by setting the receive wait time of the queue to more than 0 seconds`,`Long polling waits until a message is available, which reduces the number of empty responses and lowers cost.`],wrong:[[`Increase the visibility timeout of the queue so that messages stay hidden for longer`,`The visibility timeout hides received messages from other consumers and does not change the number of empty responses.`],[`Reduce the message retention period of the queue so that old messages are removed sooner`,`The retention period controls how long messages are kept, and the empty ReceiveMessage calls would continue.`],[`Keep short polling and add a delay queue that holds each new message before delivery`,`A delay makes messages available later and does not reduce the number of empty responses from polling.`]],slot:3,evidence:[`sqs-polling|Long polling helps reduce the cost of using Amazon SQS by reducing the number of empty responses (when there are no messages available for a ReceiveMessage request) and false empty responses (when messages are available but aren't included in a response).`,`sqs-polling|When the wait time for the ReceiveMessage API action is greater than 0, long polling is in effect.`]}),t({id:`message-quay-011`,building:`message-quay`,bullets:[`2.1-K11`],d:2,stem:`Workers need about two minutes to process each message from an Amazon SQS queue that uses default settings. Other workers keep receiving the same message while the first worker is still processing it, so work is duplicated. Which change BEST fixes this with the LEAST effort?`,correct:[`Increase the visibility timeout of the queue to more than the time the workers need to process a message`,`A received message stays hidden from other consumers for the visibility timeout, and the default is 30 seconds, which is shorter than the processing time.`],wrong:[[`Enable long polling on the queue so that the workers wait longer for new messages to arrive before they return`,`Long polling reduces empty responses and does not stop a message from becoming visible again during processing.`],[`Extend the message retention period of the queue to the maximum value`,`The retention period controls how long messages stay in the queue and does not hide a message that is being processed.`],[`Attach a dead-letter queue that receives each message after its first receive`,`This would move messages away after the first receive, even though they are still being processed correctly.`]],slot:0,evidence:[`sqs-visibility|When you receive a message from an Amazon SQS queue, it remains in the queue but becomes temporarily invisible to other consumers.`,`sqs-visibility|The default visibility timeout for a queue is 30 seconds, but you can adjust this to match the time your application needs to process and delete a message.`,`sqs-visibility|If you don't delete it before the timeout expires, the message becomes visible again in the queue and can be retrieved by another consumer.`]}),t({id:`message-quay-012`,building:`message-quay`,bullets:[`2.1-K16`],d:1,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`An order process has ordered steps: validate payment, reserve stock and send a confirmation. It needs branching, automatic retries and a console view where engineers can visualize and debug each run, with the LEAST custom orchestration code. Which service BEST meets these requirements?`,correct:[`AWS Step Functions, with a workflow of ordered states`,`Step Functions workflows are made of ordered states, support Retry and Catch, and can be visualized and debugged in the console.`],wrong:[[`Amazon SQS, with a queue between the steps of the process`,`A queue buffers messages between components and does not sequence steps, branch or show a visual run of a process.`],[`Amazon SNS, with a topic for each step of the process`,`A topic delivers a message to subscribers and does not coordinate ordered steps or retries.`],[`Amazon EventBridge, with a rule for each step of the process`,`EventBridge routes events to targets and does not hold the sequence and state of a multi-step process.`]],slot:1,evidence:[`stepfunctions|In the Step Functions' console, you can visualize, edit, and debug your application’s workflow.`,`stepfunctions|Error handling (Retry / Catch) – You can retry failed tasks, or catch failed tasks and automatically run alternative steps.`,`stepfunctions|Orchestrate tasks – You can create workflows that orchestrate a series of tasks, or steps, in a specific order.`]}),t({id:`message-quay-013`,building:`message-quay`,bullets:[`2.1-K16`],d:2,stem:`A loan-approval process can take several weeks because it waits for a manager to sign off. Each step must run exactly once, and auditors need the execution history of every run. The company wants the LEAST custom code. Which solution meets these requirements?`,correct:[`A Standard workflow in AWS Step Functions that waits for a callback with a task token`,`Standard workflows are long-running and auditable with exactly-once execution, and a task token lets the workflow wait for the approval.`],wrong:[[`An Express workflow in AWS Step Functions that waits for a callback with a task token`,`Express workflows run for up to five minutes and have at-least-once execution, which does not fit weeks of waiting.`],[`A chain of AWS Lambda functions in which each function sleeps until the approval arrives`,`This is custom waiting code and has no execution history that auditors can inspect for each run.`],[`An Amazon SQS queue whose consumers keep each message hidden until the manager responds`,`A queue has no workflow history, and keeping messages hidden for weeks is custom logic that the company would maintain.`]],slot:2,evidence:[`stepfunctions|Standard workflows are ideal for long-running, auditable workflows, as they show execution history and visual debugging.`,`stepfunctions|Standard workflows have exactly-once workflow execution and can run for up to one year.`,`stepfunctions|Express workflows have at-least-once workflow execution and can run for up to five minutes.`,`stepfunctions|With a callback and a task token, you can have Step Functions wait until the customers friend confirms the transfer, and then Step Functions will continue the workflow to notify the banking customer that the transfer has completed.`]}),t({id:`message-quay-014`,building:`message-quay`,bullets:[`2.1-K16`],d:3,stem:`A company receives a very high rate of sensor readings. Each reading starts a short workflow that finishes within seconds. Every step is idempotent, so a step that occasionally runs more than once does no harm. The company wants the workflow type that BEST fits this high-event-rate processing. Which solution meets these requirements?`,correct:[`An Express workflow in AWS Step Functions that runs each reading as its own execution`,`Express workflows are ideal for high-event-rate workloads such as streaming data processing, and at-least-once execution is acceptable for idempotent steps.`],wrong:[[`A Standard workflow in AWS Step Functions for every reading, because it runs each step exactly once`,`Standard workflows are meant for long-running, auditable workflows, not high-event-rate streaming workloads.`],[`A Standard workflow in AWS Step Functions with a Wait state between the steps`,`A Wait state adds no benefit for short executions, and Standard remains the type for long-running, auditable workflows.`],[`An AWS Lambda function that calls the steps one after another in code`,`This moves the sequencing into custom code instead of using a workflow service for the high-event-rate processing.`]],slot:3,evidence:[`stepfunctions|Express workflows are ideal for high-event-rate workloads, such as streaming data processing and IoT data ingestion.`,`stepfunctions|This means that one or more steps in an Express Workflow can potentially run more than once, while each step in the workflow executes at least once.`,`stepfunctions|Standard workflows are ideal for long-running, auditable workflows, as they show execution history and visual debugging.`]}),e({id:`message-quay-015`,building:`message-quay`,bullets:[`2.1-K16`],d:2,stem:`A credit-limit request workflow calls a validation service that sometimes fails on the first attempt. Requests above the customer's pre-approved limit must go to a manager, and all other requests must be approved automatically. The company wants the LEAST custom code. Which TWO AWS Step Functions capabilities meet these requirements? (Choose two.)`,correct:[[`A Retry configuration on the validation task`,`A failed task can be retried, so a first failure of the validation service does not need custom code.`],[`A Choice state that branches on the requested amount`,`A Choice state decides on the input of the state, so large requests can go to a manager and others be approved automatically.`]],wrong:[[`A Map state that runs the same steps on every item of a dataset`,`A Map state iterates over the items of a dataset, and the requirement is a decision based on one request.`],[`A Parallel state that runs the validation and the manager approval at the same time`,`A Parallel state runs steps at the same time, whereas only large requests should reach a manager.`],[`An Express workflow type so that the approval step can wait for several days`,`Express workflows can run for up to five minutes, which is not enough to wait for a manager.`]],slots:[1,2],evidence:[`stepfunctions|Error handling (Retry / Catch) – You can retry failed tasks, or catch failed tasks and automatically run alternative steps.`,`stepfunctions|Choose tasks based on data – Using a Choice state, you can have Step Functions make decisions based on the state’s input.`,`stepfunctions|Express workflows have at-least-once workflow execution and can run for up to five minutes.`]}),t({id:`message-quay-016`,building:`message-quay`,bullets:[`2.1-S3`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A company continuously collects website clickstream records. Two applications must read the same records in real time, concurrently and independently: one computes running aggregates and the other archives the raw records to Amazon S3. Which service BEST meets these requirements?`,correct:[`Amazon Kinesis Data Streams, with one stream that both applications read`,`Kinesis Data Streams collects and processes large streams of data records in real time, and multiple applications can consume the same stream independently.`],wrong:[[`One Amazon SQS standard queue that both applications poll for the clickstream records`,`A queue typically processes each message through a single subscriber, so the two applications would split the records instead of each reading all of them.`],[`Amazon EventBridge with a custom event bus`,`EventBridge routes events from sources to targets and is not the service for collecting and processing large streams of data records.`],[`Amazon MQ with a queue for each application`,`Amazon MQ is recommended for migrating applications from existing brokers, and there is no existing broker here.`]],slot:0,evidence:[`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`,`kinesis-streams|Multiple Kinesis Data Streams applications can consume data from a stream, so that multiple actions, like archiving and processing, can take place concurrently and independently.`,`sqs-what-is|It processes messages through a single subscriber typically, ideal for workflows where order and loss prevention are critical.`]}),t({id:`message-quay-017`,building:`message-quay`,bullets:[`2.1-S3`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A news application must send each breaking-news message to a very large number of subscribed endpoints, including mobile push notifications and email addresses. Messages come from many publishers at high throughput and with low latency, and the message format is not fixed. Which service BEST meets these requirements?`,correct:[`Amazon SNS, with a topic that the endpoints subscribe to`,`SNS suits high-throughput, low-latency messages with very high fanout, its topics do not depend on a message schema, and it supports push and email endpoints.`],wrong:[[`Amazon EventBridge, with a rule for each subscribed endpoint`,`EventBridge works on events with a predefined schema and rules, and it is not the service recommended for very high fanout of schema-agnostic messages to mobile push and email endpoints.`],[`Amazon SQS, with one queue for each subscribed endpoint`,`Queues are polled by consumers and do not push messages to mobile devices or email addresses.`],[`Amazon Kinesis Data Streams, with a stream that each endpoint reads`,`A stream is read by consumer applications and does not push messages to mobile devices or email addresses.`]],slot:1,evidence:[`eda-overview|Amazon SNS is recommended when you want to build an application that reacts to high throughput and low latency events published by other applications, microservices, or AWS services, or for applications that need very high fanout (thousands or millions of endpoints).`,`eda-overview|SNS topics are agnostic to the event schema coming through.`,`sns-what-is|Subscribers to an SNS topic can receive messages through different endpoints, depending on their use case, such as: Amazon SQS Lambda HTTP(S) endpoints Email Mobile push notifications Mobile text messages (SMS)`]}),t({id:`message-quay-018`,building:`message-quay`,bullets:[`2.1-S3`],d:3,stem:`A payment service reads messages from an Amazon SQS standard queue, which must remain a standard queue. Occasionally the same message is delivered twice and the customer is charged twice. The company wants to prevent duplicate charges with the LEAST change to the architecture. Which solution meets these requirements?`,correct:[`Make the charge operation idempotent by sending an idempotency token with each charge request`,`An idempotent service returns the same result for repeated identical requests, so a duplicate message does not charge the customer twice.`],wrong:[[`Raise the visibility timeout of the queue to the maximum so that no message is delivered again`,`There is no absolute guarantee that a message is not delivered more than once, because of the at-least-once delivery model.`],[`Enable long polling on the queue so that consumers receive each message only once`,`Long polling reduces empty responses and does not change the at-least-once delivery of standard queues.`],[`Run the consumer on a single instance so that two consumers never see the same message`,`A standard queue can still deliver more than one copy of a message to a single consumer.`]],slot:2,evidence:[`sqs-standard|Standard queues ensure at-least-once message delivery, but due to the highly distributed architecture, more than one copy of a message might be delivered, and messages may occasionally arrive out of order.`,`waf-idempotent|An idempotent service promises that each request is processed exactly once, such that making multiple identical requests has the same effect as making a single request.`,`waf-idempotent|To do this, clients can issue API requests with an idempotency token, which is used whenever the request is repeated.`]}),e({id:`message-quay-019`,building:`message-quay`,bullets:[`2.1-S3`],d:3,stem:`An order API calls three downstream services synchronously over HTTP, and the services share one database. An outage in one service now fails orders, and retries sometimes create duplicate records. The company wants to loosely couple the services and make the system MOST resilient to failures in any one of them. Which THREE changes meet these requirements? (Choose three.)`,correct:[[`Put an Amazon SQS queue between the API and each downstream service so that requests are buffered`,`An intermediate queue makes the interaction asynchronous, so an outage in one service no longer fails the API.`],[`Attach a dead-letter queue to each queue so that messages that cannot be processed are set aside`,`Messages that are not processed successfully move to a dead-letter queue, where they can be examined without blocking the others.`],[`Make the consumers idempotent by using idempotency tokens for each request`,`An idempotent consumer can safely handle a repeated request, so retries do not create duplicate records.`]],wrong:[[`Keep the services calling one another directly and add retries to the API`,`Directly invoking APIs without asynchronous processing keeps the services tightly coupled.`],[`Move the services to larger Amazon EC2 instances so that they fail less often`,`Larger instances do not remove the dependency between the services, so an outage still fails orders.`],[`Let the services keep sharing the one database to exchange data with each other`,`Sharing data through a shared database reintroduces tight coupling and hinders scalability.`]],slots:[1,3,4],evidence:[`waf-loose-coupling|Directly invoking APIs between workload tiers with no capability of failover or asynchronous processing of the request.`,`waf-loose-coupling|Loosely coupled systems should avoid sharing data through shared databases or other forms of tightly coupled data storage, which can reintroduce tight coupling and hinder scalability.`,`sqs-dlq|Amazon SQS supports dead-letter queues (DLQs), which source queues can target for messages that are not processed successfully.`,`waf-idempotent|Using idempotency tokens in APIs, services can receive a mutating request one or more times without the need to create duplicate records or side effects.`]}),t({id:`message-quay-020`,building:`message-quay`,bullets:[`2.1-K5`,`2.1-S3`],d:2,tags:[`mock-reserve`],stem:`A company must invoke an AWS Lambda function every night at a fixed time. The company wants a serverless way to do this, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`An Amazon EventBridge rule that runs on a schedule with a cron expression and has the function as its target`,`An EventBridge rule can run on a defined schedule and invoke a target such as a function, with no servers to manage.`],wrong:[[`An Amazon EC2 instance that runs cron jobs which call the function`,`The company would have to run and patch the instance, which adds operational overhead.`],[`An AWS Step Functions Standard workflow that loops with a Wait state until the next night`,`The company would have to build and maintain a long-running workflow instead of using a schedule.`],[`An Amazon SQS queue that delivers a message to the function every night`,`A queue holds messages and does not create a time-based schedule on its own.`]],slot:3,evidence:[`eventbridge-rules|You can create two types of rules: rules that match on event data as events are delivered, and rules that run on a defined schedule.`,`eventbridge-rules|A rule specifies which events to send to which targets for processing.`]}),t({id:`message-quay-021`,building:`message-quay`,bullets:[`2.1-K11`],d:2,tags:[`mock-reserve`],stem:`A consumer application of an Amazon SQS queue will be offline for planned maintenance for ten days. Messages that arrive in that time must not be deleted by the queue. The company wants the LEAST effort. Which change meets these requirements?`,correct:[`Set the message retention period of the queue to the maximum of 14 days`,`The default retention period is 4 days, and it can be set to a value up to 14 days, so messages survive ten days.`],wrong:[[`Leave the default message retention period, which keeps messages for ten days`,`The default message retention period is 4 days, so older messages are deleted automatically.`],[`Set the visibility timeout of the queue to the maximum so that messages stay hidden`,`The visibility timeout hides received messages from other consumers and does not extend how long messages are kept.`],[`Enable long polling with the longest wait time so that the queue waits for the consumer`,`Long polling reduces empty responses and does not extend the time that messages stay in the queue.`]],slot:0,evidence:[`sqs-what-is|Amazon SQS automatically deletes messages that have been in a queue for more than the maximum message retention period.`,`sqs-what-is|The default message retention period is 4 days.`,`sqs-what-is|However, you can set the message retention period to a value from 60 seconds to 1,209,600 seconds (14 days) using the SetQueueAttributes action.`]}),t({id:`message-quay-022`,building:`message-quay`,bullets:[`2.1-K16`,`2.1-S3`],d:3,tags:[`mock-reserve`],stem:`When a customer orders thirty items, the system must run the same set of workflow steps on each item, and the iterations should run in parallel so that the whole order is prepared quickly. The company wants the LEAST custom code. Which solution meets these requirements?`,correct:[`An AWS Step Functions workflow that uses a Map state over the items of the order`,`A Map state runs a set of workflow steps on each item in a dataset, and the iterations run in parallel.`],wrong:[[`An AWS Step Functions workflow that uses a Choice state for each item of the order`,`A Choice state decides between branches based on its input and does not repeat the steps for each item.`],[`An AWS Step Functions workflow that uses a Parallel state with thirty hand-written branches`,`A Parallel state runs defined steps in parallel on the input, and thirty branches would be hand-built and fixed in number.`],[`An Amazon SNS topic that publishes the order to thirty subscribed AWS Lambda functions`,`Each function would receive the whole order, and no workflow coordinates the steps for each item.`]],slot:1,evidence:[`stepfunctions|Dynamically process data elements – Using a Map state, Step Functions can run a set of workflow steps on each item in a dataset.`,`stepfunctions|The iterations run in parallel, which makes it possible to process a dataset quickly.`,`stepfunctions|Choose tasks based on data – Using a Choice state, you can have Step Functions make decisions based on the state’s input.`]})],d=[t({id:`purpose-built-workshop-001`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:1,stem:`A company's trading partners upload daily files with SFTP clients that the partners cannot change. The company wants the files to land in an Amazon S3 bucket and does not want to run or patch SFTP servers. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AWS Transfer Family server that uses the SFTP protocol and stores files in the S3 bucket`,`Transfer Family is a fully managed service for SFTP transfers directly into AWS storage, and partners can keep their existing client configurations.`],wrong:[[`Run an SFTP server on an Amazon EC2 instance and copy each uploaded file to the S3 bucket`,`The company would run, patch and scale the SFTP server itself, which the company wants to avoid.`],[`Create an AWS DataSync task and ask each partner to start it from the partner's SFTP client`,`DataSync transfers files between storage systems and AWS services and does not give partners an SFTP endpoint.`],[`Enable Amazon S3 Transfer Acceleration on the bucket and ask partners to upload to the accelerate endpoint`,`Partners would have to switch from SFTP to the S3 accelerate endpoint, and they cannot change their clients.`]],slot:0,evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`transfer-what-is|You can seamlessly migrate, automate, and monitor your file transfer workflows by maintaining existing client-side configurations for authentication, access, and firewalls`,`datasync-how|The following diagram shows a high-level overview of DataSync transferring files between self-managed, on-premises storage systems and AWS services.`]}),t({id:`purpose-built-workshop-002`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:2,tags:[`trap:secrets-manager-vs-parameter-store`],stem:`An application on Amazon ECS reads an Amazon RDS database password from a configuration file in its container image. A new policy requires the password to be rotated automatically every 30 days without rebuilding images or redeploying the application. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Store the password in AWS Secrets Manager, turn on automatic rotation and have the application retrieve it at runtime`,`Secrets Manager rotates credentials on a schedule, and because the application retrieves them at runtime, rotation needs no application update.`],wrong:[[`Store the password as a SecureString parameter in AWS Systems Manager Parameter Store and update it by hand each month`,`The manual update is not automatic rotation, and AWS recommends Secrets Manager for credentials that must rotate automatically.`],[`Store the password in a task definition environment variable and redeploy the tasks after each change`,`Every rotation would need a redeployment, which the company wants to avoid.`],[`Store the password in an Amazon S3 object and run a function each month to overwrite the object`,`The company would write and maintain the rotation code and the retrieval logic itself.`]],slot:1,evidence:[`secrets-intro|You replace hard-coded credentials with a runtime call to the Secrets Manager service to retrieve credentials dynamically when you need them.`,`secrets-intro|Since the credentials are no longer stored with the application, rotating credentials no longer requires updating your applications and deploying changes to application clients.`,`ssm-parameter-store|For secrets such as database credentials, API keys, or tokens, we recommend AWS Secrets Manager, which provides purpose built security controls including automatic rotation and cross-region replication.`]}),t({id:`purpose-built-workshop-003`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`An online store's checkout service calls an order-fulfillment service directly. During promotions, fulfillment slows down and checkout requests time out. The company wants checkout to accept orders even when fulfillment is slow or briefly offline, using a managed service with the LEAST operational overhead. Which solution BEST meets these requirements?`,correct:[`Have checkout place each order in an Amazon SQS queue that the fulfillment service reads at its own pace`,`The queue buffers orders durably so checkout is decoupled from fulfillment, and it absorbs spikes without provisioning.`],wrong:[[`Have checkout publish each order to an Amazon SNS topic with the fulfillment service's HTTPS endpoint subscribed`,`A subscriber that is offline can miss messages when no queue holds them, so orders could be lost.`],[`Add more fulfillment servers in an Amazon EC2 Auto Scaling group behind the same direct call`,`Checkout would still call fulfillment directly, so an offline or slow service would still fail checkout requests.`],[`Put an Application Load Balancer between the two services and raise the checkout timeout`,`The services stay coupled, and a longer timeout only makes customers wait while fulfillment is unavailable.`]],slot:2,evidence:[`sqs-what-is|Amazon Simple Queue Service (Amazon SQS) offers a secure, durable, and available hosted queue that lets you integrate and decouple distributed software systems and components.`,`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`,`sqs-what-is|To prevent message loss when subscribers are offline, integrating Amazon SNS with Amazon SQS queue messages ensures consistent delivery.`]}),e({id:`purpose-built-workshop-004`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`Suppliers send purchase files to a company over FTPS. The company must store the files in Amazon S3 and have a processing application handle each file later. The application is sometimes offline for hours, and no file notification may be lost. The company wants managed services with the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Transfer Family server that uses the FTPS protocol and stores the files in the S3 bucket`,`Transfer Family offers fully managed FTPS transfers directly into AWS storage, so there is no server to run.`],[`Send an S3 event notification for each new object to an Amazon SQS queue that the application reads when it is online`,`S3 can send event notifications to SQS queues, and the durable queue holds each message until the application is back.`]],wrong:[[`Run an FTPS server on an Amazon EC2 instance that writes the files to the S3 bucket`,`The company would run, patch and scale the FTPS server itself.`],[`Send an S3 event notification to an Amazon SNS topic with the application's HTTPS endpoint as the subscriber`,`An offline subscriber can miss messages because no queue holds them, so notifications can be lost once delivery retries are exhausted.`],[`Turn on Amazon S3 Transfer Acceleration and have the suppliers upload to the accelerate endpoint`,`Suppliers send files over FTPS, and Transfer Acceleration provides an S3 endpoint rather than an FTPS server.`]],slots:[0,3],evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`s3-event-notifications|Amazon S3 can send event notification messages to the following destinations.`,`s3-event-notifications|Amazon Simple Notification Service (Amazon SNS) topics Amazon Simple Queue Service (Amazon SQS) queues AWS Lambda function Amazon EventBridge`,`sqs-what-is|To prevent message loss when subscribers are offline, integrating Amazon SNS with Amazon SQS queue messages ensures consistent delivery.`]}),t({id:`purpose-built-workshop-005`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:3,tags:[`trap:secrets-manager-vs-parameter-store`],stem:`A company runs a payment application in one Region and keeps a warm standby in a second Region. Database credentials are rotated every 30 days. The standby application must read the current credentials from inside its own Region, even if the primary Region is unavailable, and the company does not want to write synchronization code. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Store the credentials in AWS Secrets Manager with automatic rotation and replicate the secret to the second Region`,`Replicas serve applications in the other Region, and rotation of the primary secret propagates the new value to every replica.`],wrong:[[`Store the credentials in the primary Region only and let the standby call that Region's Secrets Manager endpoint across Regions`,`The standby would depend on the primary Region, so it could not read credentials during a primary Region outage.`],[`Keep SecureString parameters in Parameter Store in both Regions and update each copy on a schedule`,`Parameter Store does not rotate the credentials automatically or replicate them, so the company would build the sync.`],[`Copy the secret to the second Region with a scheduled AWS Lambda function that the company writes`,`This is the custom synchronization code that the company wants to avoid.`]],slot:3,evidence:[`secrets-replicate|You can replicate your secrets in multiple AWS Regions to support applications spread across those Regions to meet Regional access and low latency requirements.`,`secrets-replicate|If you turn on rotation for your primary secret, Secrets Manager rotates the secret in the primary Region, and the new secret value propagates to all of the associated replica secrets.`,`ssm-parameter-store|For secrets such as database credentials, API keys, or tokens, we recommend AWS Secrets Manager, which provides purpose built security controls including automatic rotation and cross-region replication.`]}),t({id:`purpose-built-workshop-006`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:1,stem:`A social networking company wants to recommend friends by traversing relationships among hundreds of millions of users. The queries must return results with low latency, and the company wants a fully managed database. Which database BEST fits this workload?`,correct:[`Amazon Neptune, a fully managed graph database for highly connected datasets`,`Neptune is purpose-built for traversing large numbers of relationships and supports recommendation engines.`],wrong:[[`Amazon RDS for MySQL, with a table of friendships queried through many self-joins`,`RDS is built for structured data in tables, not for traversing large numbers of relationships.`],[`Amazon DynamoDB, with one item per user listing the user's friends`,`A key-value table fetches items by key, and it is not built for traversing relationship patterns.`],[`Amazon Redshift, with the friendships loaded into a data warehouse`,`Redshift is a data warehouse for large-scale analytics, not for low-latency relationship traversal.`]],slot:1,evidence:[`neptune-what-is|Amazon Neptune is a fast, reliable, fully managed graph database service that makes it easy to build and run applications that work with highly connected datasets.`,`database-decision|Optimized for traversing and evaluating large numbers of relationships, and identifying patterns with minimal latency.`]}),t({id:`purpose-built-workshop-007`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:2,stem:`A gaming company stores player session state and shopping-cart items for millions of concurrent users. Items are always read and written by player ID, load is unpredictable, and the company wants single-digit millisecond latency with no database servers to manage. Which database is the BEST fit?`,correct:[`Amazon DynamoDB, a serverless key-value table keyed by player ID`,`DynamoDB is serverless with single-digit millisecond performance at any scale, and AWS suggests it for session stores and shopping carts.`],wrong:[[`Amazon RDS for PostgreSQL on a large Multi-AZ DB instance with read replicas`,`The company would size and manage DB instances, and it does not need a relational model for lookups by player ID.`],[`Amazon DocumentDB (with MongoDB compatibility) cluster that stores each session as a document`,`DocumentDB suits rich queries across document fields, which lookups by player ID do not need.`],[`Amazon Redshift cluster that stores each session as a row in a warehouse table`,`Redshift is a data warehouse for large-scale analytics, not a low-latency store for session lookups.`]],slot:2,evidence:[`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`,`database-decision|Use for workloads such as session stores or shopping carts.`]}),t({id:`purpose-built-workshop-008`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:2,stem:`A company's catalog application stores product data as JSON-like documents in a self-managed MongoDB database. Developers run rich queries across the fields of the documents. The company wants a fully managed AWS database with the LEAST application change. Which solution BEST meets these requirements?`,correct:[`Migrate the data to Amazon DocumentDB (with MongoDB compatibility)`,`DocumentDB is the purpose-built document database for JSON-like documents with rich querying across fields, with MongoDB compatibility.`],wrong:[[`Migrate the data to Amazon DynamoDB and remodel each document as key-value items`,`DynamoDB is a key-value database, so the document model and the field queries would have to be reworked.`],[`Migrate the data to Amazon RDS for MySQL and store each document in a text column`,`RDS is a relational database for structured data in tables, so the document queries would have to be rewritten.`],[`Migrate the data to Amazon Keyspaces (for Apache Cassandra) and rewrite the queries`,`Keyspaces is a wide-column database for Cassandra workloads and is not a document database.`]],slot:3,evidence:[`database-decision|Use when you want to store JSON-like documents with rich querying abilities across the fields of the documents.`,`database-decision|Optimized for storing semi-structured data as documents with multilayered attributes.`,`database-decision|Use when you need to migrate your on-premises Cassandra workloads, or when you need to process data at high speeds for applications that require single-digit millisecond latency.`]}),t({id:`purpose-built-workshop-009`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:3,stem:`A retailer's product-detail pages read the same catalog rows from an Amazon RDS database thousands of times per second. The company wants read response times measured in microseconds rather than single-digit milliseconds. The RDS database must stay the system of record, and the cached data can be rebuilt from it at any time. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Add Amazon ElastiCache in front of the database and serve repeated reads from the cache`,`An in-memory cache alongside the database serves hot reads in microseconds, while the database remains the durable system of record.`],wrong:[[`Add Amazon RDS read replicas and spread the catalog reads across the replicas`,`Replicas are database engines that still answer reads in milliseconds, not the in-memory microsecond responses the company wants.`],[`Migrate the catalog to Amazon DynamoDB tables and read from them directly`,`DynamoDB reads are single-digit milliseconds, and the RDS database would no longer be the system of record.`],[`Move the catalog to an Amazon Redshift cluster and run the page queries there`,`Redshift is a data warehouse for large-scale analytics and is not built for microsecond reads of hot rows.`]],slot:0,evidence:[`database-decision|If your workload requires extremely high read performance with a response time measured in microseconds (rather than single-digit milliseconds), you might want to consider using in- memory caching solutions such as Amazon ElastiCache alongside your database`,`database-decision|Use when you need a caching layer to improve read performance.`,`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`]}),e({id:`purpose-built-workshop-010`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:3,stem:`An e-commerce company is designing a new platform. The product catalog and user profiles are semi-structured JSON-like documents that need rich queries across fields. The product pages are served by simple key-based lookups that need low, predictable latency at a very high request rate, while the catalog documents themselves are managed and queried separately. Inventory and order processing need a relational data model with transaction support. The company wants a purpose-built managed database for each need. Which THREE choices meet these requirements? (Choose three.)`,correct:[[`Amazon DocumentDB (with MongoDB compatibility) for the catalog and user profiles`,`DocumentDB stores semi-structured documents and supports rich queries across their fields.`],[`Amazon DynamoDB for serving product browsing requests`,`DynamoDB provides low, predictable latency at very high request rates.`],[`Amazon Aurora for inventory and order processing`,`Aurora provides the relational data model and transaction support that inventory and orders need.`]],wrong:[[`Amazon Neptune for inventory and order processing`,`Neptune is a graph database for highly connected datasets and not a relational database for transactions.`],[`Amazon Redshift for serving product browsing requests`,`Redshift is a data warehouse for analytics, not a store for low-latency browsing requests.`],[`Amazon ElastiCache as the only store for the user profiles`,`ElastiCache is an ephemeral cache for frequently accessed data, so profiles kept only there would not be durable.`]],slots:[0,3,4],evidence:[`database-decision|in an ecommerce use case, you might use Amazon DocumentDB (for product catalogs and user profiles) for the flexibility that is provided by semi-structured data`,`database-decision|You might also add Aurora into the mix for inventory and order processing, where a relational data model and transaction support are needed.`,`database-decision|combine it with the low, predictable latency provided by DynamoDB (for when your users are browsing your product catalog)`]}),t({id:`purpose-built-workshop-011`,building:`purpose-built-workshop`,bullets:[`2.1-S7`],d:2,tags:[`mock-reserve`],stem:`A company runs an Apache Cassandra cluster on premises for a high-throughput application that needs single-digit millisecond latency. The company wants to move to a managed AWS database that keeps the Cassandra data model, with the LEAST operational overhead. Which service should the company choose?`,correct:[`Amazon Keyspaces (for Apache Cassandra), the managed wide-column service`,`Keyspaces is the purpose-built wide-column database for migrating on-premises Cassandra workloads with single-digit millisecond latency.`],wrong:[[`Amazon Neptune, loading the Cassandra tables as a graph of nodes and edges`,`Neptune is a graph database for highly connected data and does not keep the Cassandra data model.`],[`Amazon RDS for PostgreSQL, loading the Cassandra tables as relational tables`,`RDS is a relational database for structured data, so the data model and application queries would change.`],[`Amazon ElastiCache, loading the Cassandra data into an in-memory cache`,`ElastiCache is an ephemeral cache and not a durable database for the Cassandra data.`]],slot:1,evidence:[`database-decision|Use when you need to migrate your on-premises Cassandra workloads, or when you need to process data at high speeds for applications that require single-digit millisecond latency.`,`database-decision|Optimized for workloads that require heavy reads/writes and high throughput, coupled with low latency and linear scalability.`]}),t({id:`purpose-built-workshop-012`,building:`purpose-built-workshop`,bullets:[`2.1-K2`],d:2,tags:[`mock-reserve`],stem:`A company exchanges purchase orders and invoices with retail partners using the AS2 protocol for business-to-business transactions. The files must be stored in Amazon S3, and the company does not want to run its own AS2 servers. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use AWS Transfer Family with the AS2 protocol and an S3 bucket as the storage`,`Transfer Family offers fully managed AS2 support directly into AWS storage, and B2B transactions are a listed AS2 use case.`],wrong:[[`Run AS2 server software on an Amazon EC2 instance and copy received files to the bucket`,`The company would run, patch and scale the AS2 server itself.`],[`Create an Amazon SQS queue and ask each partner to send its documents as queue messages`,`A queue is a messaging service and does not provide an AS2 endpoint for the partners.`],[`Create an AWS DataSync task that copies the partners' documents into the bucket on a schedule`,`DataSync moves data between storage systems and AWS and does not provide an AS2 endpoint for partners.`]],slot:0,evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`transfer-what-is|The following are some common use cases for using Transfer Family with AS2: Workflows with compliance requirements that rely on having data protection and security features built into the protocol Supply chain logistics Payments workflows Business-to-business (B2B) transactions`]})],f=[t({id:`rebuild-yard-001`,building:`rebuild-yard`,bullets:[`2.2-K7`],d:1,stem:`A company patches its production web servers in place over SSH, and audits keep finding servers whose configuration differs from the others. The company wants to adopt immutable infrastructure. Which approach BEST meets this goal?`,correct:[`Build a new image that includes each patch and launch replacement instances from it instead of patching the running servers`,`Immutable infrastructure allows no in-place patches on production, so a change is built onto new infrastructure that replaces the old, which also removes configuration drift.`],wrong:[[`Patch the running servers in place on a fixed schedule and record every change in a version-controlled runbook`,`The servers are still modified in place, which immutable infrastructure does not allow, so drift can still appear.`],[`Take an Amazon EBS snapshot of each server before every patch so that a failed change can be reversed by restoring it`,`The patches are still applied in place on the running servers, and rollback means restoring volumes, not returning to an unchanged version.`],[`Give each administrator a separate SSH key pair so that every in-place change can be traced back to one person`,`Tracing changes does not stop them, so servers are still patched in place and can still drift apart.`]],slot:0,evidence:[`waf-immutable|Immutable infrastructure is a model that mandates that no updates, security patches, or configuration changes happen in-place on production workloads.`,`waf-immutable|When a change is needed, the architecture is built onto new infrastructure and deployed into production.`]}),t({id:`rebuild-yard-002`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:1,stem:`A team wants to describe a scalable web environment (an Auto Scaling group, a load balancer and a database) in text files kept in version control, so the same environment can be created again in another AWS Region. Which service BEST meets this requirement?`,correct:[`AWS CloudFormation, with a template that describes the resources and is reused to create them in each Region`,`A template describes all the resources and their settings, and the same template can provision the same resources again in other Regions.`],wrong:[[`AWS Systems Manager Run Command, with commands that are sent to the instances in each Region to configure them`,`Run Command manages the configuration of managed nodes and does not provision the group, the load balancer and the database from a description.`],[`Amazon EC2 Auto Scaling, with a group whose launch template is copied to each Region and started there`,`A group keeps the right number of instances running and does not create the load balancer and the database as well.`],[`AWS Systems Manager Patch Manager, with a patch baseline that is applied to the instances in each Region`,`Patch Manager patches nodes with security-related and other updates and does not provision resources from a template.`]],slot:1,evidence:[`cfn-what-is|Reuse your CloudFormation template to create your resources in a consistent and repeatable manner.`,`cfn-what-is|Because these templates are text files, you simply track differences in your templates to track changes to your infrastructure, similar to the way developers control revisions to source code.`,`ssm-run-command|Using Run Command, you can remotely and securely manage the configuration of your managed nodes.`]}),t({id:`rebuild-yard-003`,building:`rebuild-yard`,bullets:[`2.2-K7`,`2.2-S1`],d:2,stem:`A company runs 40 Amazon EC2 instances in an Auto Scaling group. A new AMI contains a security update, and the company wants every instance replaced by an instance launched from the new AMI, in a rolling fashion, with the LEAST manual effort. Which solution meets these requirements?`,correct:[`Create a new launch template version that specifies the new AMI and start an instance refresh on the group`,`An instance refresh rolls out a new AMI by replacing the instances of the group, and no one has to replace each instance by hand.`],wrong:[[`Run an AWS Systems Manager Run Command document on every instance to install the update on the running instances`,`The update is applied in place, so the instances are not replaced by instances launched from the new AMI.`],[`Terminate the instances one at a time and let the group replace them, leaving the launch template unchanged`,`Replacements launch with the current settings of the launch template, so they would use the old AMI, and the steps are manual.`],[`Copy the new AMI to a second Region and create a second Auto Scaling group there that uses the new AMI`,`The existing group and its instances stay on the old AMI, so the 40 instances are not replaced by the new image.`]],slot:2,evidence:[`asg-instance-refresh|Deploying a new Amazon Machine Image (AMI) or user data script across your Auto Scaling group. You can create a new launch template with the changes and then use an instance refresh to roll out the updates immediately.`,`asg-what-is|The instance refresh feature provides a mechanism to update instances in a rolling fashion when you update your AMI or launch template.`,`asg-health-checks|The new instance launches using the current settings of the Auto Scaling group and its associated launch template or launch configuration.`]}),t({id:`rebuild-yard-004`,building:`rebuild-yard`,bullets:[`2.2-K7`],d:2,stem:`A company is releasing a new version of its web application. At first only a small number of customers should reach the new version, running on a single instance, so that the team can examine errors, and those customers must be sent back to the old version if problems appear. Which deployment strategy BEST meets these requirements?`,correct:[`A canary deployment that directs a small number of customers to one instance running the new version`,`A canary is a single instance of the new version that receives a small number of customers, who can be sent back to the previous version.`],wrong:[[`A blue/green deployment that deploys a full fleet of the new version in parallel with the old fleet`,`It builds a full fleet of the new version in parallel, not the single instance the company wants.`],[`An all-at-once update that changes every running instance to the new version at the same time`,`Every customer would reach the new version at once, and the old version no longer exists to fall back to.`],[`A rolling update that modifies the existing instances in batches until all of them run the new version`,`The existing instances are modified in place, so the previous working version is changed and cannot be returned to.`]],slot:3,evidence:[`waf-immutable|Canary deployment: The practice of directing a small number of your customers to the new version, usually running on a single service instance (the canary).`,`waf-immutable|Blue/green deployment: Similar to the canary deployment, except that a full fleet of the application is deployed in parallel.`,`waf-immutable|Safer deployments with fast rollback and recovery processes: Deployments are safer because the previous working version is not changed.`]}),t({id:`rebuild-yard-005`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:2,stem:`A company manages a web environment with an AWS CloudFormation stack. During an incident, an operator changed an Amazon EC2 resource of the stack directly in the console. The company wants to find which stack resources no longer match the template, with the LEAST effort. Which solution meets this requirement?`,correct:[`Run drift detection on the stack and review the resources that are reported as drifted`,`Drift detection identifies stack resources that were changed outside CloudFormation, so the operator can bring them back in line with the template.`],wrong:[[`Delete the stack, create it again from the template and compare the new resources with the deleted ones`,`Deleting the stack deletes all of its resources, which is far more effort and far riskier than a detection step.`],[`Use AWS Systems Manager Run Command to query every instance in the stack for its settings and compare them by hand`,`It needs manual comparison and covers only instances, not the other resources of the stack.`],[`Run an AWS Systems Manager Patch Manager scan on the instances of the stack and review the report`,`A scan reports missing patches and does not compare resource properties with the template.`]],slot:0,evidence:[`cfn-drift|You can use drift detection to identify stack resources to which configuration changes have been made outside of CloudFormation management.`,`cfn-what-is|You can delete the stack just as easily, which deletes all the resources in the stack.`,`ssm-patch|Patch Manager automates the process of patching managed nodes with both security-related updates and other types of updates.`]}),t({id:`rebuild-yard-006`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:2,stem:`A company has 200 Amazon EC2 instances and a few on-premises servers. Security policy forbids opening inbound SSH ports and running bastion hosts. The company must apply security updates to all of them on a schedule. Which solution BEST meets these requirements?`,correct:[`Use AWS Systems Manager Patch Manager on managed nodes that run SSM Agent and can reach Systems Manager`,`Patch Manager patches managed nodes, including EC2 and on-premises machines, without inbound ports or bastion hosts.`],wrong:[[`Use an Amazon EC2 Auto Scaling instance refresh to replace the instances of each Auto Scaling group`,`An instance refresh updates only the instances in an Auto Scaling group, so the on-premises servers would stay unpatched.`],[`Run update scripts through a bastion host that connects to each server over SSH on a schedule`,`It needs bastion hosts and open inbound SSH ports, which the security policy forbids.`],[`Run CloudFormation drift detection on the stacks to find the servers that are missing updates and fix them`,`Drift detection compares stack resource properties with the template and does not show patch levels or cover on-premises servers.`]],slot:1,evidence:[`ssm-what-is|To use Systems Manager, nodes must be managed, which means SSM Agent is installed on the machine and the agent can communicate with the Systems Manager service.`,`ssm-patch|You can patch fleets of Amazon Elastic Compute Cloud (Amazon EC2) instances, edge devices, on-premises servers, and virtual machines (VMs) by operating system type.`,`ssm-what-is|With Systems Manager tools you can do the following: Just-in-time access node access Patch nodes at scale Securely connect to nodes without opening inbound ports Run commands remotely on nodes Securely store data referenced by applications Automate common systems administration tasks`,`asg-instance-refresh|You can use an instance refresh to update the instances in your Auto Scaling group.`]}),t({id:`rebuild-yard-007`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:2,stem:`A company must deploy the same networking and security baseline to 12 AWS accounts in two AWS Regions. The company wants to maintain one template and have the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use AWS CloudFormation StackSets to create and update the stacks in all of the accounts and Regions with a single operation`,`StackSets provisions stacks from one template into selected accounts and Regions with a single operation.`],wrong:[[`Create a CloudFormation stack by hand in every account and Region and update each stack separately each time`,`Each stack is managed separately, which multiplies the operations that StackSets would run as one.`],[`Create an AMI that holds the baseline, copy it to the second Region and share it with each of the accounts`,`An AMI provides the software to boot an instance and does not create networking and security resources in the accounts.`],[`Use AWS Systems Manager Run Command to send the configuration commands to a managed node in each Region`,`Run Command manages the configuration of managed nodes and does not deploy a template to accounts and Regions.`]],slot:2,evidence:[`cfn-stacksets|CloudFormation StackSets extends the capability of stacks by allowing you to create, update, or delete stacks across multiple accounts and AWS Regions with a single operation.`,`ami|An Amazon Machine Image (AMI) is an image that provides the software that is required to set up and boot an Amazon EC2 instance.`,`ssm-run-command|Using Run Command, you can remotely and securely manage the configuration of your managed nodes.`]}),t({id:`rebuild-yard-008`,building:`rebuild-yard`,bullets:[`2.2-K7`],d:3,stem:`A company serves an application from an Auto Scaling group behind an Application Load Balancer. For the next release, it wants to build a full second fleet of the new version behind its own load balancer, move users over in steps (for example 10 percent, then 50 percent, then 100 percent) and be able to fall back to the original fleet immediately. The original fleet must stay unchanged during the rollout. Which solution BEST meets these requirements?`,correct:[`Create Amazon Route 53 weighted records that point to both load balancers and raise the weight of the new fleet in steps`,`Weighted records choose how much traffic goes to each fleet, and the original fleet keeps running unchanged for fallback.`],wrong:[[`Create Route 53 failover records with the new fleet as the primary and the original fleet as the secondary`,`Failover sends traffic to the primary while it is healthy, so users cannot be moved in percentage steps.`],[`Update the launch template of the existing group and start an instance refresh so instances are replaced in place`,`An instance refresh replaces the instances in the same group when a configuration change requires it, so the original fleet is not left unchanged for an immediate fallback.`],[`Create Route 53 geolocation records that send users from each country to the new fleet one country at a time`,`Geolocation routing chooses the resources that serve traffic by where users are located, so it cannot move a set share of traffic to the new fleet.`]],slot:3,evidence:[`waf-immutable|Commonly all traffic is switched at once, however you can also use fractions of your traffic to each version to dial up the adoption of the new version using the weighted DNS routing capabilities of Amazon Route 53.`,`route53-weighted|With weighted routing, you can link multiple resources to a single domain name (example.com) or subdomain name (acme.example.com) and choose how much traffic goes to each resource.`,`route53-failover-types|Use an active-passive failover configuration when you want a primary resource or group of resources to be available the majority of the time and you want a secondary resource or group of resources to be on standby in case all the primary resources become unavailable.`,`asg-instance-refresh|This feature can be useful when a configuration change requires you to replace instances or their root volumes, especially if your Auto Scaling group contains a large number of instances.`,`route53-geo|With geolocation routing, you can choose the resources that serve your traffic based on where your users are located, meaning the location that DNS queries come from.`]}),e({id:`rebuild-yard-009`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:3,stem:`A company manages a production environment with AWS CloudFormation. It wants to see which resources an update would add, modify or delete before the update is applied, and it also wants to identify resources that someone changed outside CloudFormation. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a change set for each proposed update and review it before choosing to execute it`,`A change set previews how proposed changes affect running resources, and nothing changes until the change set is executed.`],[`Run drift detection on the stack when auditing the environment`,`Drift detection identifies stack resources that were changed outside of CloudFormation.`]],wrong:[[`Deploy each update with StackSets to one Region first and compare the results with the other Regions`,`StackSets deploys stacks to accounts and Regions and does not preview the changes of an update before it is applied.`],[`Run an AWS Systems Manager Patch Manager scan on the instances of the stack after every update`,`A scan reports patch compliance, not the resources an update changes or resources edited outside CloudFormation.`],[`Start an Auto Scaling instance refresh after every update to confirm that new instances launch`,`It replaces instances and does not list the changes of an update or find resources edited outside CloudFormation.`]],slots:[1,3],evidence:[`cfn-changesets|Change sets allow you to preview how proposed changes to a stack might impact your running resources, including the impact on resource properties and attributes.`,`cfn-changesets|CloudFormation makes the changes to your stack only when you decide to execute the change set, allowing you to decide whether to proceed with your proposed changes or explore other changes by creating another change set.`,`cfn-drift|You can use drift detection to identify stack resources to which configuration changes have been made outside of CloudFormation management.`,`cfn-stacksets|CloudFormation StackSets extends the capability of stacks by allowing you to create, update, or delete stacks across multiple accounts and AWS Regions with a single operation.`]}),e({id:`rebuild-yard-010`,building:`rebuild-yard`,bullets:[`2.2-K7`,`2.2-S1`],d:3,stem:`A company is moving its web tier to immutable infrastructure. Running production instances must not be changed in place, administrators must not rely on inbound SSH ports, and a failed release must be easy to reverse. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Deploy each release as a new set of instances built from a new AMI and keep the previous set available to return to`,`Replacing instead of modifying means the previous working version is not changed, so a rollback is fast.`],[`Close the inbound SSH ports and use AWS Systems Manager Session Manager when an administrator needs a shell`,`Session Manager provides node access without open inbound ports, which fits immutable infrastructure that disables SSH.`]],wrong:[[`Apply each hotfix to the running instances with Systems Manager Run Command at the time of the release`,`Hotfixes on running instances are in-place changes, which immutable infrastructure does not allow.`],[`Schedule Systems Manager Patch Manager to patch the running production instances in place every week`,`Patching running instances modifies them in place, which immutable infrastructure does not allow.`],[`Take hourly Amazon EBS snapshots of the production volumes and restore the latest snapshot after a failed change`,`Changes are still made in place, and recovery means restoring volumes instead of returning to an unchanged version.`]],slots:[0,2],evidence:[`waf-immutable|Safer deployments with fast rollback and recovery processes: Deployments are safer because the previous working version is not changed.`,`waf-immutable|Enhanced security posture: By not allowing changes to infrastructure, remote access mechanisms (such as SSH) can be disabled.`,`ssm-session-manager|Session Manager provides secure node management without the need to open inbound ports, maintain bastion hosts, or manage SSH keys.`]}),t({id:`rebuild-yard-011`,building:`rebuild-yard`,bullets:[`2.2-K7`],d:2,tags:[`mock-reserve`],stem:`A company runs its web application in an AWS Elastic Beanstalk environment. A rolling deployment that fails can leave the environment with instances on both versions. The company wants each deployment to launch a full set of new instances in a separate Auto Scaling group and, if those instances fail health checks, to terminate them and leave the original instances untouched. Which deployment policy meets these requirements?`,correct:[`Immutable`,`An immutable update launches new instances in a separate Auto Scaling group and terminates them if they fail health checks, leaving the original instances untouched.`],wrong:[[`All at once`,`It deploys the new version to the existing instances simultaneously, so there is no separate group and no untouched original set.`],[`Rolling`,`It deploys the new version to the existing instances in batches, so a failure can leave a mix of versions.`],[`Rolling with additional batch`,`It launches an extra batch only to keep full capacity and still deploys the new version in batches to the existing instances.`]],slot:0,evidence:[`eb-deploy-policies|Immutable deployments perform an immutable update to launch a full set of new instances running the new version of the application in a separate Auto Scaling group, alongside the instances running the old version.`,`eb-deploy-policies|If the new instances don't pass health checks, Elastic Beanstalk terminates them, leaving the original instances untouched.`,`eb-deploy-policies|All at once – Deploy the new version to all instances simultaneously.`,`eb-deploy-policies|Rolling – Deploy the new version in batches.`]}),t({id:`rebuild-yard-012`,building:`rebuild-yard`,bullets:[`2.2-S1`],d:3,tags:[`mock-reserve`],stem:`A company runs hundreds of Amazon EC2 instances that must always run an approved monitoring agent with a defined configuration. Administrators sometimes remove or change the agent, and the company wants the defined state reapplied automatically on a schedule, without inbound SSH access and with the LEAST custom code. Which solution meets these requirements?`,correct:[`Create an AWS Systems Manager State Manager association that targets the instances by tag and runs on a schedule`,`State Manager keeps managed nodes in a state that you define, reapplies it on a schedule and reduces configuration drift.`],wrong:[[`Run an AWS Systems Manager Run Command command by hand whenever an audit finds a missing agent`,`Run Command is for one-time configuration changes, so it does not reapply the state on a schedule.`],[`Add a user data script to the launch template that installs the agent`,`A user data script runs at launch, so it does not repair an agent that is removed or changed later on a running instance.`],[`Write an AWS Lambda function that connects to each instance over SSH and checks the agent`,`This is custom code to build and maintain, and connecting over SSH needs inbound SSH ports open, which the company wants to avoid.`]],slot:2,evidence:[`ssm-state-manager|State Manager is a secure and scalable configuration management service that automates the process of keeping your managed nodes and other AWS resources in a state that you define.`,`ssm-state-manager|State Manager is appropriate for any AWS customer that wants to improve the management and governance of their AWS resources and reduce configuration drift.`,`ssm-state-manager|An association specifies a schedule for when to apply the configuration and the targets for the association.`,`ssm-state-manager|After the initial run, the association runs in intervals according to the schedule that you defined.`,`ssm-state-manager|State Manager supports targeting AWS resources by using tags, AWS Resource Groups, individual node IDs, or all managed nodes in the current AWS Region and AWS account.`,`ssm-state-manager|Download and update agents on a defined schedule, including the SSM Agent.`,`ssm-run-command|Using Run Command, you can remotely and securely manage the configuration of your managed nodes.`,`ssm-run-command|With Run Command, you can automate common administrative tasks and perform one-time configuration changes at scale.`,`asg-warm-pools|For simple scenarios where you want to run commands on your instances at launch, you can include a user data script when you create a launch template or launch configuration for your Auto Scaling group.`,`ssm-session-manager|Leaving inbound SSH ports and remote PowerShell ports open on your managed nodes greatly increases the risk of entities running unauthorized or malicious commands on the managed nodes.`]})],p=[t({id:`scaling-floodgate-001`,building:`scaling-floodgate`,bullets:[`2.1-K6`],d:1,stem:`A company runs the stateless web tier of an application on one large Amazon EC2 instance. Traffic keeps growing, and the loss of that instance would take the application offline. The company wants capacity that grows with demand and survives the loss of an instance, with the LEAST manual effort. Which solution BEST meets these requirements?`,correct:[`Place the instances in an Auto Scaling group across two Availability Zones behind an Application Load Balancer`,`Adding instances is horizontal scaling, which suits a stateless tier; the group replaces failed instances and launches capacity in another Availability Zone if one becomes unavailable, with no manual steps.`],wrong:[[`Change the instance to the next larger instance type each time the load grows`,`This is vertical scaling of a single instance, so one failure still takes the application offline and each resize is manual.`],[`Attach an additional Amazon EBS volume to the instance so that it can hold more of the working data`,`Storage does not add compute capacity, and the application would still run on a single instance that is a single point of failure.`],[`Launch a second instance by hand in another Availability Zone and change the DNS record whenever one fails`,`Both the capacity changes and the recovery steps are manual, which conflicts with the LEAST manual effort requirement.`]],slot:0,evidence:[`waf-stateless|In addition to server replacement, another benefit of stateless applications is that they can scale horizontally because any of the available compute resources (such as EC2 instances and AWS Lambda functions) can service any request.`,`asg-benefits|If one Availability Zone becomes unavailable, Amazon EC2 Auto Scaling can launch instances in another one to compensate.`,`asg-what-is|Amazon EC2 Auto Scaling automatically monitors the health and availability of your instances using EC2 health checks and replaces terminated or impaired instances to maintain your desired capacity.`]}),t({id:`scaling-floodgate-002`,building:`scaling-floodgate`,bullets:[`2.1-K6`,`2.1-K15`],d:2,stem:`A company runs an order-processing application on a single Amazon RDS for PostgreSQL DB instance. CPU is saturated by a high volume of INSERT and UPDATE statements, while read traffic is small. The company accepts a short change during a maintenance window. Which action BEST addresses the bottleneck?`,correct:[`Modify the DB instance to use a larger DB instance class`,`Write traffic can only be handled by the primary, so the way to add capacity for writes is to scale vertically by changing the DB instance size.`],wrong:[[`Create an RDS read replica and send the INSERT and UPDATE statements to it`,`A read replica is read-only, so it cannot accept the write statements that are saturating the primary.`],[`Enable a Multi-AZ DB instance deployment so that the standby replica takes a share of the write load`,`The standby replica in a Multi-AZ DB instance deployment exists for high availability and cannot serve traffic, so it does not relieve the primary.`],[`Place an Amazon CloudFront distribution in front of the application to absorb the traffic`,`A CDN caches content for viewers and does not reduce the number of write statements the database must process.`]],slot:1,evidence:[`rds-scaling-ha|With Amazon RDS, you can scale vertically by modifying your DB instance size to meet your performance and capacity requirements.`,`rds-scaling-ha|Read replicas are read-only and can't handle write operations.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`]}),t({id:`scaling-floodgate-003`,building:`scaling-floodgate`,bullets:[`2.1-K6`],d:2,stem:`A company runs a web application on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer. When the group scales in, some users see errors because an instance is removed while it is still completing requests that take up to two minutes. The company wants in-flight requests to finish before an instance is removed, with the LEAST change. Which solution meets these requirements?`,correct:[`Keep a deregistration delay on the target group that is longer than the longest request`,`The load balancer stops sending new requests to a deregistering target and waits for the delay, which lets in-flight requests complete before the instance is terminated.`],wrong:[[`Turn on sticky sessions on the target group so that each user returns to the same instance`,`Stickiness binds a user to one target for routing and does not delay the removal of an instance that is being scaled in.`],[`Turn on slow start mode on the target group so that removed instances are drained gradually`,`Slow start gives newly registered targets a ramp-up period and does not affect targets that are being removed.`],[`Switch the target group to the least outstanding requests routing algorithm`,`The routing algorithm chooses which target receives a new request and does not make the load balancer wait for in-flight requests on a removed target.`]],slot:2,evidence:[`alb-target-attrs|Elastic Load Balancing stops sending requests to targets that are deregistering.`,`alb-target-attrs|By default, Elastic Load Balancing waits 300 seconds before completing the deregistration process, which can help in-flight requests to the target to complete.`,`alb-target-attrs|If the target is part of an Auto Scaling group, it can be terminated and replaced.`]}),t({id:`scaling-floodgate-004`,building:`scaling-floodgate`,bullets:[`2.1-K6`],d:2,tags:[`mock-reserve`],stem:`A company runs a licensed legacy application on one Amazon EC2 instance that has an Amazon EBS root volume. The application keeps its working set in memory, cannot run on more than one server, and is now memory-bound. The company wants to fix this with the LEAST change to the architecture. Which solution meets these requirements?`,correct:[`Change the instance type of the existing instance to a larger, memory-optimized type`,`Resizing by changing the instance type adds memory to the same instance, which suits an application that cannot be spread across several servers.`],wrong:[[`Place the instance in an Auto Scaling group behind an Application Load Balancer`,`This is horizontal scaling and needs the application to run on several servers, which it cannot do.`],[`Add another Amazon EBS volume to the instance so that more data can be held`,`An extra volume adds storage and does not add the memory the application is short of.`],[`Put an Application Load Balancer in front of the instance so that the memory use is spread across requests`,`A load balancer distributes requests across several targets and cannot add memory to the single instance behind it.`]],slot:3,evidence:[`ec2-resize|If this is the case, you can resize your instance by changing its instance type.`,`ec2-resize|To add additional storage to your instance without changing the instance type, add an EBS volume to the instance.`]}),e({id:`scaling-floodgate-005`,building:`scaling-floodgate`,bullets:[`2.1-K6`,`2.1-K15`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`The web tier of a company application runs on stateless Amazon EC2 instances. At peak the web tier is CPU-bound, and an Amazon RDS for MySQL DB instance is saturated by product-catalogue read queries, while writes are modest. The company wants each tier to scale with the LEAST application redesign. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Place the web instances in an Auto Scaling group behind an Application Load Balancer`,`A stateless tier scales horizontally, and the load balancer spreads requests across the instances as the group adds and removes them.`],[`Create RDS read replicas and direct the catalogue queries to them`,`Read replicas offload read-intensive work from the primary, and the application only has to point its read-only queries at the replicas.`]],wrong:[[`Enable a Multi-AZ DB instance deployment so that the standby replica answers the catalogue queries`,`The standby replica in a Multi-AZ DB instance deployment cannot serve read traffic, so it does not relieve the read load.`],[`Replace the web tier with a single instance of the largest available instance type`,`This is vertical scaling of one server, which adds power to a single instance instead of adding instances to the web tier.`],[`Move the web tier to AWS Lambda functions and keep the single database unchanged`,`The catalogue read queries would still all run on the one saturated DB instance, so the database tier does not scale, and the web tier is redesigned.`]],slots:[1,3],evidence:[`asg-what-is|You can use Elastic Load Balancing load balancing and health checks to ensure an even distribution of application traffic to your healthy instances.`,`rds-scaling-ha|Amazon RDS provides horizontal scaling by using read replicas to offload read-intensive workloads and improve database performance.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`,`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`,`compute-decision|The scalability of a service can be vertical, allowing you to scale up by adding more power to your existing infrastructure (like increasing the CPU or memory of an instance), or horizontal, helping you to scale out by adding more instances to handle the load.`]}),t({id:`scaling-floodgate-006`,building:`scaling-floodgate`,bullets:[`2.1-K9`],d:1,stem:`A company runs a web application on three Amazon EC2 instances in two Availability Zones. Clients must use one entry point, requests must be spread across the instances, and no request may be sent to an instance that has failed. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an Application Load Balancer, register the instances in a target group, and configure health checks`,`The load balancer is the single point of contact, spreads requests across targets in several Availability Zones, and routes only to targets that pass health checks.`],wrong:[[`Run reverse proxy software on a separate instance that forwards each request to one of the three instances`,`The proxy is one more instance to patch, scale and keep available, and it becomes a single point of failure.`],[`Associate an Elastic IP address with the least busy instance and move it by hand when load shifts`,`Moving the address is manual work, and all clients would still reach one instance at a time instead of being spread.`],[`Publish the private IP address of every instance to clients and have each client retry on failure`,`Clients would have to track instance addresses and handle failures themselves, which adds overhead and does not give one entry point.`]],slot:0,evidence:[`elb-what-is|It monitors the health of its registered targets, and routes traffic only to the healthy targets.`,`elb-what-is|Using a load balancer increases the availability and fault tolerance of your applications.`,`alb-intro|A load balancer serves as the single point of contact for clients.`]}),t({id:`scaling-floodgate-007`,building:`scaling-floodgate`,bullets:[`2.1-K9`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`An online store runs as separate services on Amazon EC2 instances: product pages under /products/* and shopping carts under /cart/*, each in its own target group. All traffic is HTTPS on one domain name. The company wants one load balancer that sends each request to the correct service based on the URL path, with the LEAST operational overhead. Which load balancer should the company use?`,correct:[`An Application Load Balancer with listener rules that use path conditions`,`An Application Load Balancer works at the application layer and can forward requests to different target groups based on the URL in the request.`],wrong:[[`A Network Load Balancer with a TLS listener and one target group per service`,`A Network Load Balancer works at the fourth layer and does not route on the URL path of an HTTP request.`],[`A Gateway Load Balancer placed in front of both target groups`,`A Gateway Load Balancer is for deploying and scaling virtual appliances such as firewalls and not for routing web requests to services.`],[`A Classic Load Balancer with one listener for each service`,`A Classic Load Balancer lacks the path-condition routing that lets an Application Load Balancer split services by URL.`]],slot:1,evidence:[`alb-intro|Support for Path conditions. You can configure rules for your listener that forward requests based on the URL in the request.`,`nlb-intro|A Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`]}),t({id:`scaling-floodgate-008`,building:`scaling-floodgate`,bullets:[`2.1-K9`,`2.1-S2`],d:2,tags:[`mock-reserve`],stem:`A web application runs in an Auto Scaling group behind an Application Load Balancer. Occasionally the application process on an instance stops responding although the instance still passes its EC2 status checks, so the load balancer marks it unhealthy but the instance stays in the group. The company wants such instances replaced automatically with the LEAST custom code. Which solution meets these requirements?`,correct:[`Turn on Elastic Load Balancing health checks for the Auto Scaling group`,`With these checks on, the group replaces a running instance when an attached load balancer reports it as unhealthy, so no extra code is needed.`],wrong:[[`Increase the minimum size of the group so that healthy instances absorb the traffic`,`Extra capacity does not remove the unhealthy instance, which would stay registered in the group.`],[`Create an Amazon CloudWatch alarm on CPU utilization that invokes an AWS Lambda function to terminate the instance`,`This needs custom code, and CPU utilization is not a reliable signal that the application stopped responding.`],[`Enable detailed monitoring on the instances so that the group can see application failures`,`Detailed monitoring publishes metrics at a finer interval and does not make the group act on load balancer health.`]],slot:2,evidence:[`asg-attach-lb|By default, Amazon EC2 Auto Scaling only replaces instances that are unhealthy or unreachable based on Amazon EC2 health checks.`,`asg-attach-lb|If you turn on Elastic Load Balancing health checks, Amazon EC2 Auto Scaling can replace a running instance if any of the Elastic Load Balancing load balancers you attach to the Auto Scaling group report it as unhealthy.`]}),t({id:`scaling-floodgate-009`,building:`scaling-floodgate`,bullets:[`2.1-K9`],d:3,tags:[`trap:alb-nlb-gwlb`],stem:`A company runs a TCP-based service behind a Network Load Balancer with both Availability Zones enabled. Two instances are registered in Availability Zone A and eight in Availability Zone B. Each load balancer node receives half of the client traffic, so the instances in Availability Zone A are overloaded while those in Availability Zone B are mostly idle. The company wants requests spread evenly across all ten instances without changing how many instances run in each Availability Zone. Which solution meets these requirements with the LEAST change?`,correct:[`Turn on cross-zone load balancing for the Network Load Balancer`,`With cross-zone load balancing enabled, each node distributes traffic across the registered targets in all enabled Availability Zones, so every instance gets an equal share.`],wrong:[[`Replace the Network Load Balancer with an Application Load Balancer`,`The service uses TCP rather than HTTP, so an Application Load Balancer does not fit, and the replacement is a larger change.`],[`Add two more instances in Availability Zone A and leave the load balancer settings as they are`,`This changes how many instances run in each Availability Zone, which the company wants to avoid, and does not change how nodes share traffic.`],[`Increase the deregistration delay on the target group so that overloaded instances drain slowly`,`The deregistration delay applies to targets being removed and has no effect on how traffic is shared among healthy targets.`]],slot:3,evidence:[`elb-how-it-works|When cross-zone load balancing is enabled, each load balancer node distributes traffic across the registered targets in all enabled Availability Zones.`,`elb-how-it-works|With Network Load Balancers and Gateway Load Balancers, cross-zone load balancing is disabled by default.`,`alb-target-attrs|Elastic Load Balancing stops sending requests to targets that are deregistering.`]}),e({id:`scaling-floodgate-010`,building:`scaling-floodgate`,bullets:[`2.1-K9`,`2.1-S2`],d:3,stem:`A web application runs in an Auto Scaling group behind an Application Load Balancer with a target tracking policy. New instances take several minutes to warm their caches. During scale-out, each new instance immediately receives a full share of requests and responds slowly, and the group then scales out again because the new instances report unrepresentative metrics. Which TWO actions address these problems with the LEAST operational overhead? (Choose two.)`,correct:[[`Enable slow start mode on the target group`,`Slow start gives new targets time to warm up by increasing the requests they receive gradually instead of sending a full share at once.`],[`Set an instance warmup time for the target tracking scaling policy`,`A warming instance is not counted in the aggregated metrics of the group, so unrepresentative values do not trigger further scale-out.`]],wrong:[[`Switch the target group to the least outstanding requests routing algorithm`,`Slow start cannot be enabled with the least outstanding requests algorithm, so this blocks the fix for the overloaded new instances.`],[`Increase the deregistration delay on the target group`,`The delay applies when targets are removed and has no effect on how new instances are warmed up.`],[`Turn on sticky sessions so that users stay on the instances that are already warm`,`Stickiness binds a session to a target and does not limit how many new requests a freshly registered instance receives or what its metrics report.`]],slots:[0,2],evidence:[`alb-target-attrs|Using slow start mode gives targets time to warm up before the load balancer sends them a full share of requests.`,`alb-target-attrs|You can't enable slow start mode when using the least outstanding requests or weighted random routing algorithms.`,`asg-target-tracking|Until its specified warmup time has expired, an instance is not counted toward the aggregated EC2 instance metrics of the Auto Scaling group.`]}),t({id:`scaling-floodgate-011`,building:`scaling-floodgate`,bullets:[`2.1-K15`],d:1,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company's Amazon RDS for MySQL production database slows down every morning when analysts run long reporting queries. The analysts only read data and can accept results that are slightly out of date. The company wants to keep the reports from affecting production with the LEAST disruption. Which solution meets these requirements?`,correct:[`Create a read replica and point the reporting queries at it`,`A read replica is a read-only copy that exists for scaling reads and business reporting, so the reports no longer compete with production work.`],wrong:[[`Enable a Multi-AZ DB instance deployment and point the reporting queries at the standby replica`,`The standby replica in a Multi-AZ DB instance deployment cannot serve read traffic, so it cannot run the reports.`],[`Restore a snapshot of the database into a new DB instance every morning for the analysts`,`This adds daily manual or scripted work, and the copy is already hours old when the analysts begin.`],[`Move the DB instance to a larger DB instance class so both workloads fit on the same server`,`The reports still run on the production instance, so they continue to compete with production traffic.`]],slot:0,evidence:[`rds-read-replicas|Business reporting or data warehousing scenarios where you might want business reporting queries to run against a read replica, rather than your production DB instance.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`]}),t({id:`scaling-floodgate-012`,building:`scaling-floodgate`,bullets:[`2.1-K15`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`A retailer runs an Amazon RDS for PostgreSQL primary DB instance that is overloaded by read traffic, most of it product browsing. After a customer places an order, the confirmation page must show that order immediately. The company wants to offload reads while making sure the confirmation page never misses a just-written order. Which design BEST meets these requirements?`,correct:[`Create read replicas for the product browsing queries and read the confirmation page from the primary instance`,`Replicas are updated asynchronously and can lag, so only the lag-tolerant browsing reads go to them while the order read goes to the primary.`],wrong:[[`Send every read, including the confirmation page, to the read replicas because replication to them is synchronous`,`Updates are copied to a read replica asynchronously, so a just-written order may not be there yet.`],[`Enable a Multi-AZ DB instance deployment and read the confirmation page from the standby replica`,`The standby replica in a Multi-AZ DB instance deployment cannot serve read traffic, so the confirmation page could not be read from it.`],[`Create read replicas and send the order writes to them so the confirmation page finds the order on the same node`,`Read replicas allow only read-only access, so the order writes would be rejected.`]],slot:1,evidence:[`rds-read-replicas|When you make updates to the primary DB instance, Amazon RDS copies them asynchronously to the read replica.`,`rds-scaling-ha|Replicas might introduce minor latency due to asynchronous replication.`,`rds-read-replicas|Clients have read/write access to the primary DB instance and read-only access to the replica.`]}),t({id:`scaling-floodgate-013`,building:`scaling-floodgate`,bullets:[`2.1-K15`],d:2,tags:[`trap:aurora-vs-rds`],stem:`A company runs Amazon RDS for MySQL with a few read replicas. Read traffic rises sharply during promotions and falls afterwards. The company wants the number of read replicas to follow demand automatically without paying for idle replicas, and is willing to change database engine. Which solution BEST meets these requirements with the LEAST operational overhead?`,correct:[`Migrate to Amazon Aurora MySQL and apply an Aurora Auto Scaling policy to the Aurora Replicas`,`Aurora Auto Scaling adds and removes Aurora Replicas as the workload changes, which RDS read replicas cannot do automatically.`],wrong:[[`Use an RDS Multi-AZ DB instance deployment so that the standby replica absorbs the extra read traffic`,`The standby replica in a Multi-AZ DB instance deployment cannot serve read traffic, and RDS read replicas are not autoscaled, so read capacity would not follow demand.`],[`Create enough RDS read replicas to cover the largest promotion and keep them running`,`Replicas that run permanently are billed as standard DB instances, so this pays for idle capacity between promotions.`],[`Write a scheduled AWS Lambda function that creates and deletes read replicas around promotions`,`This is custom code to build and maintain, and a schedule cannot follow unplanned changes in read demand.`]],slot:2,evidence:[`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`,`aurora-autoscaling|To meet your connectivity and workload requirements, Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas (reader DB instances) provisioned for an Aurora DB cluster.`,`rds-read-replicas|Read replicas are billed as standard DB instances at the same rates as the DB instance class used for the replica.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`]}),t({id:`scaling-floodgate-014`,building:`scaling-floodgate`,bullets:[`2.1-K15`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs a business-critical Amazon RDS for PostgreSQL DB instance in one AWS Region. To prepare for a Regional outage, the company wants a copy of the database in a second Region that can be promoted to a standalone instance if the primary fails. The company wants the LEAST operational effort. Which solution meets these requirements?`,correct:[`Create a cross-Region read replica in the second Region`,`A read replica can reside in a different Region and can be promoted to a standalone instance as a disaster recovery solution.`],wrong:[[`Enable Multi-AZ on the DB instance`,`A Multi-AZ standby replica is maintained in a different Availability Zone, not in a second Region, so it does not protect against a Regional outage.`],[`Create a read replica in another Availability Zone of the same Region`,`The replica stays in the same Region, so a Regional outage would affect both the primary and the replica.`],[`Export the data every night with a script and import it into a new DB instance in the second Region`,`The nightly scripts are extra operational work, and the copy is up to a day behind.`]],slot:3,evidence:[`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`rds-read-replicas|You can promote a read replica to a standalone instance as a disaster recovery solution if the primary DB instance fails.`,`rds-scaling-ha|Multi-AZ deployments provide high availability and durability by automatically maintaining a synchronous standby replica in a different Availability Zone.`]}),e({id:`scaling-floodgate-015`,building:`scaling-floodgate`,bullets:[`2.1-K15`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs a single-Availability-Zone Amazon RDS for MySQL production DB instance. Read traffic is growing, and the company also wants the database to fail over automatically to another Availability Zone if the primary instance fails. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create read replicas and route the read-only queries to them`,`Read replicas scale out reads beyond the capacity of a single DB instance.`],[`Enable a Multi-AZ DB instance deployment so that a standby replica is maintained in another Availability Zone`,`A Multi-AZ DB instance deployment automatically fails over to the standby replica when the primary has a problem, which meets the failover requirement.`]],wrong:[[`Send the read queries to the standby replica of a Multi-AZ DB instance deployment to scale reads`,`The standby replica in a Multi-AZ DB instance deployment is there for high availability and cannot serve read traffic.`],[`Increase the allocated storage of the DB instance so that it can serve more read requests`,`More allocated storage does not add read capacity and does not provide failover to another Availability Zone.`],[`Take hourly snapshots and restore the latest one to a new DB instance after a failure`,`A restore is a manual recovery and not an automatic failover, and it does not add read capacity.`]],slots:[0,4],evidence:[`rds-read-replicas|In this way, you can elastically scale out beyond the capacity constraints of a single DB instance for read-heavy database workloads.`,`rds-scaling-ha|Multi-AZ deployments minimize downtime during planned maintenance or infrastructure failure by automatically failing over to the standby replica.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`]}),t({id:`scaling-floodgate-016`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:1,stem:`A company runs a web application in an Amazon EC2 Auto Scaling group. Load varies unpredictably during the day. The company wants average CPU utilization to stay near 50 percent, with instances added and removed automatically and the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create a target tracking scaling policy with a target of 50 percent average CPU utilization`,`Target tracking keeps a metric near a chosen target value, and the group scales out above the target and scales in below it.`],wrong:[[`Create step scaling policies together with the CloudWatch alarms that invoke them`,`With step scaling you create and manage the alarms and the step adjustments yourself, which is more overhead than a target.`],[`Create scheduled actions that change the desired capacity at fixed hours of the day`,`The load is unpredictable, so a fixed schedule cannot follow the actual CPU utilization.`],[`Set the minimum and desired capacity of the group to the size needed at the busiest moment of the day`,`This keeps peak capacity running all day, so CPU utilization stays far below the target and capacity is wasted.`]],slot:0,evidence:[`asg-target-tracking|You can meet this need by creating a target tracking scaling policy that targets an average CPU utilization of 50 percent.`,`asg-target-tracking|With target tracking, you select a metric and a target value to represent the ideal average utilization or throughput level for your application.`,`asg-step|With step scaling and simple scaling, you create and manage the CloudWatch alarms that invoke the scaling process.`]}),t({id:`scaling-floodgate-017`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:2,stem:`An online retailer will run a flash sale that starts at a known time next Friday. Earlier sales needed far more capacity than a normal day, so the company wants 40 instances ready when the sale starts and wants to return to normal capacity afterwards. The company wants the lowest cost and effort. Which solution BEST meets these requirements?`,correct:[`Create scheduled actions that raise the desired capacity before the sale and lower it afterwards`,`Scheduled scaling changes desired capacity at specific times, and it can run once, so the capacity is ready before the sale and removed after it.`],wrong:[[`Create a target tracking policy on average CPU utilization and rely on it to react once the sale starts`,`A tracking policy is reactive, so instances arrive only after the load has already built up.`],[`Set the minimum size of the group to 40 permanently`,`This keeps sale-level capacity running every day, which wastes cost outside the sale.`],[`Enable predictive scaling so that the group learns the sale pattern`,`Predictive scaling forecasts from daily or weekly patterns in historical data, and a single sale does not form such a pattern.`]],slot:1,evidence:[`asg-scheduled|You can create scheduled actions that scale one time only or that scale on a recurring schedule.`,`asg-scheduled|You create scheduled actions that increase or decrease your group's desired capacity at specific times.`,`asg-predictive|Predictive scaling works by analyzing historical load data to detect daily or weekly patterns in traffic flows.`]}),t({id:`scaling-floodgate-018`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:2,stem:`An application runs in an Amazon EC2 Auto Scaling group. Traffic follows a consistent daily cycle, high during business hours and low overnight. Each new instance takes about ten minutes to initialize, and users notice slow responses at the start of each business day while the group scales out. The company wants capacity ready before the load arrives, without hand-written schedules. Which solution BEST meets these requirements?`,correct:[`Configure a predictive scaling policy for the group`,`Predictive scaling forecasts capacity from historical daily patterns and launches instances in advance, which helps applications that take a long time to initialize.`],wrong:[[`Configure a target tracking policy on average CPU utilization only`,`A tracking policy reacts after utilization rises, so slow-to-initialize instances still arrive late.`],[`Write recurring scheduled actions that raise the desired capacity before each business day`,`This works but requires reviewing the load pattern and maintaining schedules by hand, which the company wants to avoid.`],[`Configure a step scaling policy with a lower alarm threshold so that it reacts earlier`,`Step scaling is still dynamic and reactive, and a lower threshold wastes capacity without having instances ready in advance.`]],slot:2,evidence:[`asg-predictive|Predictive scaling is well suited for situations where you have: Cyclical traffic, such as high use of resources during regular business hours and low use of resources during evenings and weekends`,`asg-predictive|Predictive scaling can help you scale faster by launching capacity in advance of forecasted load, compared to using only dynamic scaling, which is reactive in nature.`,`asg-predictive|You also don't have to spend time reviewing your application's load patterns and trying to schedule the right amount of capacity using scheduled scaling.`]}),t({id:`scaling-floodgate-019`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:3,stem:`A video-processing application runs worker instances in an Auto Scaling group that read jobs from an Amazon SQS queue. The jobs spend most of their time waiting on a remote service, so CPU utilization stays low even when the queue is long. The company wants the group to scale so that each instance has a steady number of waiting jobs. Which solution BEST meets these requirements?`,correct:[`Publish a backlog-per-instance custom metric to Amazon CloudWatch and create a target tracking policy on it`,`The number of messages per instance changes in proportion to group size, so it works as a target tracking metric once it is published as a custom metric.`],wrong:[[`Create a target tracking policy directly on the ApproximateNumberOfMessagesVisible queue metric`,`The queue length does not change in proportion to the size of the group that processes it, so it is not suitable for target tracking.`],[`Create a target tracking policy on average CPU utilization of the group with a target of 50 percent`,`The jobs wait on a remote service, so CPU stays low whatever the queue length and the group would not scale on the backlog.`],[`Create a target tracking policy on the ALBRequestCountPerTarget metric of the load balancer`,`The workers pull jobs from a queue and are not behind a load balancer, so this metric does not describe their load.`]],slot:3,evidence:[`asg-sqs|To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`,`asg-sqs|A policy that targets only the number of messages in the queue does not account for the number of instances available.`,`asg-sqs|If you use a target tracking scaling policy based on a custom Amazon SQS queue metric, dynamic scaling can adjust to the demand curve of your application more effectively.`]}),t({id:`scaling-floodgate-020`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:3,stem:`A payroll application needs at least 20 instances between 08:00 and 09:00 on each weekday, when employees submit timesheets. Demand above that baseline is unpredictable, and outside that hour the group should run only a few instances. The company wants acceptable response times without over-provisioning. Which solution BEST meets these requirements?`,correct:[`Create recurring scheduled actions that raise the minimum capacity for that hour, plus a target tracking policy`,`The schedule has the baseline ready before 08:00 and the policy keeps adding capacity above it when demand exceeds the baseline.`],wrong:[[`Use only a target tracking policy with a low minimum capacity`,`The policy reacts only after the load arrives, so the baseline of 20 instances would not be ready when the hour begins.`],[`Use only scheduled actions that set the capacity to the expected peak for that hour and never change it`,`Demand above the baseline is unpredictable, and a fixed schedule cannot add capacity beyond what was planned.`],[`Keep the minimum capacity at 20 instances all day and add a target tracking policy for the extra load`,`The group would run 20 instances outside the busy hour, which is the over-provisioning the company wants to avoid.`]],slot:0,evidence:[`asg-scheduled|You can use scheduled scaling and scaling policies together to get the benefits of both approaches to scaling.`,`asg-scheduled|After a scheduled scaling action runs, the scaling policy can continue to make decisions about whether to further scale capacity.`,`asg-scheduled|While your application scales to match demand, current capacity must fall within the minimum and maximum capacity that was set by your scheduled action.`]}),t({id:`scaling-floodgate-021`,building:`scaling-floodgate`,bullets:[`2.1-S2`,`2.1-K9`],d:2,tags:[`mock-reserve`],stem:`An API runs on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer. Each instance performs best at about 1,000 requests per minute. The company wants the group to add instances when the average number of requests per instance rises above that level, and to remove them when it falls. Which scaling policy configuration should the company use?`,correct:[`A target tracking policy that uses the ALBRequestCountPerTarget metric with a target value of 1,000`,`This predefined metric is the average request count per target of the group, and the target value is the throughput that one instance handles in a minute.`],wrong:[[`A target tracking policy that uses the load balancer RequestCount metric`,`The total request count does not change when the group scales, so it cannot guide a policy about requests per instance.`],[`A target tracking policy that uses the load balancer Latency metric`,`Latency can rise with utilization but does not change in proportion to the number of instances, so it does not work for target tracking.`],[`A target tracking policy that uses the ASGAverageNetworkOut metric`,`Outbound network traffic is not the requests-per-instance figure the company wants to hold near a target.`]],slot:1,evidence:[`asg-target-tracking|ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`,`asg-target-tracking|The number of requests received by the load balancer doesn't change based on the utilization of the Auto Scaling group.`,`asg-target-tracking|Request latency can increase based on increasing utilization, but doesn't necessarily change proportionally.`]}),e({id:`scaling-floodgate-022`,building:`scaling-floodgate`,bullets:[`2.1-S2`],d:2,stem:`A company runs a fault-tolerant batch-processing tier in an Amazon EC2 Auto Scaling group. Demand peaks for a few hours each day. The company wants to keep the capacity it needs at peak while paying the LOWEST compute cost. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use a scaling policy that removes capacity when demand is lower`,`Scaling in during quiet periods means the company pays only for the instances that the load requires.`],[`Configure the group to launch both Spot Instances and On-Demand Instances`,`A single group can combine purchase options, so Spot Instance usage lowers the cost of the capacity the group needs.`]],wrong:[[`Set the minimum and maximum sizes of the group to the peak size`,`The group would always run the peak number of instances, so no capacity is removed when demand is lower.`],[`Turn off the scale-in part of the scaling policy so that instances are never removed`,`Without scale-in the group keeps its largest size after each peak and the cost does not fall.`],[`Replace the group with one very large instance that always runs`,`A single always-on instance sized for the peak is paid for all day and removes the fault tolerance of a group.`]],slots:[2,3],evidence:[`asg-what-is|Using auto scaling allows you to maintain application availability and reduce costs by adding capacity to handle peak loads and removing capacity when demand is lower.`,`asg-what-is|Within a single Auto Scaling group, you can launch multiple instance types and purchase options (Spot and On-Demand Instances), allowing you to optimize costs through Spot Instance usage.`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`]})],m=[t({id:`serverless-mill-001`,building:`serverless-mill`,bullets:[`2.1-K1`],d:1,stem:`A company is adding a live chat feature to its web application. The browser and the server must both be able to send messages at any time over one persistent connection, and the company wants a fully managed API front end. Which Amazon API Gateway API type BEST meets these requirements?`,correct:[`A WebSocket API that keeps a stateful, full-duplex connection between each client and the server`,`WebSocket APIs follow the WebSocket protocol, which enables stateful, full-duplex communication, so either side can send a message at any time.`],wrong:[[`An HTTP API that the browser polls every second to check whether new chat messages have arrived`,`HTTP APIs are stateless request and response APIs, so the server cannot push messages over a persistent connection.`],[`A REST API with an edge-optimized endpoint that returns the new chat messages on each request`,`REST APIs are stateless, and an edge-optimized endpoint changes where requests enter the network, not how client and server communicate.`],[`A private REST API that the clients reach through an interface VPC endpoint inside the VPC`,`A private endpoint is reachable only from a VPC, and a REST API is stateless, so it gives no persistent two-way connection.`]],slot:0,evidence:[`apigw-welcome|Adhere to the WebSocket protocol, which enables stateful, full-duplex communication between client and server.`,`apigw-welcome|Support for stateful (WebSocket) and stateless (HTTP and REST) APIs.`]}),t({id:`serverless-mill-002`,building:`serverless-mill`,bullets:[`2.1-K1`],d:2,tags:[`placement-eligible`],stem:`A company exposes a public API through Amazon API Gateway that invokes AWS Lambda functions. The security team requires an AWS WAF web ACL that blocks SQL injection attempts and limits the request rate of each client IP address before requests reach the backend. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create the API as a REST API and associate a web ACL with a SQL injection rule and a rate-based rule with the API stage`,`REST APIs integrate with AWS WAF, and a web ACL can block SQL injection and apply rate-based rules for each client IP address.`],wrong:[[`Create the API as an HTTP API and associate a web ACL with a SQL injection rule and a rate-based rule with its stage`,`HTTP APIs do not support AWS WAF integration, so the web ACL cannot be associated with the API.`],[`Create the API as an HTTP API and add a Lambda authorizer that scans request bodies for SQL syntax and counts requests per IP address`,`This needs custom code to build and maintain, instead of the managed rules and low operational overhead that the company wants.`],[`Create the API as a REST API and require API keys with a usage plan that sets a throttle for each customer`,`Usage plans throttle per API key and are not meant to block access, and they do nothing to detect SQL injection.`]],slot:1,evidence:[`apigw-http-vs-rest|Choose REST APIs if you need features such as API keys, per-client throttling, request validation, AWS WAF integration, or private API endpoints.`,`apigw-http-vs-rest|Security features REST API HTTP API Mutual TLS authentication Yes Yes Certificates for backend authentication Yes No AWS WAF Yes No`,`apigw-waf|You can use AWS WAF to protect your API Gateway REST API from common web exploits, such as SQL injection and cross-site scripting (XSS) attacks.`,`apigw-waf|For example, you can use rate-based rules to specify the number of web requests that are allowed by each client IP in a trailing, continuously updated, 5-minute period.`]}),t({id:`serverless-mill-003`,building:`serverless-mill`,bullets:[`2.1-K12`],d:1,stem:`A company runs an AWS Lambda function that resizes images. The function completes successfully, but it is CPU-bound and runs too slowly. The team wants to give the function more CPU power with the LEAST change to the application. What should the team do?`,correct:[`Increase the memory setting of the function`,`Lambda allocates CPU power in proportion to the configured memory, so more memory gives a CPU-bound function more CPU.`],wrong:[[`Increase the reserved concurrency of the function`,`Reserved concurrency controls how many invocations can run at the same time and does not change the CPU that each invocation gets.`],[`Increase the timeout of the function to 900 seconds`,`A longer timeout lets one run last longer, but it does not make the code run faster.`],[`Configure provisioned concurrency for the function`,`Provisioned concurrency pre-initializes execution environments to reduce cold starts and does not add CPU power to an invocation.`]],slot:2,evidence:[`lambda-memory|Lambda allocates CPU power in proportion to the amount of memory configured.`,`lambda-memory|If a function is CPU, network or memory-bound, then increasing the memory setting can dramatically improve its performance.`]}),t({id:`serverless-mill-004`,building:`serverless-mill`,bullets:[`2.1-S5`],d:1,stem:`A company wants to create a thumbnail every time a user uploads an image to an Amazon S3 bucket. Uploads are infrequent and arrive at unpredictable times, and the company does not want to provision or manage servers. Which solution is the MOST cost-effective?`,correct:[`Configure the bucket to invoke an AWS Lambda function that creates the thumbnail on each upload`,`Lambda runs code in response to events such as S3 uploads with no servers to manage, and serverless billing follows the value delivered.`],wrong:[[`Run an Amazon EC2 instance that lists the bucket every minute and creates thumbnails for new objects`,`The instance runs and bills all the time and must be provisioned, patched and scaled, which the company wants to avoid.`],[`Run an Amazon ECS service on Amazon EC2 container instances that watches the bucket continuously`,`The company would manage the container instances and pay for idle capacity between infrequent uploads.`],[`Run an Amazon ECS service on AWS Fargate with one task that polls the bucket all day long`,`There are no servers to manage, but the task runs and bills continuously and idles between uploads, which costs more than running code only on events.`]],slot:3,evidence:[`lambda-welcome|You write a handler function, connect it to a trigger (API Gateway, Amazon S3, Amazon SQS, EventBridge, and 200+ other AWS services), and Lambda executes it.`,`msa-whitepaper|Serverless is characterized by the following principles: No infrastructure to provision or manage Automatically scaling by unit of consumption "Pay for value" billing model Built-in availability and fault tolerance Event Driven Architecture (EDA)`]}),t({id:`serverless-mill-005`,building:`serverless-mill`,bullets:[`2.1-K1`],d:2,tags:[`placement-eligible`],stem:`A software company sells access to a public API that runs on Amazon API Gateway and AWS Lambda. Premium customers must be allowed a higher request rate than free customers, and every customer must have a monthly request quota. The company wants to identify customers by a key and enforce these limits with the LEAST custom code. Which solution meets these requirements?`,correct:[`Create a REST API, issue an API key to each customer, and attach the keys to usage plans that define throttling limits and quotas`,`A usage plan uses API keys to identify clients and sets a throttle and a quota for them, and REST APIs support API keys and per-client throttling.`],wrong:[[`Create an HTTP API and keep a request counter for every customer in an Amazon DynamoDB table that the function updates`,`HTTP APIs have no API keys or per-client throttling, so all of the limit logic would be custom code.`],[`Raise the account-level throttling limit for the Region and rely on it to give premium customers a higher rate`,`The account-level limit applies to all APIs in the account, so it cannot give one customer a different rate than another.`],[`Set a different reserved concurrency value on the Lambda function for each customer tier`,`Reserved concurrency applies to one function as a whole, so it cannot identify customers or enforce monthly quotas.`]],slot:0,evidence:[`apigw-usage-plans|A usage plan specifies who can access one or more deployed API stages and methods`,`apigw-usage-plans|The plan uses API keys to identify API clients and who can access the associated API stages for each key.`,`apigw-http-vs-rest|Features REST API HTTP API Custom domains Yes Yes API keys Yes No Per-client rate limiting Yes No Per-client usage throttling Yes No`,`apigw-throttling|Per-account limits are applied to all APIs in an account in a specified Region.`,`apigw-usage-plans|A quota limit sets the target maximum number of requests with a given API key that can be submitted within a specified time interval.`]}),t({id:`serverless-mill-006`,building:`serverless-mill`,bullets:[`2.1-K12`],d:2,tags:[`placement-eligible`],stem:`A company runs many AWS Lambda functions in one Region. A nightly bulk-import function scales out and uses so much of the account concurrency that the checkout function behind Amazon API Gateway is throttled. The company must guarantee that the checkout function always has capacity to run. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Configure reserved concurrency for the checkout function`,`Reserved concurrency reserves the specified capacity exclusively for the function, so the import function cannot use it.`],wrong:[[`Configure provisioned concurrency for the bulk-import function so that its environments start faster`,`Provisioned concurrency pre-initializes environments to cut cold starts and does not stop the import function from consuming account concurrency.`],[`Request an increase of the account concurrency quota and make no other change to the functions`,`A larger shared pool guarantees nothing, because the import function can still use the capacity that the checkout function needs.`],[`Enable caching on the API Gateway stage that fronts the checkout function to reduce the load`,`Caching applies to GET methods by default and does not reserve Lambda concurrency for the checkout requests.`]],slot:1,evidence:[`lambda-reserved|Reserved concurrency is useful for ensuring that your most critical functions always have enough concurrency to handle incoming requests.`,`lambda-reserved|When an Event Function has reserved concurrency, no other Event Function can use that concurrency.`,`lambda-concurrency|By default, Lambda provides your account with a total concurrency limit of 1,000 concurrent executions across all Event Functions in an AWS Region.`]}),t({id:`serverless-mill-007`,building:`serverless-mill`,bullets:[`2.1-K12`],d:2,stem:`A company serves a latency-sensitive customer API through Amazon API Gateway and an AWS Lambda function. At the start of each daily sales event the first requests are slow, because new execution environments must initialize. The company needs consistently low response times during the event. Which solution meets this requirement with the LEAST change to the code?`,correct:[`Configure provisioned concurrency on an alias of the function`,`Provisioned concurrency keeps pre-initialized execution environments ready to respond immediately, which removes cold-start delays for interactive APIs.`],wrong:[[`Configure reserved concurrency on the function and set it to the expected peak number of requests`,`Reserved concurrency guarantees and caps capacity but does not pre-initialize execution environments, so cold starts continue.`],[`Convert the REST API in Amazon API Gateway to an HTTP API for the sales event`,`The API type decides features and price, not the time that Lambda needs to initialize a new execution environment.`],[`Increase the timeout of the function to the maximum number of seconds that Lambda allows`,`The timeout limits how long one invocation may run and has no effect on how long a new environment takes to initialize.`]],slot:2,evidence:[`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`,`lambda-provisioned|These execution environments are ready to respond immediately to incoming function requests.`,`lambda-provisioned|Generally, interactive workloads benefit the most from the feature.`,`lambda-reserved|Reserved concurrency acts as both a lower and upper bound - it reserves the specified capacity exclusively for your function while also preventing it from scaling beyond that limit.`]}),t({id:`serverless-mill-008`,building:`serverless-mill`,bullets:[`2.1-S5`,`2.1-K12`],d:3,tags:[`placement-eligible`],stem:`A company has a media-processing step packaged as a container image. Each upload starts one run that processes a single file in one process for about two hours, and the work cannot be split into smaller steps. Runs are infrequent, and the company does not want to manage servers or clusters of instances. Which solution is the MOST cost-effective?`,correct:[`Run the image as an Amazon ECS task on AWS Fargate that is started for each upload`,`Fargate runs containers without servers to manage, a task performs its work and then stops, and the company pays only while the task runs.`],wrong:[[`Create a standard AWS Lambda function from the container image and invoke it for each upload`,`A standard Lambda function times out at 15 minutes, and the longest Lambda timeout on the quotas page is shorter than two hours, so a two-hour process cannot finish.`],[`Run the image as an Amazon ECS service on AWS Fargate with one task that always runs`,`The task runs and bills all day although runs are infrequent, so it costs more than starting a task for each upload.`],[`Run the image on a self-managed Amazon EC2 instance that stays on and polls for new uploads`,`The company would manage and pay for an always-on instance, which conflicts with the requirement to avoid servers.`]],slot:3,evidence:[`lambda-quotas|Code can run for up to 15 minutes in a single invocation`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`,`lambda-quotas|For functions using AWS Lambda Managed Instances, asynchronous invocations and event source mapping invocations (except Amazon MQ and Amazon DocumentDB) support a maximum allowed value of 5,400 seconds (90 minutes).`,`fargate-ecs|With AWS Fargate, you no longer have to provision, configure, or scale clusters of virtual machines to run containers.`,`ecs-what-is|Fargate is a serverless, pay-as-you-go compute engine.`,`ecs-what-is|Task An application such as a batch job that performs work, and then stops.`]}),t({id:`serverless-mill-009`,building:`serverless-mill`,bullets:[`2.1-K1`],d:2,stem:`A mobile app signs users in with an Amazon Cognito user pool. The backend is a REST API in Amazon API Gateway, and only signed-in users may call it. The company wants API Gateway to validate each caller before a request reaches the backend, with the LEAST custom code. Which solution meets these requirements?`,correct:[`Create an Amazon Cognito user pool authorizer for the API methods and have the app send its token in the Authorization header`,`API Gateway lets the call succeed only when a valid token from the user pool is supplied, and no authorization code has to be written.`],wrong:[[`Give every user an API key and require the key on the API methods through a usage plan`,`AWS says not to use API keys for authentication or authorization, because a key identifies a client for a usage plan and not a signed-in user.`],[`Write a Lambda authorizer that calls the user pool to validate the token on every request`,`This works, but it needs custom code to write and maintain, while the Cognito authorizer performs the check without code.`],[`Associate an AWS WAF web ACL that allows only requests that contain an Authorization header`,`AWS WAF can match header values but does not validate a token against a user pool, so any caller could add a header.`]],slot:0,evidence:[`apigw-cognito-authorizer|you can use an Amazon Cognito user pool to control who can access your API in Amazon API Gateway.`,`apigw-cognito-authorizer|The API call succeeds only if the required token is supplied and the supplied token is valid`,`apigw-usage-plans|Don't use API keys for authentication or authorization to control access to your APIs.`,`apigw-lambda-authorizer|Use a Lambda authorizer to implement a custom authorization scheme.`]}),e({id:`serverless-mill-010`,building:`serverless-mill`,bullets:[`2.1-K1`],d:3,tags:[`placement-eligible`],stem:`A company is designing a public product-catalog API on Amazon API Gateway in front of an AWS Lambda function. API Gateway must reject malformed request bodies before it invokes the function, and it must answer repeated GET requests from a cache for 300 seconds instead of invoking the function. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Create the API as a REST API`,`Request validation and caching are available in REST APIs and not in HTTP APIs.`],[`Enable caching on the API stage with a time-to-live of 300 seconds`,`API Gateway caches endpoint responses for the TTL period and answers repeated requests from the cache, so the function is not invoked.`]],wrong:[[`Create the API as an HTTP API to get request validation and caching at a lower price`,`HTTP APIs cost less but offer neither request validation nor caching.`],[`Configure a usage plan that limits every client to 300 requests`,`A usage plan throttles or caps requests for each client and neither validates bodies nor serves cached responses.`],[`Enable provisioned concurrency on the function so that repeated requests run faster`,`Provisioned concurrency reduces cold starts, but every request still invokes the function and bodies are not validated at the gateway.`]],slots:[0,3],evidence:[`apigw-http-vs-rest|Caching Yes No User-controlled deployments Yes Yes Automatic deployments No Yes Custom gateway responses Yes No Canary release deployments Yes No Request validation Yes No`,`apigw-caching|When you enable caching for a stage, API Gateway caches responses from your endpoint for a specified time-to-live (TTL) period, in seconds.`,`apigw-caching|The default TTL value for API caching is 300 seconds.`]}),t({id:`serverless-mill-011`,building:`serverless-mill`,bullets:[`2.1-S5`],d:2,tags:[`placement-eligible`],stem:`A startup runs an API whose traffic is close to zero overnight and jumps to thousands of requests per second during marketing campaigns. The small team does not want to manage servers or plan capacity, and it wants to pay in proportion to usage. Which architecture is the MOST suitable?`,correct:[`Amazon API Gateway invoking AWS Lambda functions that read and write an Amazon DynamoDB table`,`Each layer is serverless and scales automatically by unit of consumption with pay-for-value billing, so nothing is sized for campaigns or paid for overnight.`],wrong:[[`An Application Load Balancer in front of an Amazon EC2 Auto Scaling group sized for the campaign peak`,`Instances sized for the peak run and bill overnight, and the team has to manage the instances and the capacity.`],[`An Amazon ECS cluster on Amazon EC2 instances behind a Network Load Balancer, sized for the campaign peak`,`The team must manage and pay for the cluster capacity all night, which conflicts with no servers and usage-based cost.`],[`An Amazon EKS cluster with a managed node group that has a fixed number of worker nodes`,`A fixed node group does not follow demand, and the team still operates the cluster, which conflicts with usage-based cost.`]],slot:1,evidence:[`msa-whitepaper|Serverless is characterized by the following principles: No infrastructure to provision or manage Automatically scaling by unit of consumption "Pay for value" billing model Built-in availability and fault tolerance Event Driven Architecture (EDA)`,`apigw-welcome|Together with AWS Lambda, API Gateway forms the app-facing part of the AWS serverless infrastructure.`]}),e({id:`serverless-mill-012`,building:`serverless-mill`,bullets:[`2.1-K12`],d:3,tags:[`placement-eligible`],stem:`A company runs an interactive web application on Amazon API Gateway and AWS Lambda. Traffic is predictable: it rises every weekday at 08:00 and falls after 18:00, and users report slow first requests at the start of the peak because of cold starts. The company wants to remove the slow starts while paying for the higher level of pre-initialized capacity only during business hours. Which TWO actions meet these requirements at the LOWEST cost? (Choose two.)`,correct:[[`Publish a function version and configure provisioned concurrency on an alias that points to it`,`Provisioned concurrency keeps pre-initialized execution environments ready, and it works with versions and aliases but not with the $LATEST version.`],[`Schedule the provisioned concurrency setting to rise before 08:00 and fall after 18:00`,`Scheduled scaling (through Application Auto Scaling) follows predictable load changes, so the higher level of pre-initialized capacity exists only during business hours.`]],wrong:[[`Configure provisioned concurrency on the $LATEST version of the function`,`Provisioned concurrency cannot be used with the $LATEST version of a function.`],[`Set reserved concurrency to the peak value so that the execution environments stay initialized`,`Reserved concurrency reserves and caps capacity but does not keep execution environments pre-initialized.`],[`Increase the memory of the function to 10,240 MB`,`More memory adds CPU power, but new execution environments still have to initialize, so cold starts remain and each run costs more.`]],slots:[1,4],evidence:[`lambda-provisioned|You cannot use provisioned concurrency with the $LATEST version of any Event Function.`,`lambda-provisioned|With Application Auto Scaling, you can set your own scaling schedule according to predictable load changes.`,`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`]}),e({id:`serverless-mill-013`,building:`serverless-mill`,bullets:[`2.1-K12`],d:2,stem:`A company is building an AWS Lambda function that updates items in an Amazon DynamoDB table. The function must receive its permissions without any long-term access keys stored in its code or configuration. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Create an IAM role that allows the required DynamoDB actions on the table and set it as the execution role of the function`,`The execution role grants the function permission to access AWS services and resources, so no access keys are needed.`],[`Specify the Lambda service principal as a trusted service in the trust policy of the role`,`Lambda can assume the execution role only when the trust policy names the Lambda service principal as a trusted service.`]],wrong:[[`Store the access keys of an IAM user that has DynamoDB permissions in the environment variables of the function`,`Long-term access keys in configuration are exactly what the company wants to avoid.`],[`Attach a resource-based policy to the function that allows the DynamoDB service to access it`,`A resource-based policy on a function grants others access to the function and does not give the function permission to call DynamoDB.`],[`Write code in the function that calls the role-assumption API to assume the execution role on every invocation`,`Lambda assumes the execution role automatically, and AWS advises avoiding manual role-assumption calls in function code.`]],slots:[2,3],evidence:[`lambda-exec-role|A Lambda Event Function's execution role is an AWS Identity and Access Management (IAM) role that grants the function permission to access AWS services and resources.`,`lambda-exec-role|In order for Lambda to properly assume your execution role, the role's trust policy must specify the Lambda service principal (lambda.amazonaws.com) as a trusted service.`,`lambda-exec-role|You should avoid manually calling sts:AssumeRole to assume the execution role in your function code.`,`lambda-resource-policy|With resource-based permissions policies, you can grant other AWS accounts, users, organizations, and AWS services access to your Lambda Event Functions.`]}),t({id:`serverless-mill-014`,building:`serverless-mill`,bullets:[`2.1-S5`],d:3,tags:[`placement-eligible`],stem:`A company has an image-analysis function packaged as a 4 GB container image because of large libraries. Messages in an Amazon SQS queue start it at unpredictable times, and each run finishes in about 40 seconds. The team wants to avoid refactoring how the function is packaged and to avoid managing servers or container clusters. Which solution is the MOST cost-effective?`,correct:[`Create an AWS Lambda function from the container image and use the queue as its event source`,`Lambda accepts container images as a deployment package, runs in response to SQS messages, and has no servers to manage.`],wrong:[[`Run the image as an Amazon ECS service on AWS Fargate with tasks that poll the queue all day`,`The tasks run and bill continuously even when the queue is empty, which costs more than paying only when messages arrive.`],[`Run the image on Amazon EC2 instances in an Auto Scaling group that poll the queue for messages`,`The team would manage instances, patching and scaling, which conflicts with the requirement to avoid servers.`],[`Rewrite the function as a .zip package and split it into several smaller functions`,`This is the refactoring of the packaging that the team wants to avoid, and Lambda already supports container images.`]],slot:2,evidence:[`lambda-images|Lambda supports two types of deployment packages: container images and .zip file archives.`,`lambda-images|Lambda supports a maximum uncompressed image size of 10 GB, including all layers.`,`lambda-welcome|You write a handler function, connect it to a trigger (API Gateway, Amazon S3, Amazon SQS, EventBridge, and 200+ other AWS services), and Lambda executes it.`]}),t({id:`serverless-mill-015`,building:`serverless-mill`,bullets:[`2.1-K1`],d:2,tags:[`mock-reserve`],stem:`A company runs a REST API on Amazon API Gateway for mobile clients located on several continents. The company wants requests to enter the AWS network close to each client, with the LEAST operational overhead and no other services to configure. Which API endpoint type should the company use?`,correct:[`An edge-optimized endpoint`,`An edge-optimized API endpoint typically routes requests to the nearest CloudFront Point of Presence, which helps when clients are geographically distributed.`],wrong:[[`A Regional endpoint that serves the clients of every continent from one Region`,`A Regional API endpoint is intended for clients in the same Region and does not route requests through nearby edge locations.`],[`A private endpoint that the mobile clients reach through an interface VPC endpoint`,`A private API endpoint can only be accessed from a VPC, so mobile clients on the internet cannot reach it.`],[`A Regional endpoint with an Amazon CloudFront distribution that the company creates in front of it`,`This needs another service to create and configure, but the company wants no other services to configure.`]],slot:3,evidence:[`apigw-endpoint-types|An edge-optimized API endpoint typically routes requests to the nearest CloudFront Point of Presence (POP), which could help in cases where your clients are geographically distributed.`,`apigw-endpoint-types|A Regional API endpoint is intended for clients in the same Region.`,`apigw-http-vs-rest|Endpoint types REST API HTTP API Edge-optimized Yes No Regional Yes Yes Private Yes No`]}),t({id:`serverless-mill-016`,building:`serverless-mill`,bullets:[`2.1-K12`],d:2,tags:[`mock-reserve`],stem:`A company discovers that a faulty AWS Lambda function is writing bad data. Several event sources invoke the function. The company must stop the function from processing any events immediately, while keeping the function, its code and its configuration, with the LEAST effort. What should the company do?`,correct:[`Set the reserved concurrency of the function to 0`,`Setting reserved concurrency to 0 intentionally throttles the function, so it stops processing events until the limit is removed.`],wrong:[[`Delete the function and recreate it after the problem is fixed`,`Deleting the function removes its code and configuration, which the company wants to keep.`],[`Reduce the timeout of the function to the minimum value that Lambda allows`,`The function would still be invoked and could still write bad data before it times out.`],[`Reduce the memory of the function to the minimum value that Lambda allows`,`The function would still process events, only with less CPU power and memory.`]],slot:0,evidence:[`lambda-reserved|To intentionally throttle an Event Function, set its reserved concurrency to 0.`,`lambda-reserved|This stops your Event Function from processing any events until you remove the limit.`]})],h=[t({id:`single-point-watch-001`,building:`single-point-watch`,bullets:[`2.2-K5`],d:1,stem:`A company's mobile clients call a backend API. When the API briefly returns errors, every client retries at once in a tight loop, and the combined retries keep the recovering service overloaded. The company wants the clients to give the service time to recover. Which retry behavior is BEST?`,correct:[`Retry with exponential backoff and jitter, and stop after a fixed maximum number of retries`,`Backoff gives the service progressively longer intervals to recover, jitter randomizes the retries so they do not spike together, and a maximum stops endless load.`],wrong:[[`Retry every second on a fixed schedule from every client until the request finally succeeds`,`Fixed intervals line the clients up into coordinated spikes, and with no maximum the retries never stop adding load.`],[`Retry at the SDK, the application and the API layers so each failed call is attempted again at every layer`,`Retrying at several layers compounds the attempts into a retry storm that consumes even more resources.`],[`Retry immediately and repeatedly with the shortest possible delay so the first success is returned quickly`,`Immediate retries pile more load onto a service that is already overloaded and give it no time to self-heal.`]],slot:0,evidence:[`waf-retries|Backoff and jitter help avoid artificial traffic spikes due to unintentionally coordinated retries at common intervals.`,`waf-retries|Finally, it’s important to configure a maximum number of retries or elapsed time to avoid creating backlogs that produce metastable failures.`,`waf-retries|Retrying at multiple layers of your application stack in a manner which compounds retry attempts further consuming resources in a retry storm.`]}),t({id:`single-point-watch-002`,building:`single-point-watch`,bullets:[`2.2-K5`],d:2,stem:`A retail website's landing page shows personalized recommendations, top-ranked products and the customer's order status, each fetched from a different backend service. When the recommendations service is down, the whole page returns an error. The company wants the page to keep working during such failures. Which design change is MOST appropriate?`,correct:[`Treat the recommendations call as a soft dependency and render the rest of the page with default content`,`The page keeps its core function when one upstream system fails, so customers still see the other sections instead of an error page.`],wrong:[[`Retry the recommendations call until it succeeds before the page renders any of its other sections for the customer`,`This keeps the recommendations service as a hard dependency, so the page still fails or hangs whenever that service is down.`],[`Run a second copy of the page in another Availability Zone behind the same Application Load Balancer`,`The dependency is unavailable to every copy of the page, so a second copy fails in exactly the same way.`],[`Increase the page timeout so that the recommendations service has much longer to respond to each request`,`A longer wait still ends in an error when the service is down, and customers wait longer to see it.`]],slot:1,evidence:[`waf-graceful|Application components should continue to perform their core function even if dependencies become unavailable.`,`waf-graceful|When one upstream system fails, it still makes sense to display everything else instead of showing an error page to a customer.`]}),t({id:`single-point-watch-003`,building:`single-point-watch`,bullets:[`2.2-K5`],d:2,stem:`A company exposes a REST API through Amazon API Gateway to partner applications. The backend runs on Amazon EC2 instances. A faulty partner client sometimes floods the API with POST requests, which exhausts the backend and slows every other partner. The company wants the excess requests rejected with a throttled response, with the LEAST operational overhead and no backend code changes. Which solution meets these requirements?`,correct:[`Configure throttling limits on the API Gateway stage so that requests above the rate and burst limits are rejected`,`Requests below the throttling rate are processed and those over the limit are rejected with 429 Too Many Requests, protecting the backend.`],wrong:[[`Enable API caching on the stage so that repeated requests are answered without reaching the backend`,`Caching is enabled only for GET methods by default, and a cache serves repeated responses but never rejects excess requests.`],[`Raise the maximum size of the backend Auto Scaling group so that the flood is absorbed by additional instances`,`This spends more on capacity for faulty traffic and does not reject the excess requests as the company requires.`],[`Create an Amazon CloudWatch alarm on the request count that notifies the operators so that they block the faulty partner`,`A notification and manual block is not automatic, so the backend stays overloaded until someone acts.`]],slot:2,evidence:[`waf-throttle|Requests below throttling rates are processed while those over the defined limit are rejected with a return message indicating the request was throttled.`,`apigw-throttling|When request submissions exceed the steady-state request rate and burst limits, API Gateway begins to throttle requests.`,`apigw-throttling|Clients may receive 429 Too Many Requests error responses at this point.`]}),e({id:`single-point-watch-004`,building:`single-point-watch`,bullets:[`2.2-K5`],d:3,stem:`An image-processing API runs on Amazon EC2 instances. It works normally but fails when the request rate gets too high. Clients wait at most 30 seconds for a result and then give up, and the work can be completed asynchronously. The company wants the service to absorb traffic spikes without wasting capacity on requests that clients have already abandoned. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Have the API place each request in an Amazon SQS queue and answer the client immediately with an acknowledgment`,`A queue buffers requests when the rate is too high, and the client can release its resources instead of waiting.`],[`Have the workers compare each message timestamp with the current time and discard messages older than the client wait`,`Dropping stale messages prevents the processing of requests that a client has already given up on.`]],wrong:[[`Set the queue message retention period to its maximum so that no request is ever discarded from the backlog`,`Keeping every message lets a long backlog build up, and the workers spend capacity on stale requests.`],[`Use an Amazon SQS FIFO queue so that the oldest requests are always processed before any newer request`,`Strict oldest-first order makes new, time-sensitive requests wait behind a backlog of requests already abandoned.`],[`Move the API to larger instances and keep every client connection open until its image has been processed`,`The synchronous design still fails when the request rate is too high, and it holds resources for abandoned clients.`]],slots:[1,4],evidence:[`waf-fail-fast|When a service is able to respond successfully under normal conditions but fails when the rate of requests is too high, use a queue to buffer requests.`,`waf-fail-fast|However, do not allow a buildup of long queue backlogs that can result in processing stale requests that a client has already given up on.`,`waf-fail-fast|Either retry or, when tolerable, drop old messages by comparing now to the message timestamp and discarding messages that are no longer relevant to the requesting client.`]}),e({id:`single-point-watch-005`,building:`single-point-watch`,bullets:[`2.2-K5`],d:3,stem:`A payment service calls a card-processing API. The call is retried by the SDK, again by an application wrapper and again by a gateway layer. During an outage the card API was flooded with repeated calls, and some customers were charged twice. The company wants to stop the retry storm and prevent duplicate charges. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Implement retries at only one layer of the call stack`,`Retrying at multiple layers compounds the attempts and consumes resources in a retry storm.`],[`Make the charge operation idempotent by sending an idempotency token that is reused whenever the request is repeated`,`A repeated request carrying the same token does not produce a second charge, so retries become safe.`]],wrong:[[`Raise the maximum number of retries at every layer so that each charge is eventually completed`,`More retries at every layer multiply the load on the overloaded API and the chance of duplicate charges.`],[`Switch every layer to fixed retry intervals so that the retry attempts arrive at predictable times`,`Fixed intervals align the retries into coordinated spikes; backoff and jitter are what avoid them.`],[`Send each retry to a second card-processing endpoint at the same moment as the original call`,`Sending parallel copies of the call doubles the load and increases the risk of duplicate charges.`]],slots:[0,3],evidence:[`waf-retries|Be sure to understand how these errors affect your application the dependencies you rely on, then implement retries at only one level.`,`waf-retries|Retrying service calls that are not idempotent, causing unexpected side effects like duplicated results.`,`waf-idempotent|To do this, clients can issue API requests with an idempotency token, which is used whenever the request is repeated.`]}),t({id:`single-point-watch-006`,building:`single-point-watch`,bullets:[`2.2-K5`],d:2,stem:`A checkout service calls a fraud-scoring service. The fraud service is overloaded and times out, yet checkout keeps sending every request and retrying it, which prevents the fraud service from recovering. Checkout is allowed to approve low-value orders without a score. The company wants checkout to stop adding load and keep working. Which approach is BEST?`,correct:[`Add a circuit breaker that stops calls after many failures, lets test calls through, and approves small orders`,`Stopping calls relieves the overloaded service, test calls detect its recovery, and approving low-value orders keeps the core function working.`],wrong:[[`Raise the checkout timeout and the retry count so that each scoring call has more chances to eventually succeed`,`More retries and longer waits add load to a service that is already overloaded and delay its recovery.`],[`Scale out the checkout service so that more scoring calls are sent in parallel during the overload`,`More callers increase the load on the overloaded fraud service, and checkout still fails on each timeout.`],[`Hold every order in an Amazon SQS queue until the fraud service answers and make customers wait for approval`,`Customers cannot complete checkout while the dependency is down, so the core function is not kept working.`]],slot:3,evidence:[`waf-graceful|If a high number of calls are failing, it will stop sending more requests to the downstream system and only occasionally let calls through to test whether the downstream system is available again.`,`waf-graceful|If requests to a downstream system are consistently failing, it does not make sense to continue retrying.`]}),t({id:`single-point-watch-007`,building:`single-point-watch`,bullets:[`2.2-K8`],d:2,stem:`A web application runs in an Auto Scaling group behind an Application Load Balancer. The company turned on Elastic Load Balancing health checks for the group so that instances reported unhealthy are replaced. Since then, new instances are terminated and replaced repeatedly before the application finishes starting, which takes about six minutes. The company must keep replacing instances that the load balancer reports unhealthy. Which change MOST directly fixes the problem?`,correct:[`Increase the health check grace period of the group to longer than the application start-up time`,`The group waits for the grace period before checking a new instance, so the application can start before health checks can fail it.`],wrong:[[`Turn off Elastic Load Balancing health checks for the group and rely only on the EC2 health checks`,`This stops the replacement of instances that the load balancer reports unhealthy, which the company must keep.`],[`Reduce the health check interval of the target group to its minimum so that problems are detected faster`,`A shorter interval runs more checks against an application that is still starting, so more instances fail.`],[`Raise the desired capacity of the group so that more instances share the work of starting the application`,`Extra instances each still fail the load balancer checks during start-up and are replaced the same way.`]],slot:0,evidence:[`asg-attach-lb|This is how long Amazon EC2 Auto Scaling needs to wait before checking the health status of an instance after it enters the InService state.`,`asg-health-checks|Then, Amazon EC2 Auto Scaling performs health checks on the instance by using the built-in Amazon EC2 status checks, and after a grace period, any optional health checks that you enabled for the group.`]}),t({id:`single-point-watch-008`,building:`single-point-watch`,bullets:[`2.2-K8`],d:3,stem:`A company runs a web application behind an Application Load Balancer in each of two AWS Regions. The primary Region should receive all client traffic, and the second Region should receive traffic only when the primary Region cannot serve requests. When every target in the primary Region fails, clients currently get errors because DNS keeps returning the primary load balancer. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create Route 53 failover alias records for the two load balancers with a health check on the primary`,`With failover routing, Route 53 sends traffic to the primary resource while it is healthy and to the secondary resource when the primary is unhealthy.`],wrong:[[`Create one simple routing record that lists both load balancers`,`Simple routing returns the values in random order and does not health check them, so clients would still reach the failed Region.`],[`Enable cross-zone load balancing on both load balancers`,`Cross-zone load balancing distributes traffic across targets in the Availability Zones of one load balancer and cannot send clients to another Region.`],[`Create weighted records that give both load balancers the same weight and no health checks`,`Equal weights send about half of the clients to the primary Region all the time, including when it has failed, and nothing detects the failure.`]],slot:1,evidence:[`route53-failover-routing|With failover routing, you can route traffic to a resource when it's healthy or to a different resource when the first one is unhealthy.`,`route53-failover-types|Use an active-passive failover configuration when you want a primary resource or group of resources to be available the majority of the time and you want a secondary resource or group of resources to be on standby in case all the primary resources become unavailable.`,`route53-simple|With simple routing, although you can specify multiple IP addresses, they are not health checked.`,`elb-how-it-works|When cross-zone load balancing is enabled, each load balancer node distributes traffic across the registered targets in all enabled Availability Zones.`]}),t({id:`single-point-watch-009`,building:`single-point-watch`,bullets:[`2.2-K8`],d:2,stem:`A web application runs in an Auto Scaling group behind an Application Load Balancer. Some users download reports that take up to ten minutes. When the group scales in, those users receive HTTP 500 errors because the instance being removed ends their connection. The company wants in-flight downloads to finish during scale-in. Which change meets this requirement with the LEAST effort?`,correct:[`Increase the deregistration delay of the target group to be longer than the longest download`,`A deregistering target stays in the draining state until the delay elapses, so in-flight requests can complete before it is removed.`],wrong:[[`Reduce the deregistration delay of the target group to zero so that instances leave the target group at once`,`Removing instances immediately ends connections sooner, which produces more of the 500 errors.`],[`Enable sticky sessions on the target group so that each user stays with one instance for the whole session`,`Stickiness does not stop an instance from being terminated, so the user connection still ends with an error.`],[`Turn on slow start mode for the target group so that new instances receive requests gradually after launch`,`Slow start affects newly registered targets and has no effect on requests running on instances being removed.`]],slot:2,evidence:[`alb-target-attrs|By default, Elastic Load Balancing waits 300 seconds before completing the deregistration process, which can help in-flight requests to the target to complete.`,`alb-target-attrs|To change the amount of time that Elastic Load Balancing waits, update the deregistration delay value.`,`alb-target-attrs|If a deregistering target terminates the connection before the deregistration delay elapses, the client receives a 500-level error response.`]}),t({id:`single-point-watch-010`,building:`single-point-watch`,bullets:[`2.2-K8`],d:1,stem:`A company runs web servers in an Auto Scaling group. When the group scales out, an operator must add each new instance to the load balancer by hand, and until then the instance receives no traffic. The company wants new instances to receive traffic automatically, with the LEAST manual effort. What should the company do?`,correct:[`Attach the load balancer target group to the Auto Scaling group so that new instances are registered automatically`,`The group registers instances with the load balancer when they launch and deregisters them when they terminate.`],wrong:[[`Assign an Elastic IP address to each new instance and publish the addresses in the DNS records of the company website`,`Each launch would still need manual address and DNS changes, and the load balancer would not distribute traffic.`],[`Add a launch script that calls the AWS CLI to update the target group each time a new instance starts up`,`This is custom code to build and maintain, where the group can register instances without any scripting.`],[`Register a fixed number of extra instances in the target group in advance to cover the busiest expected load`,`A fixed fleet does not follow demand, and idle instances run all the time at the cost of the company.`]],slot:3,evidence:[`asg-what-is|Whenever instances are launched or terminated, Amazon EC2 Auto Scaling automatically registers and deregisters the instances from the load balancer.`,`asg-attach-lb|When you attach an Application Load Balancer, Network Load Balancer, or Gateway Load Balancer, you attach a target group rather than the load balancer itself.`]}),t({id:`single-point-watch-011`,building:`single-point-watch`,bullets:[`2.2-K9`],d:1,stem:`AWS Lambda functions connect to an Amazon RDS for MySQL DB instance. During traffic spikes many functions run at once, and the database returns "too many connections" errors. The company wants to fix this with the LEAST change to the application code. Which solution meets this requirement?`,correct:[`Create an Amazon RDS Proxy for the DB instance and connect the functions to the proxy endpoint`,`The proxy pools and shares database connections, so many function connections use a smaller number of long-lived database connections.`],wrong:[[`Create a read replica and send every query from the functions to the replica instead of the primary`,`A replica has connection limits of its own and is read-only, so this moves the problem and breaks writes.`],[`Convert the DB instance to a Multi-AZ DB instance deployment with a synchronous standby replica`,`The standby does not serve traffic, so the number of connections the functions can use stays the same.`],[`Increase the memory setting of each Lambda function to the maximum value that Lambda allows`,`More function memory does not reduce the number of connections that the concurrent functions open.`]],slot:0,evidence:[`rds-proxy-planning|Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`rds-proxy-planning|AWS Lambda functions can also be good candidates for using a proxy.`,`rds-proxy|You can enable RDS Proxy for most applications with no code changes.`]}),t({id:`single-point-watch-012`,building:`single-point-watch`,bullets:[`2.2-K9`],d:2,stem:`An application uses an Amazon RDS for PostgreSQL Multi-AZ DB instance deployment. When a failover occurs, the application connections drop, and clients keep resolving the old address from their DNS caches, so recovery takes longer than the company accepts. The company wants failovers to be more transparent to the application, with no application code changes. Which solution meets these requirements?`,correct:[`Place Amazon RDS Proxy in front of the DB instance and point the application at the proxy endpoint`,`The proxy bypasses DNS caches and routes traffic to the new instance while preserving application connections.`],wrong:[[`Add a read replica in a third Availability Zone and have the application switch to it after a failure`,`A replica is read-only and needs a manual promotion, so failover stays slow and is not transparent.`],[`Move the database to a larger DB instance class so that the failover process finishes in less time`,`Instance size does not keep application connections open or bypass the DNS caches of the clients.`],[`Lower the connection timeout in the application so that it notices the failed primary much sooner`,`The connections still drop and the clients still resolve the old address, and the change needs code work.`]],slot:1,evidence:[`rds-proxy-planning|RDS Proxy bypasses Domain Name System (DNS) caches to reduce failover times by up to 66% for Amazon RDS Multi-AZ DB instances.`,`rds-proxy-planning|RDS Proxy also automatically routes traffic to a new database instance while preserving application connections.`,`rds-proxy-planning|This makes failovers more transparent for applications.`]}),e({id:`single-point-watch-013`,building:`single-point-watch`,bullets:[`2.2-K9`],d:2,stem:`A company reviews its Amazon RDS for MySQL workloads to decide where Amazon RDS Proxy would help most. Which TWO workloads are the BEST candidates for a proxy? (Choose two.)`,correct:[[`A DB instance that frequently returns "too many connections" errors during traffic peaks`,`The proxy lets applications open many client connections while it manages a smaller number of long-lived connections to the instance.`],[`AWS Lambda functions that make frequent short database connections`,`These functions benefit from the connection pooling that the proxy offers.`]],wrong:[[`A DB instance whose storage space is running low as the amount of stored data grows`,`Connection pooling does not add storage; the fix is more storage, not a proxy.`],[`A DB instance whose long analytical queries scan large tables and run slowly for the analysts`,`Slow queries are not a connection problem; offloading reads to a replica or tuning the queries addresses them.`],[`A DB instance in one Region that must be recoverable in a second Region after a Regional outage`,`A proxy works within one VPC and does not copy data to another Region.`]],slots:[2,4],evidence:[`rds-proxy-planning|Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-proxy-planning|These functions make frequent short database connections that benefit from connection pooling offered by RDS Proxy.`]}),t({id:`single-point-watch-014`,building:`single-point-watch`,bullets:[`2.2-K9`],d:3,stem:`AWS Lambda functions query an Amazon RDS for PostgreSQL DB instance, and concurrent invocations exhaust the database connections. Security policy forbids database passwords in function code and function configuration. The company wants the functions to authenticate with the credentials they already have, and wants the fix to also stop the connection exhaustion. Which solution meets these requirements?`,correct:[`Create an RDS proxy that reads the credentials from AWS Secrets Manager and requires IAM authentication from the functions`,`The proxy pools the connections, the functions use IAM instead of a database password, and the proxy uses the stored credentials.`],wrong:[[`Keep the password in encrypted Lambda environment variables and add a read replica to spread the connections across both`,`The password stays in function configuration, and a replica does not pool connections or accept writes.`],[`Raise the max_connections parameter in the DB parameter group and read the password from AWS Secrets Manager in each function`,`Every invocation still opens its own connection, so the connection pressure and the memory use remain.`],[`Limit the reserved concurrency of the functions to a low value and keep the database password in a configuration file`,`A low concurrency cap throttles the application, and the password is still stored in the function package.`]],slot:2,evidence:[`rds-proxy|By using RDS Proxy, you can enforce AWS Identity and Access Management (IAM) authentication for clients connecting to the proxy, and the proxy can connect to databases using either IAM database authentication or credentials stored in AWS Secrets Manager.`,`rds-proxy-planning|You can take advantage of any IAM authentication you already have for Lambda functions, instead of managing database credentials in your Lambda application code.`]}),t({id:`single-point-watch-015`,building:`single-point-watch`,bullets:[`2.2-K9`,`2.2-S4`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs a single-Availability-Zone Amazon RDS DB instance. To improve availability, an engineer placed an Amazon RDS Proxy in front of it. In a test, the Availability Zone of the DB instance was made unavailable, and the application stayed down until the instance was restored. The application must survive an Availability Zone failure, with the LEAST change. What should the company do?`,correct:[`Convert the DB instance to a Multi-AZ deployment and keep the proxy in front of it`,`The standby provides failover support, and the proxy connects to the standby while preserving application connections.`],wrong:[[`Create a second RDS Proxy in another Availability Zone and register the same DB instance as its target`,`Both proxies would still point at the one instance in the failed zone, so there is no database to fail over to.`],[`Add a read replica in another Availability Zone and register it as the target of the existing proxy`,`A proxy can be associated only with the writer of a replicated DB instance, and a replica needs a manual promotion.`],[`Increase the maximum connections percentage of the proxy so that it holds more connections open`,`The setting changes how many connections the proxy opens and does not create a standby in another zone.`]],slot:3,evidence:[`rds-proxy|RDS Proxy makes applications more resilient to database failures by automatically connecting to a standby DB instance while preserving application connections.`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`,`rds-proxy|For RDS DB instances in replication configurations, you can associate a proxy only with the writer DB instance, not a read replica.`]}),t({id:`single-point-watch-016`,building:`single-point-watch`,bullets:[`2.2-S4`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs a production Amazon RDS for MySQL DB instance in one Availability Zone and has added a read replica in a second zone, believing that this protects the database against an Availability Zone failure. The company now requires automatic failover with synchronous replication to a standby in another zone, without a manual step. Which change meets these requirements?`,correct:[`Modify the DB instance to use a Multi-AZ DB instance deployment`,`RDS provisions a synchronous standby in a different Availability Zone and fails over to it automatically.`],wrong:[[`Keep the read replica and promote it manually to a standalone instance if the primary fails`,`Replication to a replica is asynchronous and promotion is a manual step, which the company wants to avoid.`],[`Create a second read replica in a third Availability Zone and promote whichever one is closest`,`More replicas still replicate asynchronously and still need a manual promotion after a failure.`],[`Create a cross-Region read replica and promote it to a standalone instance if the primary fails`,`This is an asynchronous disaster recovery copy that needs a manual promotion, not an automatic zone failover.`]],slot:0,evidence:[`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`rds-read-replicas|Amazon RDS then uses the asynchronous replication method for the DB engine to update the read replica whenever there is a change to the primary DB instance.`,`rds-promote|Implementing failure recovery – You can use read replica promotion as a data recovery scheme if the primary DB instance fails.`]}),e({id:`single-point-watch-017`,building:`single-point-watch`,bullets:[`2.2-S4`],d:2,stem:`A company runs its application on a single Amazon EC2 instance with an Elastic IP address, backed by a single-AZ Amazon RDS DB instance. An outage in that Availability Zone would take both offline. The company wants to remove the single points of failure and keep one endpoint for users. Which TWO changes meet these requirements? (Choose two.)`,correct:[[`Run the web tier in an Auto Scaling group that spans at least two Availability Zones behind an Application Load Balancer`,`No single instance or zone is a point of failure, and failed instances are replaced automatically.`],[`Convert the DB instance to a Multi-AZ deployment`,`A standby in another Availability Zone provides failover support if the primary or its zone fails.`]],wrong:[[`Move to a larger EC2 instance type and a larger DB instance class in the same Availability Zone`,`Larger resources in the same zone are still one instance each in one zone.`],[`Take frequent Amazon EBS snapshots of the instance volume and the database and keep them in the same Region`,`Snapshots speed up a rebuild but do not keep the application running during a zone outage.`],[`Add a read replica of the DB instance in the same Availability Zone as the primary`,`A replica in the same zone fails with that zone and does not provide automatic failover.`]],slots:[0,3],evidence:[`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`,`elb-what-is|Using a load balancer increases the availability and fault tolerance of your applications.`,`rds-multi-az-instance|It can also help protect your databases against DB instance failure and Availability Zone disruption.`]}),t({id:`single-point-watch-018`,building:`single-point-watch`,bullets:[`2.2-S4`],d:1,stem:`An Auto Scaling group runs six web instances, all in a single subnet in one Availability Zone, behind an Application Load Balancer. The company wants the web tier to keep serving traffic if that Availability Zone becomes unavailable, with the LEAST change. What should the company do?`,correct:[`Add subnets in other zones to the Auto Scaling group and the load balancer so that instances are balanced across zones`,`The group balances instances evenly across the zones it spans, and the load balancer sends traffic to healthy targets in each zone.`],wrong:[[`Increase the maximum size of the group so that many more instances run together in the same Availability Zone`,`More instances in the same zone still fail together when the zone becomes unavailable.`],[`Assign a second Elastic IP address to every instance in the group so that each instance has two public addresses`,`Extra addresses do not move any capacity out of the failing zone.`],[`Change the group to a larger instance type with enhanced networking that stays in the same Availability Zone`,`A different instance type in the same zone still depends on that one zone.`]],slot:1,evidence:[`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`,`asg-what-is|This provides high availability and resiliency by protecting your applications from failures in a single location.`]}),t({id:`single-point-watch-019`,building:`single-point-watch`,bullets:[`2.2-S4`,`2.2-K5`],d:3,stem:`An order-capture API writes each order to the single writer of an Amazon RDS for PostgreSQL Multi-AZ deployment. During a failover the writer is unavailable for a short time, and customers see errors and lose their carts. The company wants to keep accepting orders during these periods without losing any order. Which design BEST meets these requirements?`,correct:[`Have the API put each order in an Amazon SQS queue and have a consumer write the orders to the database later`,`Writes are buffered so requests can still be accepted while the primary is temporarily unavailable, and the consumer applies them afterwards.`],wrong:[[`Add a read replica and have the API write orders to the replica whenever the primary writer is unavailable`,`A read replica is read-only, so it cannot accept the order writes.`],[`Retry the insert in the application for a few seconds and then return an error to the customer`,`Retries that give up after a few seconds still refuse orders while the writer is unavailable.`],[`Move the database to a larger DB instance class so that the failover completes in less time overall for every order`,`A larger class does not remove the unavailable period, so orders are still refused during failover.`]],slot:2,evidence:[`waf-graceful|Writes can be buffered, for example in an Amazon Simple Queue Service queue, so that write requests from customers can still be accepted even if the primary is temporarily unavailable.`,`waf-graceful|Amazon Relational Database Service, like almost all relational databases, can only have one primary writer instance.`,`rds-read-replicas|Clients have read/write access to the primary DB instance and read-only access to the replica.`]}),t({id:`single-point-watch-020`,building:`single-point-watch`,bullets:[`2.2-S4`],d:2,tags:[`trap:ebs-efs-fsx`],stem:`A company keeps user-uploaded documents on an Amazon EBS volume attached to one Amazon EC2 instance, which shares them over NFS with six web servers in two Availability Zones. If that instance or its zone fails, all web servers lose the documents. The company wants to remove this single point of failure with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Move the documents to a Regional Amazon EFS file system and mount it on all of the web servers`,`A Regional file system stores data redundantly across multiple Availability Zones, and EFS removes the file server to manage.`],wrong:[[`Run a second NFS server in the other Availability Zone and synchronize the two servers with a scheduled job`,`The servers, the synchronization and the failover are all self-managed, which adds the overhead the company wants to avoid.`],[`Create an Amazon EFS One Zone file system in the Availability Zone of the current NFS server`,`A One Zone file system keeps data in one zone, so the loss of that zone can lose or block the documents.`],[`Take hourly snapshots of the EBS volume and restore the latest one on a new instance after a failure`,`Restoring takes time and loses recent uploads, so the web servers still lose access during each failure.`]],slot:3,evidence:[`efs-what-is|Regional (Recommended) – Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`,`efs-what-is|Storing data across multiple Availability Zones provides continuous availability to the data, even when one or more Availability Zones in an AWS Region are unavailable.`,`efs-what-is|In the unlikely case of the loss or damage to all or part of the Availability Zone, however, data that is stored in these types of file systems might be lost.`]}),t({id:`single-point-watch-021`,building:`single-point-watch`,bullets:[`2.2-K8`],d:2,tags:[`mock-reserve`],stem:`A company is migrating a web application in stages. Some web servers remain in the company's data center, which is connected to the VPC through an AWS Site-to-Site VPN connection, while new servers run on Amazon EC2. The company wants one Application Load Balancer to spread traffic across both groups of servers and send requests only to healthy ones. Which configuration meets these requirements?`,correct:[`Create a target group with the IP target type and register the private IP addresses of all of the servers`,`IP targets can include on-premises resources reached through a Site-to-Site VPN, and the load balancer sends requests only to healthy targets.`],wrong:[[`Create a target group with the instance target type and register the on-premises servers by their host names`,`The instance type registers EC2 instances by instance ID, so on-premises servers cannot be registered that way.`],[`Create a target group with the IP target type and register the public IP addresses of the on-premises servers`,`Publicly routable IP addresses cannot be specified for IP targets, only private ranges and the VPC subnets.`],[`Create a target group with the Lambda target type and invoke a function that forwards each request to the data center servers`,`This adds a function to build and maintain, and the load balancer does not health-check the servers behind it.`]],slot:0,evidence:[`alb-target-groups|On-premises resources linked to AWS through Direct Connect or a Site-to-Site VPN connection.`,`alb-target-groups|You can't specify publicly routable IP addresses.`,`elb-what-is|It monitors the health of its registered targets, and routes traffic only to the healthy targets.`]}),t({id:`single-point-watch-022`,building:`single-point-watch`,bullets:[`2.2-K9`],d:3,tags:[`mock-reserve`],stem:`A ticketing application sees its traffic jump from a few hundred to tens of thousands of users when sales open. It opens a new database connection for each request to an Amazon RDS for MySQL DB instance, and earlier surges made the database fail abruptly. The company wants the database protected from connection oversubscription, with excess requests queued or shed. Which solution BEST meets these requirements?`,correct:[`Use Amazon RDS Proxy and limit the number of database connections it creates, so excess requests are queued or rejected`,`The proxy controls the connections made to the database and queues, throttles or sheds the connections it cannot serve.`],wrong:[[`Move to a larger DB instance class and raise the max_connections value to a very large number for the surge`,`More allowed connections only lets the surge reach the database, which can still fail abruptly at the larger size.`],[`Add read replicas and have the application spread all of its queries across them in a round-robin order each time`,`Replicas are read-only and have their own connection limits, so the surge simply moves to the replicas.`],[`Run a larger fleet of application servers so that each individual server opens fewer database connections at once`,`The total number of connections reaching the database stays the same, so the surge is not limited.`]],slot:1,evidence:[`rds-proxy|To protect a database against oversubscription, you can control the number of database connections that are created.`,`rds-proxy|RDS Proxy queues or throttles application connections that can't be served immediately from the connection pool.`,`rds-proxy|If connection requests exceed the limits you specify, RDS Proxy rejects application connections (that is, it sheds load).`]}),t({id:`single-point-watch-023`,building:`single-point-watch`,bullets:[`2.2-S4`],d:1,tags:[`mock-reserve`],stem:`A company serves its website from a single Amazon EC2 web server that has an Elastic IP address. If the server fails, the company wants visitors to see a simple static "temporarily unavailable" page, with the LOWEST cost and operational overhead. Which solution meets these requirements?`,correct:[`Create Route 53 failover records with the server as primary and an S3 bucket configured as a website as secondary`,`When the primary is unhealthy, Route 53 answers with the secondary, so visitors get the static page from a low-cost bucket.`],wrong:[[`Create weighted Route 53 records that send half of the queries to the server and the other half to the static page bucket`,`Half of the visitors would see the unavailable page even while the server is healthy.`],[`Place the server in an Auto Scaling group with a minimum size of one so that a failed instance is replaced`,`Visitors see connection errors, not a page, until the replacement instance finishes starting.`],[`Create a Route 53 health check alarm that emails the operators, who then change the DNS record by hand`,`The switch depends on a person acting, so visitors keep reaching the failed server until the record is changed.`]],slot:2,evidence:[`route53-failover-types|Some customers use a web server as their primary resource and an Amazon S3 bucket that is configured as a website endpoint as their secondary resource.`,`route53-failover-types|The S3 bucket contains a simple "temporarily unavailable" message.`]})],g=[t({id:`tide-gauges-001`,building:`tide-gauges`,bullets:[`2.2-K10`],d:1,stem:`During a promotion, an Auto Scaling group cannot launch more Amazon EC2 instances because the account has reached a service quota for running instances in the Region. The group's maximum size is already higher than the number of instances that are running. The company wants the group to be able to grow, with the LEAST effort. What should the company do?`,correct:[`Request an increase of that quota for the Region through AWS Support`,`Support can approve a quota increase request, which raises the account ceiling that blocks the launches.`],wrong:[[`Raise the maximum size of the group further so that it is allowed to run more instances`,`The group's maximum is not the limit that is blocking launches; the account-level quota is, and it stays unchanged.`],[`Create an Amazon CloudWatch alarm on the group's CPU utilization so that scaling out starts sooner`,`Scaling out sooner still runs into the same account quota, so the launches keep failing.`],[`Turn on AWS Config recording for the instances so that their configuration history is kept`,`Recording configuration history does not change the number of instances that the account may run.`]],slot:0,evidence:[`aws-service-quotas-general|You can request increases for some quotas, but not all quotas can be increased.`,`aws-service-quotas-general|To request a quota increase Support might approve, deny, or partially approve your quota increase requests.`]}),t({id:`tide-gauges-002`,building:`tide-gauges`,bullets:[`2.2-K10`],d:2,stem:`A company raised its Amazon EC2 instance quota in the primary Region before a big launch. Its disaster recovery plan uses a second Region as a standby, and a failover test with a handful of instances succeeded. The company wants to be sure the standby Region can take the full production load. What is the MOST reliable approach?`,correct:[`Request matching quota increases in the standby Region, sized for the full production load`,`Quotas are specific to a Region, so the standby Region needs its own appropriate quotas to carry the full load after failover.`],wrong:[[`Rely on the increase already made, because a quota raised in one Region applies in every Region`,`Each quota is Region-specific unless noted otherwise, so the standby Region keeps its own, lower value.`],[`Wait until a real failover happens and request the increase in the standby Region at that moment`,`Increases take time to review and might be denied or partly approved, which can block the failover.`],[`Repeat the small failover test every month, because a test would reveal any quota difference`,`Tests at low load rarely find quota differences between Regions, so the gap stays hidden.`]],slot:1,evidence:[`waf-quotas-regions|Service quotas are tracked per account.`,`waf-quotas-regions|If you are using multiple accounts or Regions, request the appropriate quotas in all environments in which your production workloads run.`,`waf-quotas-regions|The testing plans of passive Region failovers are rarely scaled to peak active capacity, meaning that game day or table top exercises can fail to find differences in service quotas between Regions and also then maintain the correct limits.`]}),t({id:`tide-gauges-003`,building:`tide-gauges`,bullets:[`2.2-K10`],d:3,stem:`An operations team wants an Amazon SNS notification when usage of a service quota that publishes usage metrics reaches 60 percent, so that it has time to request increases before an outage. Alerts that arrive after usage is already near the limit are too late. Which solution meets these requirements with the LEAST custom work?`,correct:[`Create an Amazon CloudWatch alarm on the quota usage metric with a threshold at 60 percent of the quota value and an SNS action`,`Quota usage metrics are published to CloudWatch, so an alarm with a chosen threshold sends the notification well before the limit is reached.`],wrong:[[`Rely on the AWS Trusted Advisor service limit checks, which flag usage that is more than 80 percent of a quota`,`Those checks flag usage only above 80 percent, which is later than the 60 percent point the team needs.`],[`Create a CloudWatch alarm on the CPUUtilization metric of the instances in every Region that the team currently uses for production`,`CPU utilization measures load on the instances and says nothing about how much of a quota is used.`],[`Search the AWS CloudTrail event history every week for errors that were returned when a limit was exceeded`,`This finds failures after they have happened and does not warn the team before usage nears the limit.`]],slot:2,evidence:[`cw-usage-metrics|These metrics correspond to AWS service quotas.`,`cw-usage-metrics|Service quota usage metrics are in the AWS/Usage namespace and are collected every minute.`,`trusted-advisor-service-limits|Checks for usage that is more than 80% of the CloudFormation stacks quota.`]}),t({id:`tide-gauges-004`,building:`tide-gauges`,bullets:[`2.2-K10`],d:3,stem:`A company expects a steady request rate for its Amazon API Gateway REST API during a launch that is several times the default account-level rate limit for the Region. The stage-level, method-level and per-client limits are already set to the highest values that API Gateway allows, yet clients receive 429 Too Many Requests responses at the current rate. Which action will let the API serve the launch traffic?`,correct:[`Request an increase of the account-level throttling rate limit for the Region through the AWS Support Center`,`The account-level rate limit can be increased on request, and stage, method and client limits cannot exceed the limits above them.`],wrong:[[`Raise the per-client rate in the usage plan to a value above the account-level limit for the Region`,`Per-client limits cannot be higher than the per-account limits, so the account-level limit still caps the traffic.`],[`Set the throttle for each method on the stage to a value above the AWS throttling limit for the Region`,`Per-method limits cannot be higher than the AWS throttling limits, so the 429 responses continue.`],[`Change every client to retry each throttled request three times right after it receives the 429 error response`,`Immediate retries add to the request rate, and they do not raise the limit that the steady traffic exceeds.`]],slot:3,evidence:[`apigw-throttling|The account-level rate limit can be increased upon request - higher limits are possible with APIs that have shorter timeouts and smaller payloads.`,`apigw-throttling|To request an increase of account-level throttling limits per Region, contact the AWS Support Center.`,`apigw-throttling|Note that these limits can't be higher than the per-account limits.`]}),e({id:`tide-gauges-005`,building:`tide-gauges`,bullets:[`2.2-K10`],d:2,stem:`A company runs an active/passive workload in two Regions. Its failover exercises have always passed, but they ran with only a small share of the production load. The company wants to be confident that service quotas will not block a real failover. Which TWO actions should the company take? (Choose two.)`,correct:[[`Compare the value of each relevant quota in the primary and standby Regions and reconcile every difference`,`Quota drift, a limit changed in one Region and not in all, is important to track and correct.`],[`Verify that the standby Region can run the peak load, and request quota increases there to match the primary Region`,`The passive Region must be able to take the full load, which depends on its own quotas.`]],wrong:[[`Leave the standby Region at the default quotas, because raising a quota reserves capacity and adds cost`,`Raising a quota does not reserve compute capacity, and default values can block the failover.`],[`Track quotas only in the primary Region, because the standby Region receives no traffic until a failover`,`The standby Region receives the whole load during a failover, so its quotas must be managed too.`],[`Keep running the small-scale failover exercise, which would show any difference in quotas between the Regions`,`Exercises that are not scaled to peak capacity rarely reveal differences in quotas between Regions.`]],slots:[0,3],evidence:[`waf-quotas-regions|Service quota drift, the condition where service quota limits for a specific named quota is changed in one Region and not all Regions, is very important to track and assess.`,`waf-quotas-regions|Verify that load will successfully run in secondary Regions in the event of a failure in the primary Region.`,`waf-quotas-regions|Not updating service quotas due to incorrectly thinking that increasing quotas has cost implications like compute reservation requests.`]}),t({id:`tide-gauges-006`,building:`tide-gauges`,bullets:[`2.2-K12`],d:1,stem:`In a microservices application, one customer request passes through an API, several services and an Amazon DynamoDB table. Users report slow responses. The team wants to see how long each call in the request path takes, so that it can find the bottleneck. Which AWS service BEST meets this requirement?`,correct:[`AWS X-Ray, using the trace map built from the trace data of the services`,`X-Ray shows the calls an application makes to downstream resources and builds a trace map to identify bottlenecks and latency spikes.`],wrong:[[`AWS CloudTrail, using the event history of the API calls made by users and services`,`CloudTrail records who took which action as events and does not break down the latency of each call in a request.`],[`AWS Config, using the configuration history of the resources that the application uses`,`Config shows how resources were configured over time, not how long each call in a request takes.`],[`Amazon S3 Storage Lens, using the usage and activity metrics of the buckets in the account`,`Storage Lens reports on storage usage and does not trace the calls of a request through services.`]],slot:0,evidence:[`xray|For any traced request to your application, you can see detailed information not only about the request and response, but also about calls that your application makes to downstream AWS resources, microservices, databases, and web APIs.`,`xray|Use the trace map to identify bottlenecks, latency spikes, and other issues to solve to improve the performance of your applications.`]}),e({id:`tide-gauges-007`,building:`tide-gauges`,bullets:[`2.2-K12`],d:2,stem:`A company wants to learn which IAM user deleted a security group rule last week. It also wants to be notified in the future when a security group is configured in a way that violates company policy. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Search the AWS CloudTrail event history for the security group API call and read which principal made it`,`CloudTrail records actions taken by a user, role or AWS service as events, including actions in the console, CLI and SDKs.`],[`Create an AWS Config rule that evaluates security group configurations and sends a notification on a violation`,`Config rules evaluate resource configurations, flag noncompliant resources and send a notification.`]],wrong:[[`Create an Amazon CloudWatch alarm on the CPUUtilization metric of the instances that use the security group`,`CPU utilization says nothing about who changed a rule or whether a configuration is allowed.`],[`Turn on AWS X-Ray tracing for the applications that run on the instances behind the security group`,`X-Ray traces the requests that an application serves and does not record who changed a setting.`],[`Build a CloudWatch dashboard of the network metrics of the instances that use the security group`,`A dashboard shows network performance and neither identifies who made a change nor evaluates a configuration.`]],slots:[1,4],evidence:[`cloudtrail-what-is|Actions taken by a user, role, or an AWS service are recorded as events in CloudTrail.`,`cloudtrail-what-is|Event history – The Event history provides a viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region.`,`config-what-is|When AWS Config detects that a resource violates the conditions in one of your rules, AWS Config flags the resource as noncompliant and sends a notification.`]}),t({id:`tide-gauges-008`,building:`tide-gauges`,bullets:[`2.2-K12`],d:2,stem:`A serverless API uses Amazon API Gateway and an AWS Lambda function that calls other AWS services. The team wants trace segments for the function invocations and a service map of the calls, with the LEAST effort. What should the team do?`,correct:[`Turn on active tracing for the Lambda function so that Lambda sends trace data to AWS X-Ray`,`With active tracing Lambda creates trace segments for invocations, and the console adds the permissions the function needs.`],wrong:[[`Run the X-Ray daemon on an Amazon EC2 instance and make the function send its trace segments to it`,`With active tracing Lambda creates and sends the trace segments itself, so a separate daemon instance is unnecessary extra work to build and maintain.`],[`Create an AWS CloudTrail trail for the function and query the recorded events to build the service map`,`CloudTrail records API actions as events and does not trace the latency of the calls a request makes.`],[`Set the X-Ray sampling rate of the function to 100 percent in the function configuration of the console`,`The sampling rate for Lambda functions cannot be configured, so this setting cannot be changed.`]],slot:1,evidence:[`lambda-xray|With Active tracing, Lambda automatically creates trace segments for Event Function invocations and sends them to X-Ray.`,`lambda-xray|When you activate tracing in the Lambda console, Lambda adds the required permissions to your Event Function's execution role.`,`lambda-xray|You can't configure the X-Ray sampling rate for your functions.`]}),t({id:`tide-gauges-009`,building:`tide-gauges`,bullets:[`2.2-K12`],d:3,stem:`A company runs microservices on Amazon EC2 instances. It wants a trace map that shows the calls each service makes to downstream AWS resources, databases and web APIs, to find latency spikes. Which approach produces the trace data that the map needs?`,correct:[`Instrument the application with an X-Ray SDK that sends segment documents to the X-Ray daemon on each instance`,`Instrumenting sends trace data for incoming and outbound requests, and the daemon buffers the segments and uploads them to X-Ray.`],wrong:[[`Turn on AWS CloudTrail data events for the tables and buckets that the services use and read the recorded events`,`CloudTrail data events record API activity on resources and do not trace the latency of the calls in a request.`],[`Create Amazon CloudWatch alarms on CPUUtilization and NetworkIn for each instance and chart them on a dashboard`,`Instance load metrics show how busy each instance is and not which downstream call is slow.`],[`Turn on AWS Config recording for the instances and security groups and review the configuration timeline`,`Configuration history shows how resources changed over time, and it contains no data about the calls of a request.`]],slot:2,evidence:[`xray|Instrumenting your application involves sending trace data for incoming and outbound requests and other events within your application, along with metadata about each request.`,`xray|Instead of sending trace data directly to X-Ray, each client SDK sends JSON segment documents to a daemon process listening for UDP traffic.`,`xray|The X-Ray daemon buffers segments in a queue and uploads them to X-Ray in batches.`]}),t({id:`tide-gauges-010`,building:`tide-gauges`,bullets:[`2.2-K12`],d:2,stem:`A company monitors only the HTTP 5XX error count at the edge of its three-tier application. Last month the database tier was exhausted for twenty minutes before customers noticed, because the edge alarm never fired. The company wants earlier warning of degradation anywhere in the workload. Which approach is BEST?`,correct:[`Define key metrics for the front-end, business logic and storage tiers in Amazon CloudWatch and set alarm thresholds on each`,`All components should be monitored, with key metrics defined and thresholds set that invoke alarm events.`],wrong:[[`Lower the threshold of the edge 5XX alarm so that even a single error raises the alarm at the edge of the application`,`The alarm still watches only the external interface, so a failing database tier can be missed.`],[`Turn on AWS CloudTrail for the database tier and send an alert on each management event that is recorded`,`CloudTrail records actions taken in the account and does not measure whether the database tier is degrading.`],[`Record the database instances with AWS Config and review the configuration timeline each morning for changes`,`A configuration history shows changes, not a database that is running out of capacity, and a daily review is late.`]],slot:3,evidence:[`waf-monitor-components|All components of your workload should be monitored, including the front-end, business logic, and storage tiers.`,`waf-monitor-components|Define key metrics, describe how to extract them from logs (if necessary), and set thresholds for invoking corresponding alarm events.`,`waf-monitor-components|Only monitoring external interfaces to your workload.`]}),t({id:`tide-gauges-011`,building:`tide-gauges`,bullets:[`2.2-S3`],d:1,stem:`A web application runs on instances behind an Application Load Balancer. The company wants an alarm when one or more registered targets are failing their health checks, and it wants to avoid alarms from a single blip. Which metric and alarm setup is MOST appropriate?`,correct:[`UnHealthyHostCount with the Minimum statistic, alarming on a non-zero value for more than one data point`,`UnHealthyHostCount is the number of targets considered unhealthy, and requiring more than one data point avoids a single blip.`],wrong:[[`The RequestCount metric of the load balancer, alarming when the number of requests falls to zero`,`A request count shows traffic volume and does not show whether any registered target is failing health checks.`],[`The TargetResponseTime metric of the load balancer, alarming when the average rises above one second`,`Response time measures latency of responses, and a target can fail its health check without a change in it.`],[`The ActiveConnectionCount metric of the load balancer, alarming when it drops below the usual daily level`,`Connection counts follow the load from clients and do not report which targets are unhealthy.`]],slot:0,evidence:[`alb-metrics|We recommend you monitor for non-zero UnHealthyHostCount in the Minimum statistic, and alarm on non-zero value for more than one data point.`,`alb-metrics|The number of targets that are considered unhealthy.`]}),t({id:`tide-gauges-012`,building:`tide-gauges`,bullets:[`2.2-S3`],d:2,stem:`An online store needs customers to be able to place orders 99.95 percent of the time. Its team alarms only on the CPU utilization of the web servers, and twice customers could not place orders while CPU looked normal. The company wants metrics that reflect the business requirement and show problems earlier. Which approach is BEST?`,correct:[`Publish a custom CloudWatch metric for orders successfully processed per minute and alarm when it drops`,`A metric tied to a business outcome, such as orders processed per minute, can indicate workload issues faster than CPU utilization.`],wrong:[[`Add CloudWatch alarms for the memory and disk usage of the same web servers, next to the CPU alarm`,`These are still technical resource metrics and can look normal while customers cannot place orders.`],[`Lower the threshold of the existing CPU utilization alarm to twenty percent on all of the web servers in the Region`,`A lower CPU threshold produces more alarms without measuring whether orders are being placed.`],[`Review the AWS CloudTrail event history for the order API calls at the start of each business day`,`A daily review finds problems late, and it does not turn the order outcome into a metric with an alarm.`]],slot:1,evidence:[`waf-monitor-components|For example, a metric related to business outcomes such as the number of orders successfully processed per minute, can indicate workload issues faster than technical metric, such as CPU Utilization.`,`waf-monitor-components|Ensure metrics are relevant to the key performance indicators (KPIs) of your workload, and use metrics and logs to identify early warning signs of service degradation.`]}),t({id:`tide-gauges-013`,building:`tide-gauges`,bullets:[`2.2-S3`],d:2,stem:`A business-to-business portal receives almost no traffic between 22:00 and 06:00, but its contract requires it to be available in those hours. Today the team relies on real user traffic and simple health checks, and it learns about overnight outages from customers in the morning. The company wants to find issues before customers do, with the LEAST operational overhead. What should it do?`,correct:[`Create CloudWatch Synthetics canaries that run on a schedule, simulate user actions and alarm on failure`,`Synthetic monitoring performs the same actions as a customer, so the experience is verified even when no customers are using the workload.`],wrong:[[`Increase how often the load balancer health checks run so that failures are noticed a few seconds sooner`,`Simple health checks do not perform the actions of a customer, so they miss failures of the user journey.`],[`Rely on AWS X-Ray traces of real requests and alarm when a segment shows an error or a fault`,`With almost no overnight requests there is little to trace, so outages go unnoticed during those hours.`],[`Run a script on an Amazon EC2 instance in the same VPC that calls the portal and writes the results to a log`,`This is custom code to build and operate, and it checks the portal from inside the workload instead of from outside.`]],slot:2,evidence:[`waf-monitor-components|Synthetic monitoring follows the same routes and perform the same actions as a customer, which makes it possible for you to continually verify your customer experience even when you don't have any customer traffic on your workloads.`,`waf-monitor-components|By using synthetic transactions, you can discover issues before your customers do.`,`cw-what-is|CloudWatch Synthetics complements this by enabling you to proactively monitor your endpoints and APIs through configurable scripts called canaries that simulate user behavior and alert you to availability issues or performance degradation before they impact real users.`]}),t({id:`tide-gauges-014`,building:`tide-gauges`,bullets:[`2.2-S3`],d:3,stem:`A workload is designed for 99.99 percent availability and has hard dependencies on two other independent systems that are each designed for 99.99 percent availability. The team wants to know what the workload can theoretically achieve, so that it can choose the right availability metric. Which conclusion is MOST accurate?`,correct:[`The workload can theoretically achieve about 99.97 percent, because the availabilities of the hard dependencies multiply`,`For a hard dependency, the invoking system availability is the product of the availabilities, 99.99% × 99.99% × 99.99%, or 99.97%.`],wrong:[[`The workload can theoretically achieve 99.99 percent, because it is as available as its least available component`,`This ignores that an interruption in a hard dependency directly interrupts the invoking system, so availabilities multiply.`],[`The workload can theoretically achieve about 99.9999999999 percent, because 100 percent minus the product of the failure rates applies`,`That calculation is for independent redundant components, but hard dependencies are not redundant copies of each other.`],[`The workload achieves the average of the three availabilities, which is 99.99 percent`,`Hard dependencies do not average out: an interruption in any of them interrupts the invoking system, so the availabilities multiply.`]],slot:3,evidence:[`waf-availability|Where such hard dependencies occur, the invoking system’s availability is the product of the dependent systems’ availabilities.`,`waf-availability|99.99% × 99.99% × 99.99% = 99.97%`,`waf-availability|When a system involves the use of independent, redundant components (for example, redundant resources in different Availability Zones), the theoretical availability is computed as 100% minus the product of the component failure rates.`]}),e({id:`tide-gauges-015`,building:`tide-gauges`,bullets:[`2.2-S3`],d:2,stem:`A company runs a web tier behind an Application Load Balancer and wants alarms that show customers are not being served successfully by the registered targets. Which TWO Amazon CloudWatch metrics are the BEST choices? (Choose two.)`,correct:[[`UnHealthyHostCount, with the Minimum statistic and an alarm on a non-zero value for more than one data point`,`It counts the targets that are considered unhealthy, which shows that capacity is failing health checks.`],[`HTTPCode_Target_5XX_Count, with the Sum statistic`,`It counts the server error responses generated by the targets themselves, which shows requests that are failing.`]],wrong:[[`RequestCount, because it reports how many requests the load balancer processed`,`A count of requests shows traffic volume and does not say whether those requests succeeded.`],[`NewConnectionCount, because it reports new TCP connections made to the load balancer`,`It reports the connections that are established and says nothing about failing targets or responses.`],[`ProcessedBytes, because it reports the bytes processed by the load balancer`,`It measures the volume of data processed, which can stay normal while targets fail.`]],slots:[2,4],evidence:[`alb-metrics|We recommend you monitor for non-zero UnHealthyHostCount in the Minimum statistic, and alarm on non-zero value for more than one data point.`,`alb-metrics|HTTPCode_Target_2XX_Count, HTTPCode_Target_3XX_Count, HTTPCode_Target_4XX_Count, HTTPCode_Target_5XX_Count The number of HTTP response codes generated by the targets.`,`alb-metrics|The total number of new TCP connections established from clients to the load balancer and from the load balancer to targets.`]}),t({id:`tide-gauges-016`,building:`tide-gauges`,bullets:[`2.2-K10`],d:1,tags:[`mock-reserve`],stem:`An operations team wants one AWS service that inspects the environment and recommends where to save money, improve availability and performance, and close security gaps, and that also checks whether usage is more than 80 percent of a service quota. Which service BEST meets these requirements?`,correct:[`AWS Trusted Advisor, which inspects the environment and flags quota usage above a threshold`,`Trusted Advisor makes recommendations to save money, improve availability and performance, or close security gaps, and its service limit checks flag usage of more than 80 percent of a quota.`],wrong:[[`AWS Config, which keeps the configuration history of resources and evaluates it against rules`,`Config evaluates configuration settings against rules and does not recommend cost savings or alert on quota usage.`],[`AWS CloudTrail, which records the actions taken by users, roles and services as events in the account`,`CloudTrail records who did what and does not inspect the environment for recommendations or quota usage.`],[`AWS X-Ray, which collects data about requests and builds a trace map of the calls that were made`,`X-Ray traces application requests and does not make account-level recommendations or report quota usage.`]],slot:0,evidence:[`trusted-advisor|Trusted Advisor inspects your AWS environment, and then makes recommendations when opportunities exist to save money, improve system availability and performance, or help close security gaps.`,`trusted-advisor-service-limits|Checks for usage that is more than 80% of the CloudFormation stacks quota.`]}),t({id:`tide-gauges-017`,building:`tide-gauges`,bullets:[`2.2-S3`],d:2,tags:[`mock-reserve`],stem:`A company runs a request-driven API whose traffic varies widely, with very few requests overnight. The company wants an availability metric that reflects what customers experience and that stays meaningful in quiet periods. Which approach is BEST?`,correct:[`Count successful and failed requests in one-minute periods and compute the percentage of successful requests`,`Counting requests is often easier than timing availability, and a period with no requests is counted as fully available.`],wrong:[[`Measure the percentage of time that the Amazon EC2 instances of the API are in the running state`,`A running instance can still fail requests, so this does not reflect what customers experience.`],[`Use the average CPU utilization of the API instances over the month as the measure of availability`,`CPU utilization shows how busy the instances are and does not show whether requests succeed.`],[`Count only unscheduled outages and exclude planned maintenance windows from the total time in the calculation`,`This is not advised, because users also want to use the service during scheduled downtime.`]],slot:1,evidence:[`waf-availability|For your service it may be easier to count successful and failed requests instead of “time available for use”.`,`waf-availability|If no requests are received in a given period it is counted at 100% available for that time.`,`waf-availability|However, this is not advised, as your users will likely want to use your service during these times.`]})],_=Object.values(Object.assign({"../../content/questions/harbor/blueprint-hall.ts":n,"../../content/questions/harbor/cache-edge-breakwater.ts":r,"../../content/questions/harbor/cargo-hall.ts":i,"../../content/questions/harbor/container-dock.ts":a,"../../content/questions/harbor/disaster-bunker.ts":o,"../../content/questions/harbor/durable-dock.ts":s,"../../content/questions/harbor/island-charts.ts":c,"../../content/questions/harbor/legacy-wharf.ts":l,"../../content/questions/harbor/message-quay.ts":u,"../../content/questions/harbor/purpose-built-workshop.ts":d,"../../content/questions/harbor/rebuild-yard.ts":f,"../../content/questions/harbor/scaling-floodgate.ts":p,"../../content/questions/harbor/serverless-mill.ts":m,"../../content/questions/harbor/single-point-watch.ts":h,"../../content/questions/harbor/tide-gauges.ts":g})).flat();export{_ as questions};